  AvgCommunicate_100438_Content_14 = {
    Text = "Ну пожалуйста? Пожалуйста?"
  },
  AvgCommunicate_100438_Content_15 = {
    Text = "Бесплатная модель, помогающая тебе в погоне за идеальным искусством! Где ещё ты найдёшь такую покладистую модель?"
