  },
  AvgCommunicate_123722_Content_6 = {
    Text = "Или переживаешь, что мне будет трудно привыкнуть к превращению из «человека» в «пробуждённую»?"
  },
  AvgCommunicate_123722_Content_7 = {
    Text = "И то, и другое. Ведь такое... для кого угодно было бы непросто."
  },
  AvgCommunicate_123722_Content_8 = {
    Text = "...Я определённо не в состоянии понять ход твоих мыслей."
  },
  AvgCommunicate_123722_Content_9 = {
    Text = "Мне всё равно! Потому что неважно, какой я стану — Мося остаётся Мосей!"
