  AvgCommunicate_123722_Option_3 = {
    Text = "Тогда я спокоен."
  },
  AvgCommunicate_123722_Option_7 = {
    Text = "И то, и другое."
  },
  AvgCommunicate_126998_Content_1 = {
    Text = "Рамона, ты... Правда не хочешь ещё раз подумать?"
  },
  AvgCommunicate_126998_Content_10 = {
    Text = "Да, «я»."
  },
  AvgCommunicate_126998_Content_11 = {
    Text = "…Мне связаться с Клементиной?"
  },
  AvgCommunicate_126998_Content_12 = {
    Text = "Нет, не стоит беспокоить этого психотерапевта."
  },
  AvgCommunicate_126998_Content_13 = {
    Text = "«Я», или, точнее, «мы» — все «Рамоны» на всей временной линии."
  },
  AvgCommunicate_126998_Content_14 = {
    Text = "С помощью твоей силы, в тот миг, когда я достигла «конца», мне удалось перезаписать себя обратно в «Начало»."
  },
  AvgCommunicate_126998_Content_15 = {
    Text = "Поначалу я, как и ты, предполагала, что парадокс и искажение мгновенно поглотят моё существование, и лишь путём непрерывной саморетроспекции удастся с трудом сохранить сознание и форму."
  },
  AvgCommunicate_126998_Content_16 = {
    Text = "После чего ты будешь вечно жить в изнеможении, каждый миг напрягая все силы, чтобы не дать своей сущности рассеяться…"
  },
  AvgCommunicate_126998_Content_17 = {
    Text = "Поэтому я отвергла твои первые девятнадцать предложений."
  },
  AvgCommunicate_126998_Content_18 = {
    Text = "Даже в этот раз я… нехотя согласилась на этот план лишь после того, как ты сказал, что можно выполнить «откат состояния»."
  },
  AvgCommunicate_126998_Content_19 = {
    Text = "Да, но лишь после успеха плана я осознала, что парадокс самости проистекает из конфликта разума и тела, а для существа, давно преодолевшего поток времени…"
  },
  AvgCommunicate_126998_Content_2 = {
    Text = "Не нужно лишних слов, Страж Тайн."
  },
  AvgCommunicate_126998_Content_20 = {
    Text = "Я уже давно завершила объединение на всех временных линиях."
  },
  AvgCommunicate_126998_Content_21 = {
    Text = "«Мы» разделим между собой последствия парадокса, а я буду действовать от имени всех «Рамон». Бесчисленные временные линии уже сошлись во мне."
  },
  AvgCommunicate_126998_Content_22 = {
    Text = "В этот миг я — чудо временной линии, сингулярность, где бесконечность сходится в единое."
  },
  AvgCommunicate_126998_Content_23 = {
    Text = "Отныне я предоставлю тебе всю мощь индивидуума по имени «Рамона»."
  },
  AvgCommunicate_126998_Content_24 = {
    Text = "Я буду ждать зова — из любого времени."
  },
  AvgCommunicate_126998_Content_3 = {
    Text = "Я пересекла все времена и не нашла иного ответа."
  },
  AvgCommunicate_126998_Content_4 = {
    Text = "Благодаря тебе я наконец смогла сделать тот последний шаг."
  },
  AvgCommunicate_126998_Content_5 = {
    Text = "Но это слишком опасно! Я не понимаю, зачем ты... зачем идти на такое..."
