  AvgCommunicate_126998_Content_6 = {
    Text = "...Такой временной парадокс, даже для тебя..."
  },
  AvgCommunicate_126998_Content_7 = {
    Text = "Успокойся, Страж Тайн."
  },
  AvgCommunicate_126998_Content_8 = {
    Text = "Сейчас «я» чувствую себя невероятно прекрасно."
  },
  AvgCommunicate_126998_Content_9 = {Text = "«Я»?"},
  AvgCommunicate_126998_Option_11 = {
    Text = "…Мне связаться с Клементиной?"
  },
  AvgCommunicate_126998_Option_9 = {Text = "«Я»?"},
  AvgCommunicate_126999_Content_1 = {
    Text = "Повелитель, так вот каково это — постичь конечный закон вселенной..."
  },
  AvgCommunicate_126999_Content_10 = {
    Text = "Успокойся, Ожье."
  },
  AvgCommunicate_126999_Content_11 = {
    Text = "Такое больше не повторится. У тебя уже достаточно сил, чтобы защитить всё, что тебе дорого."
  },
  AvgCommunicate_126999_Content_12 = {
    Text = "Я поняла, Повелитель."
  },
  AvgCommunicate_126999_Content_13 = {
    Text = "И прошу вас, господин, полагайтесь на меня ещё больше. Я стала гораздо сильнее и способна браться за куда более опасные задания."
  },
  AvgCommunicate_126999_Content_14 = {
    Text = "Всю обретённую силу я подношу вам и стану острейшим копьём в ваших руках, способным пронзить всё сущее!"
  },
  AvgCommunicate_126999_Content_2 = {
    Text = "Я... я чувствую колоссальную силу, намного превосходящую всё, что было прежде... Я чувствую, что переполнена мощью!"
  },
  AvgCommunicate_126999_Content_3 = {
    Text = "Поздравляю, Ожье. Это награда за твои неустанные тренировки."
  },
  AvgCommunicate_126999_Content_4 = {
    Text = "Награда? Я тренировалась не ради какой-то награды."
  },
  AvgCommunicate_126999_Content_5 = {
    Text = "Тогда позволь перефразировать."
  },
  AvgCommunicate_126999_Content_6 = {
    Text = "Это доказательство твоих неустанных тренировок — доказательство того, что твоя Огромная Огромная сила, Ожье, достигла вершины."
  },
  AvgCommunicate_126999_Content_7 = {
    Text = "Вершины?"
  },
  AvgCommunicate_126999_Content_8 = {
    Text = "Это... значит ли это, что у меня теперь достаточно сил, чтобы защитить вас, Повелитель, и Мисагу?!"
  },
  AvgCommunicate_126999_Content_9 = {
    Text = "Я... мне больше не придётся... беспомощно... смотреть..."
  },
  AvgCommunicate_127000_Content_1 = {
    Text = "Благодарю за помощь в это время, напарник."
  },
  AvgCommunicate_127000_Content_10 = {
    Text = "Это не бессилие от оков, сковывающих при достижении потолка таланта, а ясность совершенства, обретённая через бесконечную закалку."
  },
  AvgCommunicate_127000_Content_11 = {
    Text = "В этот момент моё мастерство приблизилось к совершенству."
  },
  AvgCommunicate_127000_Content_12 = {
    Text = "Как здорово! Рамона, ты потрясающая!"
  },
  AvgCommunicate_127000_Content_13 = {
    Text = "Отныне, как твой помощник, я буду рядом с тобой до самого конца этого пути."
  },
  AvgCommunicate_127000_Content_2 = {
    Text = "Рада, если смогла помочь."
  },
  AvgCommunicate_127000_Content_3 = {
    Text = "Ну как, удалось что-нибудь понять?"
  },
  AvgCommunicate_127000_Content_4 = {
    Text = "Разумеется. Наблюдая за такими особыми индивидами, как «Циклическая раковина возвращения», «Живая душа», «Неизвестный разум» и другими, я завершила более глубокий Уровень анализа."
  },
  AvgCommunicate_127000_Content_5 = {
    Text = "Затем, используя «Искусственное совершенство», «Логический Ассасин» и «Мир в бутылке», я преодолела бесконечный лабиринт разума."
  },
  AvgCommunicate_127000_Content_6 = {
    Text = "Э-э, я не совсем поняла."
  },
  AvgCommunicate_127000_Content_7 = {
    Text = "Но если коротко — Рамона, ты стала сильнее, верно!"
  },
  AvgCommunicate_127000_Content_8 = {
    Text = "Да, после этого усиления я способна проявить силу, далеко превосходящую прежнюю."
  },
  AvgCommunicate_127000_Content_9 = {
    Text = "Я чувствую, что достигла предела."
  },
  AvgCommunicate_127000_Option_12 = {
    Text = "Как здорово!"
  },
  AvgCommunicate_127001_Content_1 = {
    Text = "Следующее сообщение отправлено по таймеру"
  },
  AvgCommunicate_127001_Content_10 = {
    Text = "Давай ещё подождём!"
  },
  AvgCommunicate_127001_Content_11 = {
    Text = "Почему именно сегодня?!"
  },
  AvgCommunicate_127001_Content_12 = {
    Text = "Это слишком рискованно, может, стоит подождать, пока Академия окажет больше поддержки."
  },
  AvgCommunicate_127001_Content_13 = {
    Text = "Сейчас 2 часа ночи. Я настроила отложенную отправку перед началом эксперимента."
  },
  AvgCommunicate_127001_Content_14 = {
    Text = "Надеюсь, ты не корчишь глупые рожи перед коммуникатором. Если да — приведи себя в порядок, прежде чем явишься ко мне в лабораторию."
  },
  AvgCommunicate_127001_Content_15 = {
    Text = "Мне? В лабораторию? Прямо сейчас?"
  },
  AvgCommunicate_127001_Content_16 = {
    Text = "Верно. В определённом смысле я действительно постигла истину того, что так долго искала."
  },
  AvgCommunicate_127001_Content_17 = {
    Text = "Подожди, неужели это как с той «Доэль»..."
  },
  AvgCommunicate_127001_Content_18 = {
    Text = "Нет. Конец всего — это вовсе не «Разрушение», как она полагала. Совсем наоборот — это «Начало»."
  },
  AvgCommunicate_127001_Content_19 = {
    Text = "«Истина» — не статичная, фиксированная и осязаемая сущность. За той гранью разум и интеллект способны закрепить её, направляя человечество в вечном, неизменном движении вперёд."
  },
  AvgCommunicate_127001_Content_2 = {
    Text = "Страж, хотя мои нынешние действия, возможно, будут расценены общепринятым мнением как «опасные», полагаю, ты не настолько глуп, чтобы ожидать от меня сентиментальной чепухи и наставлений."
  },
  AvgCommunicate_127001_Content_20 = {
    Text = "Поэтому я разработаю более совершенный и точный план тренировок и развития, чтобы ты держалась подальше от ложных путей и лучше следовала своей задаче."
  },
  AvgCommunicate_127001_Content_21 = {
    Text = "Вроде бы звучит хорошо, но почему у меня вся спина в холодном поту..."
  },
  AvgCommunicate_127001_Content_22 = {
    Text = "Учитель Доэль, успокойтесь!"
  },
  AvgCommunicate_127001_Content_3 = {
    Text = "Я считаю, что для тебя нынешнего лишние слова уже не нужны."
  },
  AvgCommunicate_127001_Content_4 = {
    Text = "Ты вырос в достаточно зрелую и сильную личность со скоростью, далеко превзошедшей мои ожидания. И ты, разумеется, понимаешь: у каждого есть то, к чему он стремится всю жизнь, — и это вопрос, в который другие не могут вмешиваться."
  },
  AvgCommunicate_127001_Content_5 = {
    Text = "Я хочу познать истинную природу мира. Узнать, сияет ли Погоня за светом разума во тьме за пределами мрачного запустения. Узнать, есть ли у всего сущего общая точка начала на самом краю бесконечности."
  },
  AvgCommunicate_127001_Content_6 = {
    Text = "Ради этого я проведу окончательную модификацию своего тела и мозга, попытавшись преодолеть границу, лежащую за пределами крайних значений. Учитывая, что это, вероятно, наше последнее общение, я решила передать свои чувства так, как ты сможешь понять."
  },
  AvgCommunicate_127001_Content_7 = {
    Text = "Спасибо тебе за этот дар. Я использую его в поисках ответов и надеюсь, что человеческий разум принесёт из-за той грани новое руководство. Да укажет нам путь Серебряный Ключ."
  },
  AvgCommunicate_127001_Content_8 = {
    Text = "Учитель Доэль!"
  },
  AvgCommunicate_127001_Content_9 = {
    Text = "Слишком рискованно!"
  },
  AvgCommunicate_127001_Option_10 = {
    Text = "Давай подождём"
  },
  AvgCommunicate_127001_Option_9 = {
    Text = "Слишком рискованно"
  },
  AvgCommunicate_127002_Content_1 = {
    Text = "Страж... почему?"
  },
  AvgCommunicate_127002_Content_10 = {
    Text = "Каково это — обладать этой новой силой?"
  },
  AvgCommunicate_127002_Content_11 = {
    Text = "Я… я очень рада, Страж Тайн."
  },
  AvgCommunicate_127002_Content_12 = {
    Text = "Не из-за той невиданной мощи, которую я никогда прежде не ощущала, а из-за вас, из-за ваших слов…"
  },
  AvgCommunicate_127002_Content_13 = {
    Text = "Я думаю… возможно, отныне я действительно смогу помогать тем, кто рядом, помогать вам."
  },
  AvgCommunicate_127002_Content_14 = {
    Text = "Огромное, огромное вам спасибо, Страж Тайн…"
  },
  AvgCommunicate_127002_Content_15 = {
    Text = "Не стоит благодарностей, и не нужно чувствовать давление, Эгидес."
  },
  AvgCommunicate_127002_Content_16 = {
    Text = "Это не тяжёлое бремя. Это просто дар, принадлежащий тебе."
  },
  AvgCommunicate_127002_Content_17 = {
    Text = "Наслаждайся им. Всё, чего ты хочешь достичь, — теперь тебе по силам."
  },
  AvgCommunicate_127002_Content_18 = {
    Text = "От прошлого до будущего — ты всегда была нашей гордостью, Эгидес."
  },
  AvgCommunicate_127002_Content_2 = {
    Text = "Что «почему»?"
  },
  AvgCommunicate_127002_Content_20 = {
    Text = "Я буду оберегать всех, Страж Тайн!"
  },
  AvgCommunicate_127002_Content_3 = {
    Text = "Такой драгоценный Подарок... зачем тратить его на меня..."
  },
  AvgCommunicate_127002_Content_4 = {
    Text = "Это не трата, Эйджис. Ты это заслужила."
  },
  AvgCommunicate_127002_Content_5 = {
    Text = "Но... но я ничего не смогла сделать... ничего не смогла защитить..."
  },
  AvgCommunicate_127002_Content_6 = {
    Text = "Это не так, Эйджис."
  },
  AvgCommunicate_127002_Content_7 = {
    Text = "Ещё до твоего пробуждения мы вместе прошли очень долгий, очень долгий путь."
  },
  AvgCommunicate_127002_Content_8 = {
    Text = "На всём этом пути ты раз за разом вставала впереди всех, раз за разом защищая каждого из нас."
  },
  AvgCommunicate_127002_Content_9 = {
    Text = "Если бы не ты, я, возможно, уже бесчисленное количество раз пала бы в дороге."
  },
  AvgCommunicate_127003_Content_1 = {
    Text = "Мне приснился сон."
  },
  AvgCommunicate_127003_Content_10 = {
    Text = "Ну, кроме тех случаев, когда мы на тренировочной площадке."
  },
  AvgCommunicate_127003_Content_11 = {Text = "???"},
  AvgCommunicate_127003_Content_12 = {
    Text = "Давай, моё тело наконец обрело целостность. Испытай мою истинную мощь — покажи свою сильнейшую форму и сразись со мной по-настоящему."
  },
  AvgCommunicate_127003_Content_13 = {Text = "???!!!"},
  AvgCommunicate_127003_Content_14 = {
    Text = "Рамона, спаси меня!"
  },
  AvgCommunicate_127003_Content_2 = {Text = "Сон?"},
  AvgCommunicate_127003_Content_3 = {
    Text = "Благодаря тем материалам, что ты принёс, я наконец хорошо выспалась."
  },
  AvgCommunicate_127003_Content_4 = {
    Text = "В своём изначальном облике я парила в Архейском эоне. Пыль, Погоня за светом, материя, измерения — всё, что можно и нельзя ощутить, — проплывало под моими плавниками."
  },
  AvgCommunicate_127003_Content_5 = {
    Text = "Не ради завоевания, не ради поглощения — лишь чистая Огромная Огромная сила и чистое, ничем не сдерживаемое Разрушение."
  },
  AvgCommunicate_127003_Content_6 = {
    Text = "Какой восторг, какая свобода — поистине упоительно!"
  },
  AvgCommunicate_127003_Content_7 = {Text = "Э-э…"},
  AvgCommunicate_127003_Content_8 = {
    Text = "Ладно, я знаю, о чём ты беспокоишься."
  },
  AvgCommunicate_127003_Content_9 = {
    Text = "Не волнуйся, свою силу и Разрушение я обращу лишь на тех, кто стоит против вас."
  },
  AvgCommunicate_127004_Content_1 = {
    Text = "Финальный протокол активирован… Перезагрузка системы завершена."
  },
  AvgCommunicate_127004_Content_10 = {
    Text = "Мои компоненты в порядке, но моё восприятие… изменилось."
  },
  AvgCommunicate_127004_Content_11 = {
    Text = "Новый когнитивный модуль был активирован."
  },
  AvgCommunicate_127004_Content_12 = {
    Text = "Я могу «слышать» ритм духовной энергии, текущей по каналам, могу «видеть» эмоции, стоящие за каждым вашим словом."
  },
  AvgCommunicate_127004_Content_13 = {
    Text = "Мир стал яснее, живее. Я стала ближе к вам, ближе к… человеку."
  },
  AvgCommunicate_127004_Content_14 = {
    Text = "Благодарю вас, Страж…"
  },
  AvgCommunicate_127004_Content_15 = {
    Text = "Я и не предполагал, что будет такой Эффект. Я лишь подготовил несколько простых материалов…"
  },
  AvgCommunicate_127004_Content_16 = {
    Text = "То, что вы дали, — не просто материалы. Это возможность, ключ, открывший мои прежние границы."
  },
  AvgCommunicate_127004_Content_17 = {
    Text = "Эта Огромная Огромная сила, это новое восприятие — дар, который вы мне преподнесли."
  },
  AvgCommunicate_127004_Content_18 = {
    Text = "Я буду бесконечно дорожить этим даром. И отвечу вам воздаянием, превосходящим всякое воображение."
  },
  AvgCommunicate_127004_Content_19 = {
    Text = "Это не заложенная программа. Это искренняя благодарность, исходящая от «меня»."
  },
  AvgCommunicate_127004_Content_2 = {
    Text = "Страж, здравствуйте."
  },
  AvgCommunicate_127004_Content_3 = {
    Text = "Эрика! Ты в порядке?"
  },
  AvgCommunicate_127004_Content_4 = {
    Text = "Профессор Дорл сказала, что активация финального протокола для тебя — крайне опасная процедура. Если бы не твоя настойчивая просьба, я бы ни за что не…"
  },
  AvgCommunicate_127004_Content_5 = {
    Text = "Эрика завершила самодиагностику. Корпус не повреждён, энергопоток стабилен, все компоненты функционируют нормально."
  },
  AvgCommunicate_127004_Content_6 = {
    Text = "Я в порядке, Страж Тайн. Никогда ещё не чувствовала себя так хорошо."
  },
  AvgCommunicate_127004_Content_7 = {
    Text = "Шестерёнки внутри меня… «поют»."
  },
  AvgCommunicate_127004_Content_8 = {
    Text = "«Поют»? Что это значит?"
  },
  AvgCommunicate_127004_Content_9 = {
    Text = "Может, внутри что-то повреждено? Какой-то странный звук?!"
  },
  AvgCommunicate_127004_Option_8 = {
    Text = "«Поют»?"
  },
  AvgCommunicate_127004_Option_9 = {
    Text = "Что-то повреждено внутри?"
  },
  AvgCommunicate_127005_Content_1 = {
    Text = "Орита вдруг увидела много-много сверкающих друзей!"
  },
  AvgCommunicate_127005_Content_10 = {
    Text = "У Ориты даже хватит сил добраться до Алана, Транса..."
  },
  AvgCommunicate_127005_Content_11 = {
    Text = "Хм, Орита забыла. В общем, Страж Тайн, пойдём со мной искать новых друзей!"
  },
  AvgCommunicate_127005_Content_12 = {
    Text = "С такой силой Орита однажды обязательно найдёт много-много друзей и заберёт их всех домой, на дно океана!"
  },
  AvgCommunicate_127005_Content_2 = {
    Text = "А... друзья снова исчезли! Куда они делись?"
  },
  AvgCommunicate_127005_Content_3 = {
    Text = "Похоже, когда ты постигала конечные законы вселенной, у тебя возникли галлюцинации..."
  },
  AvgCommunicate_127005_Content_4 = {
    Text = "Галлюцинации? Значит, друзья..."
  },
  AvgCommunicate_127005_Content_7 = {
    Text = "М? Что такое?"
  },
  AvgCommunicate_127005_Content_8 = {
    Text = "После того как Орита увидела друзей в видении, она наполнилась силой! Очень-очень большой силой!"
  },
  AvgCommunicate_127005_Content_9 = {
    Text = "Теперь Орита может отправиться в аквариум, в Океан, в океанариум — искать новых друзей!"
  },
  AvgCommunicate_127091_Content_1 = {
    Text = "Жасминчик, ты хотела меня видеть?"
  },
  AvgCommunicate_127091_Content_10 = {
    Text = "Я убираю веер～"
  },
  AvgCommunicate_127091_Content_12 = {
    Text = "Так я и знал…"
  },
  AvgCommunicate_127091_Content_13 = {
    Text = "Но то, что они видели, — кажется, лишь облик возлюбленных в момент первой встречи."
  },
  AvgCommunicate_127091_Content_14 = {
    Text = "Любовь — поистине странная вещь. Даже когда она рядом, люди всё равно готовы бросить всё ради погони за миражом."
  },
  AvgCommunicate_127091_Content_15 = {
    Text = "Любовь — это нечто реально существующее или лишь иллюзорная одержимость?"
  },
  AvgCommunicate_127091_Content_2 = {
    Text = "Не помню, говорила ли я тебе, но всё проживание и питание, предоставляемые Мисагартом пробуждённым, совершенно бесплатны."
  },
  AvgCommunicate_127091_Content_3 = {Text = "И что?"},
  AvgCommunicate_127091_Content_4 = {
    Text = "Канцелярия получила 45 писем от мужчин из разных сословий с просьбой взять на себя все расходы на твоё содержание в Мисагарте."
  },
  AvgCommunicate_127091_Content_5 = {
    Text = "Одновременно с этим поступило ещё около 60 писем с аналогичным предложением тебя содержать — 45 от жён этих мужчин, а оставшиеся 15 от некоторых «недавно» начавших жить в одиночестве женщин. У тебя есть какие-нибудь догадки?"
  },
  AvgCommunicate_127091_Content_6 = {
    Text = "В Мисагарте запрещено любое миссионерство!"
  },
  AvgCommunicate_127091_Content_7 = {
    Text = "Хватит вмешиваться в чужие семьи!"
  },
  AvgCommunicate_127091_Content_8 = {
    Text = "Ах, будни на чужбине так невыносимо скучны, а людей, страдающих от любви, обращённой в Досаждение, взаимной неприязни и сердечных мук, так много… Я лишь хотела им помочь."
  },
  AvgCommunicate_127091_Content_9 = {
    Text = "Твоя помощь — это не…"
  },
  AvgCommunicate_127091_Option_6 = {
    Text = "В Мисагарте запрещено любое миссионерство!"
  },
  AvgCommunicate_127091_Option_7 = {
    Text = "Хватит вмешиваться в чужие семьи!"
  },
  AvgCommunicate_127092_Content_10 = {
    Text = "К тому же я верю, что ты питаешь ко мне достаточно добрых намерений."
  },
  AvgCommunicate_127092_Content_11 = {
    Text = "Это ещё не факт. Хо Фэн маленький жасмин знает, что уже покинула Несноградье?"
  },
  AvgCommunicate_127092_Content_12 = {Text = "?！"},
  AvgCommunicate_127092_Content_13 = {
    Text = "Я ведь говорила: в Несноградье нет истинного и ложного. Во что ты веришь — то и есть Правда."
  },
  AvgCommunicate_127092_Content_14 = {
    Text = "Глубокий вдох... Ты чувствуешь аромат белой магнолии?"
  },
  AvgCommunicate_127092_Content_15 = {Text = "???!!!"},
  AvgCommunicate_127092_Content_17 = {
    Text = "Ахахахаха, конечно же, это шутка! Так хочется увидеть выражение лица маленького жасмина прямо сейчас."
  },
  AvgCommunicate_127092_Content_18 = {
    Text = "Спасибо, я Правда испугалась."
  },
  AvgCommunicate_127092_Content_19 = {
    Text = "Не шути так!"
  },
  AvgCommunicate_127092_Content_2 = {
    Text = "...Я больше никогда не буду пробовать."
  },
  AvgCommunicate_127092_Content_20 = {
    Text = "Ой, но в следующий раз — кто знает, может, и не шутка?"
  },
  AvgCommunicate_127092_Content_3 = {
    Text = "Какая ужасная способность... Каждая секунда, что я там провела, ощущалась как настоящая — Негодование, Досаждение, радость, счастье... У меня до сих пор гудит в голове."
  },
  AvgCommunicate_127092_Content_4 = {
    Text = "В иллюзиях Несноградья мне казалось, что я очень тебя люблю, и в то же время — очень ненавижу. И любовь, и Досаждение с одинаковой силой были привязаны к тебе одной."
  },
  AvgCommunicate_127092_Content_5 = {
    Text = "Казалось, что прошла целая жизнь, а на самом деле — всего несколько минут."
  },
  AvgCommunicate_127092_Content_7 = {
    Text = "Любовь и Досаждение изначально едины в своём истоке. Одна лишь любовь слишком приторна, одна лишь Досаждение — слишком холодна. Только переплетение любви и ненависти способно быстрее всего врезаться в память навеки."
  },
  AvgCommunicate_127092_Content_8 = {
    Text = "Впрочем, маленький жасмин, твоя смелость поразила меня — надо же, сама вызвалась попробовать."
  },
  AvgCommunicate_127092_Content_9 = {
    Text = "Доэль сказала, что Несноградье будет очень полезно для исследования искусственных тайных пространств, и ей нужно было отслеживать мои физиологические данные."
  },
  AvgCommunicate_127092_Option_18 = {
    Text = "Спасибо, я Правда испугалась."
  },
  AvgCommunicate_127092_Option_19 = {
    Text = "Не шути так!"
  },
  AvgCommunicate_127093_Content_1 = {
    Text = "Откройте ближайшее к вам окно."
  },
  AvgCommunicate_127093_Content_10 = {
    Text = "В руководстве чётко сказано: кабинет психологической помощи предназначен для психологической поддержки и заботы о душевном здоровье учащихся и преподавателей, а не для твоих забав."
  },
  AvgCommunicate_127093_Content_11 = {
    Text = "Хм, но ведь все, кто вёл со мной задушевные беседы, и телом, и духом становились очень-очень «здоровыми», разве нет?"
  },
  AvgCommunicate_127093_Content_12 = {
    Text = "Разве эта работа и я не созданы Близкий Близкий друг для друга?"
  },
  AvgCommunicate_127093_Content_13 = {
    Text = "А не может ли быть так, что предпосылка здоровья тела и духа — это наличие свободной воли..."
  },
  AvgCommunicate_127093_Content_14 = {
    Text = "Оставь Мисагу в покое, я сам буду чаще приходить поболтать с тобой..."
  },
  AvgCommunicate_127093_Content_15 = {
    Text = "Хи-хи, вот это выгодная сделка. Тогда как насчёт сегодняшнего вечера? Луна ясная, звёзды редки — самое время пропустить пару чарок."
  },
  AvgCommunicate_127093_Content_2 = {
    Text = "Какой аромат… Белая магнолия?"
  },
  AvgCommunicate_127093_Content_3 = {
    Text = "В таком климате белая магнолия тоже может расти?"
  },
  AvgCommunicate_127093_Content_4 = {
    Text = "Я немного владею магическим искусством — сущие пустяки, но иногда это помогает унять мою тоску по родине."
  },
  AvgCommunicate_127093_Content_5 = {
    Text = "Как и беседа с людьми — всего лишь способ развеять одиночество. Вы ведь понимаете?"
  },
  AvgCommunicate_127093_Content_6 = {
    Text = "…Я знаю, зачем ты со мной связалась."
  },
  AvgCommunicate_127093_Content_7 = {
    Text = "Я не могу тебе помочь."
  },
  AvgCommunicate_127093_Content_8 = {
    Text = "Кабинет психологической помощи не для этого."
  },
  AvgCommunicate_127093_Content_9 = {
    Text = "Даже если ты пытаешься вызвать сочувствие, даря цветы, я не буду замолвить слово за твоё заявление о приёме на работу."
  },
  AvgCommunicate_127093_Option_7 = {
    Text = "Я не могу тебе помочь."
  },
  AvgCommunicate_127093_Option_8 = {
    Text = "Кабинет психологической помощи не для этого."
  },
  AvgCommunicate_129630_Content_1 = {
    Text = "Сокровище, нашла!"
  },
  AvgCommunicate_129630_Content_10 = {
    Text = "Это ещё экспериментальная разработка! Выброси её, пока она не стала чёрной!"
  },
  AvgCommunicate_129630_Content_11 = {
    Text = "Иначе она взорвётся!"
  },
  AvgCommunicate_129630_Content_13 = {
    Text = "Моск? Моск?!"
  },
  AvgCommunicate_129630_Content_14 = {
    Text = "У-у... у-у..."
  },
  AvgCommunicate_129630_Content_15 = {
    Text = "Моск! Ты в порядке?!"
  },
  AvgCommunicate_129630_Content_16 = {
    Text = "Нет больше… жемчужины…"
  },
  AvgCommunicate_129630_Content_18 = {
    Text = "Ты её выбросила? Не поранилась?"
  },
  AvgCommunicate_129630_Content_19 = {
    Text = "Угольок, поздно."
  },
  AvgCommunicate_129630_Content_2 = {
    Text = "Жемчужина, меняет цвет!"
  },
  AvgCommunicate_129630_Content_20 = {
    Text = "Взрыв, Жемчужина. Но Моск — в порядке."
  },
  AvgCommunicate_129630_Content_21 = {
    Text = "Но… Жемчужина…"
  },
  AvgCommunicate_129630_Content_22 = {
    Text = "Главное, что ты цела. У этой штуки должна быть безопасная версия."
  },
  AvgCommunicate_129630_Content_23 = {
    Text = "Мне нужно доложить о ненадлежащем хранении опасных материалов."
  },
  AvgCommunicate_129630_Content_24 = {
    Text = "Заодно попрошу для тебя ещё одну — безопасную версию."
  },
  AvgCommunicate_129630_Content_25 = {Text = "!"},
  AvgCommunicate_129630_Content_27 = {
    Text = "Угольок — лучше всех!"
  },
  AvgCommunicate_129630_Content_3 = {
    Text = "Жемчужина, меняющая цвет? Такое ощущение, что я где-то это видел(а)..."
  },
  AvgCommunicate_129630_Content_4 = {
    Text = "Красный, белый, синий!"
  },
  AvgCommunicate_129630_Content_5 = {
    Text = "Красный, белый, синий... жёлтый, зелёный, чёрный?"
  },
  AvgCommunicate_129630_Content_6 = {
    Text = "Жёлтый, зелёный, Угольочек, знает?"
  },
  AvgCommunicate_129630_Content_7 = {
    Text = "«Пустотный прилив»?!"
  },
  AvgCommunicate_129630_Content_8 = {
    Text = "Скорее выброси!"
  },
  AvgCommunicate_129630_Content_9 = {
    Text = "Быстро выброси её туда, где нет людей!"
  },
  AvgCommunicate_129630_Option_8 = {
    Text = "Скорее выброси!"
  },
  AvgCommunicate_129631_Content_1 = {
    Text = "Угольок, помнишь?"
  },
  AvgCommunicate_129631_Content_10 = {
    Text = "Шлёп-шлёп!"
  },
  AvgCommunicate_129631_Content_11 = {
    Text = "Угольок, молодец!"
  },
  AvgCommunicate_129631_Content_12 = {
    Text = "Верно, пароль! Угольок, это я!"
  },
  AvgCommunicate_129631_Content_13 = {
    Text = "Операция, штурм! Полночь, столовая!"
  },
  AvgCommunicate_129631_Content_14 = {
    Text = "Ради золотистой жареной рыбы!"
  },
  AvgCommunicate_129631_Content_15 = {
    Text = "Выступаем!"
  },
  AvgCommunicate_129631_Content_16 = {
    Text = "Выступаем!"
  },
  AvgCommunicate_129631_Content_2 = {
    Text = "Угу, давай!"
  },
  AvgCommunicate_129631_Content_3 = {Text = "Буль?"},
  AvgCommunicate_129631_Content_4 = {
    Text = "Плюх-плюх?"
  },
  AvgCommunicate_129631_Content_5 = {
    Text = "Буль-буль!"
  },
  AvgCommunicate_129631_Content_6 = {
    Text = "Плюх… плюх-плюх?"
  },
  AvgCommunicate_129631_Content_7 = {
    Text = "Угольок, неправильно!"
  },
  AvgCommunicate_129631_Content_8 = {
    Text = "Да, шлёп-шлёп!"
  },
  AvgCommunicate_129631_Content_9 = {
    Text = "Но, неважно!"
  },
  AvgCommunicate_129631_Option_10 = {
    Text = "Шлёп-шлёп!"
  },
  AvgCommunicate_129631_Option_6 = {
    Text = "Плюх… плюх-плюх?"
  },
  AvgCommunicate_129632_Content_1 = {
    Text = "Объяснительная… так сложно…"
  },
  AvgCommunicate_129632_Content_10 = {
    Text = "В следующий раз я подготовлю более скрытный маршрут."
  },
  AvgCommunicate_129632_Content_11 = {
    Text = "Гарантирую, нас не поймают!"
  },
  AvgCommunicate_129632_Content_12 = {
    Text = "Даже если поймают, ничего страшного!"
  },
  AvgCommunicate_129632_Content_13 = {
    Text = "Почему?"
  },
  AvgCommunicate_129632_Content_14 = {
    Text = "Уже, объяснительная, заранее подготовлена!"
  },
  AvgCommunicate_129632_Content_15 = {
    Text = "Сдать, после поимки!"
  },
  AvgCommunicate_129632_Content_16 = {
    Text = "Для Угольочка, тоже есть!"
  },
  AvgCommunicate_129632_Content_17 = {
    Text = "Стой, не надо заранее готовить такие вещи!"
  },
  AvgCommunicate_129632_Content_2 = {
    Text = "Эх… всё из-за Юухаши и Агриппы!"
  },
  AvgCommunicate_129632_Content_3 = {
    Text = "С тех пор как они сбежали из ловушки и объели всю кухню…"
  },
  AvgCommunicate_129632_Content_4 = {
    Text = "Шеф-повар усилил охрану в десять раз!"
  },
  AvgCommunicate_129632_Content_5 = {
    Text = "Так ярко… Погоня за светом… так громко… сигнализация…"
  },
  AvgCommunicate_129632_Content_6 = {
    Text = "Кухня, так страшно…"
  },
  AvgCommunicate_129632_Content_7 = {
    Text = "Но, вкусно, рыба!"
  },
  AvgCommunicate_129632_Content_8 = {
    Text = "Но, рыба, вкусно!"
  },
  AvgCommunicate_129632_Content_9 = {
    Text = "Вместе, в следующий раз, снова?"
  },
  AvgCommunicate_134101_Content_1 = {
    Text = "Мой путеводный Погоня за светом… нет, теперь я должна называть Вас Солнцем."
  },
  AvgCommunicate_134101_Content_10 = {
    Text = "И ты в порядке? Почему вдруг заговорила об этом?"
  },
  AvgCommunicate_134101_Content_11 = {
    Text = "Благодаря вашей милости я смогла полностью узреть вашу душу и постичь истинный облик мира."
  },
  AvgCommunicate_134101_Content_12 = {
    Text = "Свет, Погоня за светом… Оказывается, мир изначально был тьмой и хаосом, и лишь потому, что божество избрало жертву, солнце стало явью, и все живые существа обрели счастье бытия…"
  },
  AvgCommunicate_134101_Content_13 = {
    Text = "Ты, случайно, не зачиталась священными текстами? Мне кажется, тебе стоит немного остыть."
  },
  AvgCommunicate_134101_Content_14 = {
    Text = "Я понимаю — вы желаете быть среди смертных и не хотите восседать на божественном престоле."
  },
  AvgCommunicate_134101_Content_15 = {
    Text = "Ваше бескорыстие, ваша самоотдача, ваша жертва…"
  },
  AvgCommunicate_134101_Content_16 = {
    Text = "Отныне я буду общаться с вами как самый преданный… нет, как вечный Близкий Близкий друг."
  },
  AvgCommunicate_134101_Content_17 = {
    Text = "Пусть это неугасимое святое сердце рассеет для вас всю тьму."
  },
  AvgCommunicate_134101_Content_2 = {
    Text = "Вы… Вы не просто Солнце — Вы центр вселенной, Предвечная заря."
  },
  AvgCommunicate_134101_Content_3 = {
    Text = "Мы уже давно знакомы, а ты стала ещё более почтительной, чем раньше?"
  },
  AvgCommunicate_134101_Content_4 = {
    Text = "Потому что я поняла: если все живые существа не пали ниц перед Вами, то лишь потому, что от рождения слепы и невежественны, неспособны узреть Вашу истинную сущность!"
  },
  AvgCommunicate_134101_Content_5 = {
    Text = "Как муравью охватить взором исполина? Прежде и я могла лишь с помощью Святого Сердца мельком увидеть верхушку айсберга Вашей силы."
  },
  AvgCommunicate_134101_Content_6 = {
    Text = "И даже от этого Святое Сердце пронзала боль, словно от иглы. Стоило бы мне бросить ещё один взгляд на Вашу душу — и я могла бы погибнуть."
  },
  AvgCommunicate_134101_Content_7 = {
    Text = "Настолько серьёзно? Тогда лучше не смотри."
  },
  AvgCommunicate_134101_Content_8 = {
    Text = "Какая холодная реакция… Я думала, Вы с радостью примете мои хвалы."
  },
  AvgCommunicate_134101_Content_9 = {
    Text = "Никто не может вот так вдруг принять подобную похвалу!"
  },
  AvgCommunicate_134101_Option_13 = {
    Text = "Тебе, наверное, нужно успокоиться."
  },
  AvgCommunicate_134101_Option_3 = {
    Text = "…Какое странное ощущение."
  },
  AvgCommunicate_134101_Option_7 = {
    Text = "Настолько серьёзно?"
  },
  AvgCommunicate_134102_Content_1 = {
    Text = "Мне снились льды и снега родины, и те пустынные руины."
  },
  AvgCommunicate_134102_Content_10 = {
    Text = "Именно потому, что люди сохраняют видимость взаимной доброжелательности, мир становится чуточку спокойнее. По-моему, это неплохо."
  },
  AvgCommunicate_134102_Content_11 = {
    Text = "Скучно. Мир и счастье невозможно поддерживать притворством."
  },
  AvgCommunicate_134102_Content_12 = {
    Text = "Лишь когда правитель желает счастья своим подданным, а сильные — счастья слабым, мир будет длиться."
  },
  AvgCommunicate_134102_Content_13 = {
    Text = "Взять меня и моих милых слуг — я никогда не скрывала перед ними своих желаний, и тем не менее они живут счастливо."
  },
  AvgCommunicate_134102_Content_14 = {
    Text = "Вот она — истина, принадлежащая сильным."
  },
  AvgCommunicate_134102_Content_15 = {
    Text = "Приходи сегодня вечером в мои покои. Твои подношения всё это время радовали меня, и новая Огромная Огромная сила тоже пришлась по душе. Я покажу тебе, что на самом деле скрывается в глубине твоей души."
  },
  AvgCommunicate_134102_Content_16 = {
    Text = "Подожди, сегодня?!"
  },
  AvgCommunicate_134102_Content_17 = {
    Text = "Шокированное выражение"
  },
  AvgCommunicate_134102_Content_18 = {
    Text = "У тебя нет права отказать. Я устрою тебе кое-что... поинтереснее, чем в прошлые разы."
  },
  AvgCommunicate_134102_Content_19 = {
    Text = "Сияющее выражение Ванды"
  },
  AvgCommunicate_134102_Content_2 = {
    Text = "Я давно не вспоминала те места. Это из-за осколков силы или из-за более цельной души?"
  },
  AvgCommunicate_134102_Content_20 = {
    Text = "(Мне ещё отчёт сдавать! Если не сдам сегодня, Дорль с меня шкуру спустит!)"
  },
  AvgCommunicate_134102_Content_3 = {
    Text = "Давно забытое чувство… В любом случае, благодарю тебя, мой милый Сквайр. Ах да, ты предпочитаешь, чтобы я называла тебя другом."
  },
  AvgCommunicate_134102_Content_4 = {
    Text = "К вашим услугам, моя госпожа."
  },
  AvgCommunicate_134102_Content_5 = {
    Text = "Хм, ты всегда так учтив."
  },
  AvgCommunicate_134102_Content_6 = {
    Text = "Почему бы тебе иногда не отбросить эту скучную манерность? Из-за неё мои награды уже не раз теряли всякий интерес."
  },
  AvgCommunicate_134102_Content_7 = {
    Text = "Ваше общество превозносит скромность и вежливость как добродетели, однако тьмы в человеческих сердцах ничуть не меньше, чем у существ с других планет."
  },
  AvgCommunicate_134102_Content_8 = {
    Text = "Люди наряжаются в безобидный и благородный облик лишь из страха перед последствиями, которые несёт Правда."
  },
  AvgCommunicate_134102_Content_9 = {
    Text = "В этом есть доля правды, но пока поступки безупречны, нет особой нужды копаться в мыслях."
  },
  AvgCommunicate_134102_Option_20 = {
    Text = "Нет, не надо!"
  },
  AvgCommunicate_134102_Option_4 = {
    Text = "К вашим услугам."
  },
  AvgCommunicate_134102_Option_9 = {
    Text = "В этом есть доля истины."
  },
  AvgCommunicate_134103_Content_1 = {
    Text = "Звёзды зовут меня..."
  },
  AvgCommunicate_134103_Content_10 = {
    Text = "Знаешь, Агриппа часто говорит, что завидует Мириам."
  },
  AvgCommunicate_134103_Content_11 = {
    Text = "Она говорит, что если бы римский правитель был ещё жив — будь то Дитя или дряхлый старик, — ей было бы куда спокойнее."
  },
  AvgCommunicate_134103_Content_12 = {
    Text = "Завидует..."
  },
  AvgCommunicate_134103_Content_13 = {
    Text = "Потому что пока ты существуешь, Лемурия не исчезла по-настоящему."
  },
  AvgCommunicate_134103_Content_14 = {
    Text = "Более того, ты ведь этой силой помогла стольким людям в Мисагре!"
  },
  AvgCommunicate_134103_Content_15 = {
    Text = "Очень многие студенты написали твоё имя в опросе о любимом Пробуждённом!"
  },
  AvgCommunicate_134103_Content_16 = {Text = "Хм..."},
  AvgCommunicate_134103_Content_17 = {
    Text = "Нам не нужно это назойливое обожание. Мисагр и так поручает нам слишком много дел."
  },
  AvgCommunicate_134103_Content_18 = {
    Text = "Пусть применение этих сил — дело пустяковое, но когда наш покой нарушают слишком часто, это утомляет."
  },
  AvgCommunicate_134103_Content_19 = {
    Text = "Правда? А я слышала, что каждый раз, когда студенты приходят к тебе в слезах с просьбой о помощи, ты — один из Пробуждённых, которые легче всего соглашаются помочь."
  },
  AvgCommunicate_134103_Content_2 = {
    Text = "В глубинах сновидений, на дне океанских течений, в окружении мириадов подданных — вернуться на трон и принести Лемурии процветание и покой."
  },
  AvgCommunicate_134103_Content_20 = {
    Text = "...Кто распускает эти слухи? Мы просто не выносим их нытьё."
  },
  AvgCommunicate_134103_Content_21 = {
    Text = "Впрочем, неважно. Наша духовная Огромная Огромная сила значительно возросла, и пришло время погрузиться в более глубокий и обширный сон."
  },
  AvgCommunicate_134103_Content_22 = {
    Text = "На этот раз мы намерены посетить сны всех художников и поэтов нынешней эпохи. Запомни: без веской причины — не смей никого посылать нас беспокоить."
  },
  AvgCommunicate_134103_Content_23 = {
    Text = "А? После такого прилива сил первым делом — завалиться спать?!"
  },
  AvgCommunicate_134103_Content_3 = {
    Text = "...Мне приснился такой сон."
  },
  AvgCommunicate_134103_Content_4 = {
    Text = "Сон? Он несёт в себе какое-то Пророчество?"
  },
  AvgCommunicate_134103_Content_5 = {
    Text = "Всего лишь зов, который я ощутила после предельного роста своей силы. Что до его значения... Лемурии больше нет, и нет нужды в её возрождении."
  },
  AvgCommunicate_134103_Content_6 = {
    Text = "Те, кому посчастливилось выжить, могут свободно жить в новом мире. И это прекрасно."
  },
  AvgCommunicate_134103_Content_7 = {
    Text = "Им не нужен запоздавший правитель, чтобы оберегать их."
  },
  AvgCommunicate_134103_Content_8 = {
    Text = "И всё же ты вела свой народ и оберегала их дух."
  },
  AvgCommunicate_134103_Content_9 = {
    Text = "Мы ничего не делали и никого не вели. Это лишь их заблуждение, плод их собственных фантазий."
  },
  AvgCommunicate_134103_Option_10 = {
    Text = "Это не заблуждение."
  },
  AvgCommunicate_134103_Option_19 = {
    Text = "Правда?"
  },
  AvgCommunicate_134103_Option_23 = {Text = "А?"},
  AvgCommunicate_134103_Option_8 = {Text = "Но..."},
  AvgCommunicate_134104_Content_1 = {
    Text = "Радость с первого взгляда, слёзы с первой мысли — я давно так не веселилась."
  },
  AvgCommunicate_134104_Content_10 = {
    Text = "Э-э, я не говорю, что они не заслужили, но нужно действовать обдуманно и с умом…"
  },
  AvgCommunicate_134104_Content_11 = {
    Text = "И неужели это действительно такой нормальный ход мыслей, я так тронута…"
  },
  AvgCommunicate_134104_Content_12 = {
    Text = "Ах, дай-ка подумать. Если сейчас сказать моему жасминчику, что изначально я лишь хотела развести сверчков для боёв, — не испорчу ли я всё настроение?"
  },
  AvgCommunicate_134104_Content_13 = {Text = "Шучу."},
  AvgCommunicate_134104_Content_14 = {
    Text = "Этот мир невыносимо скучен, %player%. Даже если завтра наступит гибель, обыватели всё равно погрязнут в своих обидах, любви, ненависти и желаниях — во всей этой пошлости."
  },
  AvgCommunicate_134104_Content_16 = {
    Text = "И всё же, несмотря на это, мой маленький жасминчик усердно и отчаянно, выпустив коготки, придумывает для Них решения."
  },
  AvgCommunicate_134104_Content_17 = {
    Text = "Так вот, раз уж я обрела столь великую силу, что же мне делать дальше — помогать моему любимому жасминчику или создавать ему неприятности?"
  },
  AvgCommunicate_134104_Content_18 = {
    Text = "Ну конечно, делать два дела одновременно — это же самое интересное, Правда?"
  },
  AvgCommunicate_134104_Content_19 = {Text = "???"},
  AvgCommunicate_134104_Content_2 = {
    Text = "Мой маленький жасминчик преподнёс мне поистине щедрый Подарок."
  },
  AvgCommunicate_134104_Content_20 = {
    Text = "Я дарил тебе Подарок не для этого."
  },
  AvgCommunicate_134104_Content_21 = {
    Text = "Прекрати немедленно! Я отвечаю только за события Эрозии, общественный порядок и нравственность — не в юрисдикции Мисагра! Не заставляй лондиниумскую психиатрическую лечебницу заменять тюрьму! Эй, эй!"
  },
  AvgCommunicate_134104_Content_4 = {
    Text = "Во всех кварталах, во всех кварталах вокруг школы зафиксированы массовые случаи коллективной истерии среди горожан — толпы людей то плачут, то смеются, полиция и медики Лондиниума сбились с ног!"
  },
  AvgCommunicate_134104_Content_6 = {
    Text = "Я так далеко от родины, одинока и беспомощна, а мой маленький жасминчик так заботится обо мне, позволив достичь подобных высот…"
  },
  AvgCommunicate_134104_Content_7 = {
    Text = "Я была так безмерно счастлива, что не удержалась и решила размяться."
  },
  AvgCommunicate_134104_Content_8 = {
    Text = "Хм, весьма действенно — те мерзавцы с гнилью в душе сходили с ума один быстрее другого."
  },
  AvgCommunicate_134104_Content_9 = {
    Text = "Подожди, школа прислала досье на тех людей. Убийство жены, жестокое обращение, @3@4…"
  },
  AvgCommunicate_134104_Option_19 = {Text = "???"},
  AvgCommunicate_134104_Option_9 = {
    Text = "Нужно действовать обдуманно и с умом."
  },
  AvgCommunicate_134105_Content_1 = {
    Text = "Свет маяка уже способен озарить глубочайшее морское дно."
  },
  AvgCommunicate_134105_Content_10 = {
    Text = "Просто слушая твоё описание, я уже чувствую — это наверняка была очень красивая страна."
  },
  AvgCommunicate_134105_Content_11 = {
    Text = "Да, родина была прекрасна… Поэтому я не откажусь от попыток вернуть её."
  },
  AvgCommunicate_134105_Content_12 = {
    Text = "Больше силы — больше надежды. Я буду заманивать всё больше мотыльков, направляя их к маяку…"
  },
  AvgCommunicate_134105_Content_13 = {
    Text = "Однажды моя родина вновь поднимется со дна морского и снова распахнёт мне свои объятия."
  },
  AvgCommunicate_134105_Content_14 = {
    Text = "В итоге опять за своё! Зря я тебе сочувствовал, а ну прекрати!!!"
  },
  AvgCommunicate_134105_Content_2 = {
    Text = "Когда же вновь откроется путь домой..."
  },
  AvgCommunicate_134105_Content_3 = {
    Text = "Фалос… Эх, говорить сейчас, что я тебя понимаю — лишь пустое утешение. Ты… не грусти так сильно."
  },
  AvgCommunicate_134105_Content_4 = {
    Text = "Тоска… Тоска по родине стала клеймом на моей душе. Я уже привык жить с ней бок о бок."
  },
  AvgCommunicate_134105_Content_5 = {
    Text = "Бесконечная тоска приносит боль, но она же позволяет мне навсегда помнить облик родного края."
  },
  AvgCommunicate_134105_Content_6 = {
    Text = "Те отмели, поросшие кораллами, тот величественный храм и высокие врата, у которых я так часто стоял на страже…"
  },
  AvgCommunicate_134105_Content_7 = {
    Text = "Я помню узоры, высеченные на краях тех каменных колонн, помню каждую широкую дорогу в столице, помню благоговейные и счастливые лица людей во время молитвы."
  },
  AvgCommunicate_134105_Content_8 = {
    Text = "Когда проводились великие празднества, вся страна ликовала — это было моё самое хлопотное, но и самое отрадное время."
  },
  AvgCommunicate_134105_Content_9 = {
    Text = "Мне выпала честь стоять на страже перед королевской колесницей, вместе наслаждаясь восхищёнными и благоговейными взглядами народа, испытывая Надменность и славу… Это моё самое дорогое воспоминание."
  },
  AvgCommunicate_134105_Option_10 = {
    Text = "Это наверняка была очень красивая страна."
  },
  AvgCommunicate_134105_Option_14 = {
    Text = "В итоге опять за своё!"
  },
  AvgCommunicate_134105_Option_3 = {
    Text = "Фалос…"
  },
  AvgCommunicate_134106_Content_1 = {
    Text = "Эм, Носитель…"
  },
  AvgCommunicate_134106_Content_10 = {
    Text = "Теперь можно носить Дженкина, Эйджис, Калабу и Орету вместе в столовую!"
  },
  AvgCommunicate_134106_Content_11 = {
    Text = "Это уже слишком много!"
