  AvgCommunicate_134106_Content_14 = {
    Text = "Хоть я и не это имел в виду, но…"
  },
  AvgCommunicate_134106_Content_15 = {
    Text = "Главное, чтобы Лили была счастлива!"
  },
  AvgCommunicate_134106_Content_2 = {Text = "Хм?"},
  AvgCommunicate_134106_Content_3 = {
    Text = "Ты можешь похвалить Лили?"
