  AvgCommunicate_134106_Content_4 = {
    Text = "Лили, умничка. Что-то произошло, за что тебя стоит похвалить?"
  },
  AvgCommunicate_134106_Content_5 = {
    Text = "Лили подняла кучу гнойничков!"
  },
  AvgCommunicate_134106_Content_6 = {
    Text = "Подняла высоко-высоко!"
  },
  AvgCommunicate_134106_Content_9 = {
    Text = "Должно быть, это влияние Последнего Закона…"
  },
  AvgCommunicate_134107_Content_1 = {
    Text = "С тех пор как я постигла Высший Закон, путь передо мной стал ещё яснее."
  },
  AvgCommunicate_134107_Content_10 = {
    Text = "Как лоцман, это мой долг."
  },
  AvgCommunicate_134107_Content_11 = {
    Text = "Любой на моём месте, вероятно, поступил бы так же."
  },
  AvgCommunicate_134107_Content_12 = {
    Text = "Лоцманская работа — это долг и ответственность, а не стремление к похвале."
  },
  AvgCommunicate_134107_Content_13 = {
    Text = "Верните все эти подарки морякам."
  },
  AvgCommunicate_134107_Content_14 = {
    Text = "Это ведь знак их признательности — прими их."
  },
  AvgCommunicate_134107_Content_15 = {
    Text = "И ещё: если в море ты увидишь жёлтый Погоня за светом неизвестного происхождения, постарайся направить корабль в противоположную сторону."
  },
  AvgCommunicate_134107_Content_16 = {
    Text = "Не спрашивай почему — руководство в кратчайшие сроки разберётся с его источником…"
  },
  AvgCommunicate_134107_Content_2 = {
    Text = "Ради бесчисленных заблудших на этом пути и ради себя самой — ещё раз искренне благодарю вас за дарованное Откровение."
  },
  AvgCommunicate_134107_Content_3 = {
    Text = "Не стоит быть такой серьёзной. Ты это заслужила, Корсанте."
  },
  AvgCommunicate_134107_Content_4 = {
    Text = "Я заслужила?"
  },
  AvgCommunicate_134107_Content_5 = {
    Text = "Да, руководство получило множество благодарственных писем, переданных окольными путями."
  },
  AvgCommunicate_134107_Content_6 = {
    Text = "Все они — люди, заблудившиеся в плавании, но увидевшие на мачте холодный сине-фиолетовый Погоня за светом."
  },
  AvgCommunicate_134107_Content_7 = {
    Text = "Следуя за этим светом, они смогли добраться до ближайшего порта."
  },
  AvgCommunicate_134107_Content_8 = {
    Text = "Они назвали этот Погоня за светом «Светом Святой»."
  },
  AvgCommunicate_134107_Content_9 = {
    Text = "Кроме того, было множество подарков в знак благодарности — они все сложены у входа в приёмную."
  },
  AvgCommunicate_134107_Option_5 = {
    Text = "Мисагр получил благодарственные письма…"
  },
  AvgCommunicate_134108_Content_1 = {
    Text = "У тебя есть такая полезная штука, а ты не додумалась достать её раньше."
  },
  AvgCommunicate_134108_Content_10 = {
    Text = "У тебя, @2, вообще мозги есть?! Принимаешь шутки за чистую монету!"
  },
  AvgCommunicate_134108_Content_11 = {
    Text = "Если всех превратить в потомство, что Великой Владычице делать с этими дурацкими электроприборами и всякими странными общеобразовательными предметами? Хотя память и сохраняется, конечно..."
  },
  AvgCommunicate_134108_Content_12 = {
    Text = "Что мне, каждый день разговаривать с пустыми оболочками и отвечать самой себе? Ещё чего!"
  },
  AvgCommunicate_134108_Content_14 = {
    Text = "Тч, опять меня раскусили. Скукотища."
  },
  AvgCommunicate_134108_Content_15 = {
    Text = "Я верю, что ты так не поступишь, Агриппа. Даже если ты иногда сбиваешься с пути, я уверена, что смогу направить тебя обратно."
  },
  AvgCommunicate_134108_Content_16 = {
    Text = "Потому что ты — мудрая Владычица Лабиринта."
  },
  AvgCommunicate_134108_Content_17 = {
    Text = "Потому что ты — дорогой мне человек."
  },
  AvgCommunicate_134108_Content_18 = {
    Text = "Фу-у! Что за странные слова ты вдруг говоришь, мерзость, какая мерзость, уши сейчас отвалятся!"
  },
  AvgCommunicate_134108_Content_19 = {
    Text = "Ладно уж, так и быть, я пока воздержусь от превращения кого-либо в потомство. А теперь забирай эти задания!"
  },
  AvgCommunicate_134108_Content_2 = {
    Text = "Ха-ха, Великая Владычица наконец-то полностью свободна! Благородная Серая Волчица вот-вот возобновит своё правление в Мессагере."
  },
  AvgCommunicate_134108_Content_3 = {
    Text = "Весь Мессагер, нет, весь Кадат будет наводнён моим потомством."
