  AvgCommunicate_134108_Content_4 = {
    Text = "Правда?"
  },
  AvgCommunicate_134108_Content_5 = {
    Text = "Вообще-то, чтобы отпраздновать твоё постижение Высшего Закона, я собиралась в виде исключения помочь тебе прибраться в общежитии, и даже учебная часть согласилась освободить тебя от домашних заданий на неделю."
  },
  AvgCommunicate_134108_Content_6 = {
    Text = "Раз уж благородная Серая Волчица собирается превратить всех в своё потомство, думаю, всё это уже ни к чему, верно?"
  },
  AvgCommunicate_134108_Content_7 = {
    Text = "Э, э-э?!"
  },
  AvgCommunicate_134108_Content_9 = {
    Text = "Нельзя, нет, не допущу!"
  },
  AvgCommunicate_134108_Option_16 = {
    Text = "Потому что ты — мудрая Владычица Лабиринта."
  },
  AvgCommunicate_134108_Option_17 = {
    Text = "Потому что ты — дорогой мне человек."
  },
  AvgCommunicate_134108_Option_4 = {
    Text = "Правда?"
  },
  AvgCommunicate_134109_Content_1 = {
    Text = "Страж мяу, я увидела Мрак-Мрак тоннель…"
  },
  AvgCommunicate_134109_Content_10 = {
    Text = "Впрочем, в тех маленьких глазках я не чувствовал злобы. Наоборот, мне было очень спокойно, и сейчас я, кажется, могу слиться с ними воедино."
