  AvgCommunicate_134109_Content_11 = {
    Text = "Ты хочешь сказать, что слился с душами крыс?"
  },
  AvgCommunicate_134109_Content_12 = {
    Text = "Да, я почувствовал, как в одно мгновение рассыпался на множество частей и шнырял по извилистым трубам, среди грязного хлама, под низкой мебелью…"
  },
  AvgCommunicate_134109_Content_13 = {
    Text = "Ты вспомнил прежнюю жизнь, да? Ничего, теперь всё это в прошлом."
  },
  AvgCommunicate_134109_Content_14 = {
    Text = "А потом — управляя ими, я с лёгкостью ворую всё что угодно!"
  },
  AvgCommunicate_134109_Content_15 = {
    Text = "Будь у меня такие способности раньше, я бы даже самый большой банк в Западном квартале обчистил! Ха-ха-ха, теперь я просто король… нет, король всех воров мира! Никто больше не сможет меня остановить!"
  },
  AvgCommunicate_134109_Content_17 = {
    Text = "Чувствую, на этот раз даже полиция не поможет. Лучше попрошу учителя Доэль сделать систему наблюдения."
  },
  AvgCommunicate_134109_Content_2 = {
    Text = "Ни света, ни времени — я шла там совсем одна, шла и шла, будто целую жизнь."
  },
  AvgCommunicate_134109_Content_3 = {
    Text = "Ты в порядке? Ты снова заблудилась в пространстве?"
  },
  AvgCommunicate_134109_Content_4 = {
    Text = "Я шла очень-очень долго и наконец увидела что-то — словно лучик света, дымку, а потом это постепенно превратилось в Брауна! Его маленькие круглые глазки светились в той кромешной тьме."
  },
  AvgCommunicate_134109_Content_5 = {
    Text = "А потом — бесчисленные одинаковые глаза, они окружали меня, были рядом со мной…"
  },
  AvgCommunicate_134109_Content_6 = {
    Text = "Крысиная стая?"
  },
  AvgCommunicate_134109_Content_7 = {
    Text = "Да, я чувствую, что они — не просто крысы. У них словно есть душа, как у тех детей, которых я когда-то знал на улицах. Мы соперничали, помогали Близкий Близкий друг другу, сочувствовали Близкий Близкий друг другу и, как крысы, шныряли по улицам."
  },
  AvgCommunicate_134109_Content_8 = {
    Text = "Возможно, это души многих детей, которые сопровождают тебя."
  },
  AvgCommunicate_134109_Content_9 = {
    Text = "Ха? Но я ведь задолжал Джо куриную ножку, малышу Джонсу — два куска хлеба, а у Джонни стащил несколько шариков… Они что, пришли за долгами?!"
  },
  AvgCommunicate_134109_Option_11 = {
    Text = "Ты слился с ними чувствами?"
