  AvgCommunicate_134109_Option_3 = {
    Text = "Ты в порядке?"
  },
  AvgCommunicate_134109_Option_6 = {
    Text = "Крысиная стая?"
  },
  AvgCommunicate_134109_Option_8 = {
    Text = "Возможно, это они и есть"
  },
  AvgCommunicate_134110_Content_1 = {
    Text = "А, а… Аааааа! Чернота, кругом одна чернота!"
  },
  AvgCommunicate_134110_Content_10 = {
    Text = "Нет…? Чёрный демон не пришёл?"
  },
  AvgCommunicate_134110_Content_11 = {
    Text = "Но если мы живём в чреве демона, то однажды тьма неизбежно поглотит нас… Нам не убежать, не убежать!"
