  AvgCommunicate_134110_Content_12 = {
    Text = "Это так страшно, так страшно…"
  },
  AvgCommunicate_134110_Content_14 = {
    Text = "Не бойся."
  },
  AvgCommunicate_134110_Content_15 = {
    Text = "Я не совсем понимаю, о чём ты говоришь, но… если миру действительно суждено погибнуть, то по крайней мере я и все Граждане Мисагара будем сражаться до последнего мгновения."
  },
  AvgCommunicate_134110_Content_16 = {
    Text = "Если Эрозия — действительно неизбежный Конец, я найду для тебя последний островок света и останусь рядом с тобой до самого конца мира."
  },
  AvgCommunicate_134110_Content_17 = {
    Text = "……Я поняла."
  },
  AvgCommunicate_134110_Content_18 = {
    Text = "Ты не погаснешь. Я верю в тебя."
  },
  AvgCommunicate_134110_Content_19 = {
    Text = "Спасибо тебе, Страж."
  },
  AvgCommunicate_134110_Content_2 = {
    Text = "Весь мир — чёрный! Только пустота, только пустота!"
  },
  AvgCommunicate_134110_Content_3 = {
    Text = "Винкель! Проснись! Опять кошмар приснился?!"
  },
  AvgCommunicate_134110_Content_4 = {
    Text = "Нет, нет, больше @2людских технологий, знаний, более могущественных душ — всё бесполезно, всё бесполезно! Я всё равно не могу снова переселиться!"
  },
  AvgCommunicate_134110_Content_5 = {
    Text = "Став сильнее, я стала ещё заметнее для тьмы… Слишком бросаюсь в глаза, тьма настигнет меня…"
  },
  AvgCommunicate_134110_Content_6 = {
    Text = "Я не хочу становиться сильнее, я хочу бежать, бежать далеко-далеко… Но если весь мир — чёрный, и весь Погоня за светом — ложь, то куда мне деться…"
  },
  AvgCommunicate_134110_Content_7 = {
    Text = "Почему, почему эта Огромная Огромная сила заставляет меня видеть всё это?! Я не хочу знать!"
  },
  AvgCommunicate_134110_Content_8 = {
    Text = "Умру, умру, умру, неужели мне снова умирать?! Я не хочу переживать это снова, не хочу, не хочу…"
