  AvgCommunicate_134110_Option_9 = {
    Text = "Винкор!"
  },
  AvgCommunicate_134111_Content_1 = {
    Text = "Мои крылья... стали ещё огромнее."
  },
  AvgCommunicate_134111_Content_10 = {
    Text = "Кастор, я знаю, что ты замечательный, и крылья твои тоже замечательные, но как бы тебе объяснить..."
  },
  AvgCommunicate_134111_Content_12 = {
    Text = "Ладно, я поняла. Кстати, раз так, твоя грузоподъёмность тоже наверняка возросла, верно?"
  },
  AvgCommunicate_134111_Content_13 = {
    Text = "Хм, по грубым подсчётам, вес десятка с лишним человек не должен быть проблемой."
  },
  AvgCommunicate_134111_Content_14 = {
    Text = "Правда, мои руки, кажется, не смогут обхватить столько людей за один раз."
