  AvgCommunicate_134111_Content_16 = {
    Text = "Вот что: потренируй силу рук, и тогда у нас будет воздушный автомобиль, который сможет в любой момент спуститься с небес!"
  },
  AvgCommunicate_134111_Content_17 = {
    Text = "Огромная Огромная сила рук? Какое это имеет отношение к воздушному... автомобилю? Благодетель, прошу простить мою тупость, я не совсем понял."
