  AvgCommunicate_134111_Content_20 = {
    Text = "Конечно! Для меня это честь, благодетель."
  },
  AvgCommunicate_134111_Content_21 = {
    Text = "Договорились, я немедленно попрошу Эрику изготовить грузовую корзину!"
  },
  AvgCommunicate_134111_Content_22 = {
    Text = "И больше никогда не думай отдавать свои крылья кому-то, никому нельзя."
