  AvgCommunicate_134111_Content_3 = {
    Text = "Вы, крылатые, совсем не понимаете, как это удобно — иметь крылья... Как же я завидую..."
  },
  AvgCommunicate_134111_Content_4 = {
    Text = "Если благодетель желает, я смутно припоминаю, что в Церкви Фонарщиков есть способы пересадки крыльев. Я могу добровольно отдать свои крылья благодетелю, я не боюсь боли."
  },
  AvgCommunicate_134111_Content_6 = {
    Text = "Нет-нет-нет-нет, это совсем не нужно, пусть они лучше остаются на тебе."
  },
  AvgCommunicate_134111_Content_7 = {
    Text = "А, благодетель не хочет мои крылья? Они сейчас уже очень сильные."
  },
  AvgCommunicate_134111_Content_8 = {
    Text = "После постижения законов я ощущаю каждое дуновение ветра, проходящее сквозь перья, каждый поток воздуха и силу его вращения — всё это в моей власти."
  },
  AvgCommunicate_134111_Content_9 = {
    Text = "Дело не в том, сильные они или нет."
  },
  AvgCommunicate_134111_Option_15 = {
    Text = "У меня есть предложение."
  },
  AvgCommunicate_134111_Option_18 = {
    Text = "Это важное задание."
  },
  AvgCommunicate_134111_Option_3 = {
    Text = "Ты совсем не понимаешь."
  },
  AvgCommunicate_134111_Option_9 = {
    Text = "Дело не в том, сильные они или нет."
  },
  AvgCommunicate_134112_Content_1 = {
    Text = "Ого, так вот каким мир выглядит с твоей точки зрения."
  },
  AvgCommunicate_134112_Content_10 = {
    Text = "У людей и Правда столько выражений лица? Похоже, меня можно считать каменнолицым."
  },
  AvgCommunicate_134112_Content_11 = {
    Text = "И это ещё не всё — я научилась одновременно смеяться и плакать, злиться и плакать, злиться и смеяться, бояться и смеяться…"
  },
  AvgCommunicate_134112_Content_12 = {
    Text = "Стоит лишь скомбинировать разные выражения — и получается новая Эмоция! Похоже, совсем скоро Кассия полностью овладеет человеческими чувствами!"
  },
  AvgCommunicate_134112_Content_13 = {
    Text = "Хочешь посмотреть? Хочешь? Даже «любовь» — эту неразгаданную тайну человечества — Кассия теперь может изобразить для тебя!"
  },
  AvgCommunicate_134112_Content_15 = {
    Text = "Ты не только совсем ничего не освоила, но сейчас выглядишь ещё менее похожей на человека! Жуть какая, прекрати немедленно!!!"
