  },
  AvgCommunicate_134112_Content_4 = {
    Text = "Кассия увидела… тысячи и тысячи букашек, наслоённых Близкий Близкий друг на друга, бесчисленные мгновения — всё в поле «зрения»."
  },
  AvgCommunicate_134112_Content_5 = {
    Text = "В одно краткое мгновение бесчисленное множество людей одновременно плакали, и столько же одновременно смеялись, злились, боялись…"
  },
  AvgCommunicate_134112_Content_6 = {
    Text = "А у некоторых лица были совершенно безмятежными — кажется, эту эмоцию называют счастьем? Оказывается, у человеческих эмоций столько тончайших оттенков…"
  },
  AvgCommunicate_134112_Content_7 = {
    Text = "Ты уже можешь чувствовать эмоции людей?!"
  },
  AvgCommunicate_134112_Content_8 = {
    Text = "Нет, Кассия может только видеть их выражения лиц, движения, видеть цвет их эмоций."
  },
  AvgCommunicate_134112_Content_9 = {
    Text = "Но Кассия лучше всего умеет подражать! Увидев разом все улыбки и слёзы мира, теперь Кассия может показать тебе 21 вид улыбки и 36 видов плача!"
  },
  AvgCommunicate_134112_Option_10 = {
    Text = "Так много?"
  },
  AvgCommunicate_134112_Option_15 = {
    Text = "Ты совсем ничего не освоила!"
  },
  AvgCommunicate_134112_Option_2 = {Text = "Что?"},
  AvgCommunicate_134112_Option_7 = {
    Text = "Ты уже можешь чувствовать эмоции людей?!"
  },
  AvgCommunicate_134113_Content_1 = {
    Text = "Сделка с тобой — самое верное решение за всю мою торговую карьеру."
  },
  AvgCommunicate_134113_Content_10 = {
    Text = "Подожди, дальше всё страннее и страннее!"
  },
  AvgCommunicate_134113_Content_11 = {
    Text = "К тому же вещи, которые звучат так ценно, наверняка стоят очень дорого. Какова цена сделки?"
  },
  AvgCommunicate_134113_Content_12 = {
    Text = "Ну... в конце концов, именно благодаря тебе я обрела силу, позволяющую свободнее перемещаться между мирами."
  },
  AvgCommunicate_134113_Content_13 = {
    Text = "Специально для тебя я сделаю особую скидку. Что касается условий — приходи в лавку, обсудим лично. Буду с нетерпением ждать твоего визита."
  },
  AvgCommunicate_134113_Content_2 = {
    Text = "Посадить семя и ждать, пока оно вырастет в цветок, травинку или исполинское дерево."
  },
  AvgCommunicate_134113_Content_3 = {
    Text = "Я редко занимаюсь делами, требующими столь долгого ожидания отдачи. К счастью, судя по результатам, вложение уже окупилось с лихвой."
  },
  AvgCommunicate_134113_Content_4 = {
    Text = "Хе-хе, спасибо за помощь всё это время. Рада, что не разочаровала тебя."
  },
  AvgCommunicate_134113_Content_5 = {
    Text = "Воды Моря Тысячи Ликов стали ещё глубже. Мы давно не виделись, и тамошние головы тоже очень скучают по тебе. Не хочешь снова наведаться в знакомые места?"
  },
  AvgCommunicate_134113_Content_6 = {
    Text = "Э-э, лу... лучше не надо. Мне кажется, иногда именно расстояние рождает красоту."
  },
  AvgCommunicate_134113_Content_7 = {
    Text = "Хе-хе, у тебя и в красноречии есть Реальность талант торговца."
  },
  AvgCommunicate_134113_Content_8 = {
    Text = "Кстати, в мою лавку недавно поступило несколько новых вещиц — весьма редких. Я приберегла их для тебя."
  },
  AvgCommunicate_134113_Content_9 = {
    Text = "Есть Жемчужина, позволяющая резонировать с собственной изначальной силой, Зеркало, через которое можно увидеть образы другого мира, и ещё ошейник, заставляющий слушаться."
  },
  AvgCommunicate_134113_Option_10 = {
    Text = "Дальше всё страннее и страннее!"
