  AvgCommunicate_134113_Option_4 = {Text = "Хе-хе."},
  AvgCommunicate_134113_Option_6 = {
    Text = "Лучше не надо."
  },
  AvgCommunicate_134114_Content_1 = {
    Text = "Я… стала огнём."
  },
  AvgCommunicate_134114_Content_10 = {
    Text = "В мире ещё так много красоты, достойной воплощения. Думаю, у меня уже появилось больше вдохновения для творчества."
  },
  AvgCommunicate_134114_Content_11 = {
    Text = "Отныне я обращусь в пламя и принесу более чистый и естественный ритм."
  },
  AvgCommunicate_134114_Content_2 = {
    Text = "Бирюзовым, танцующим огнём. Горение, очищение, танец."
  },
  AvgCommunicate_134114_Content_3 = {
    Text = "Мои грехи и грехи других сгорят в этом пламени, и всё станет чистым."
  },
  AvgCommunicate_134114_Content_4 = {
    Text = "Лиз… ты всё ещё вспоминаешь тот давний пожар?"
  },
  AvgCommunicate_134114_Content_5 = {
    Text = "Моя Досаждение уже медленно выгорела в огне, но… я не вправе прощать тот пожар за других."
  },
  AvgCommunicate_134114_Content_6 = {
    Text = "Я никогда не жалела о содеянном и не стану бежать от тех лиц в пламени."
  },
  AvgCommunicate_134114_Content_7 = {
    Text = "После того как я оказалась здесь, ты подарил мне новую жизнь. Мне больше не нужна грандиозная сцена, но если ты будешь моим зрителем, я думаю, я всё равно буду чувствовать счастье, когда танцую."
  },
  AvgCommunicate_134114_Content_8 = {
    Text = "Позволь мне быть твоим фанатом номер один и продолжать смотреть, как ты танцуешь!"
  },
  AvgCommunicate_134114_Content_9 = {
    Text = "Да, спасибо тебе. Когда я перестала танцевать, я часто сидела у окна без дела. Я видела ветер, цветы, травы, деревья, птиц и кошек — столько живых существ и природных явлений, наполненных ритмом движения."
  },
  AvgCommunicate_134114_Option_4 = {Text = "Лиз…"},
  AvgCommunicate_134114_Option_8 = {
    Text = "Я буду и дальше смотреть, как ты танцуешь!"
