  AvgCommunicate_134115_Content_12 = {
    Text = "Конечно, я по-прежнему буду отдавать всё ради пришествия Царства Божьего."
  },
  AvgCommunicate_134115_Content_13 = {
    Text = "Но теперь я понимаю… Царство Божье — это не только два состояния: полное пришествие или полное небытие."
  },
  AvgCommunicate_134115_Content_14 = {
    Text = "Когда мы возносим молитвы о пришествии Царства Божьего, часть его уже нисходит к нам."
