  AvgCommunicate_134115_Content_15 = {
    Text = "Благодарю тебя, Страж. Ты даровал мне новые силы."
  },
  AvgCommunicate_134115_Content_16 = {
    Text = "То, что я увидела, — это доказательство бессмертного существования Божественного Царства!"
  },
  AvgCommunicate_134115_Content_17 = {
    Text = "Хоть процесс и показался мне каким-то странным… но результат вышел неплохой."
  },
  AvgCommunicate_134115_Content_2 = {
    Text = "Что ты видишь?"
  },
  AvgCommunicate_134115_Content_3 = {
    Text = "Царство Божье… Да… Очертания Царства Божьего!"
  },
  AvgCommunicate_134115_Content_4 = {
    Text = "Оно никогда не было таким ясным… Оно никогда не было таким… обыденным…"
  },
  AvgCommunicate_134115_Content_5 = {
    Text = "Мириам… ты уверена, что это твои слова?.."
  },
  AvgCommunicate_134115_Content_6 = {
    Text = "Я вижу свою родину. Я вижу бессмертное будущее."
  },
  AvgCommunicate_134115_Content_7 = {
    Text = "Но более того… я вижу настоящее."
  },
  AvgCommunicate_134115_Content_8 = {
    Text = "Мой Господь, родные, близкие друзья, верующие…"
  },
  AvgCommunicate_134115_Content_9 = {
    Text = "Царство Божье всегда было рядом… Всё, чем я обладаю, всегда было частью Царства Божьего…"
