  AvgCommunicate_134115_Option_10 = {
    Text = "Это воодушевляет!"
  },
  AvgCommunicate_134115_Option_17 = {
    Text = "Ну, допустим…"
  },
  AvgCommunicate_134115_Option_2 = {Text = "Что?"},
  AvgCommunicate_134115_Option_5 = {
    Text = "Обыденным?"
  },
  AvgCommunicate_134116_Content_1 = {
    Text = "Ой, не ожидала, что когда моя Огромная Огромная сила достигнет предела, ощущения будут именно такими."
  },
  AvgCommunicate_134116_Content_10 = {Text = "Э-э…"},
  AvgCommunicate_134116_Content_11 = {
    Text = "Хм, дай-ка угадаю... Сейчас ты думаешь: «И неизвестно ещё, что из этого страшнее». Верно?"
  },
  AvgCommunicate_134116_Content_12 = {
    Text = "Что?!! Ты же говорила, что не можешь читать мои мысли!"
