  AvgCommunicate_134116_Content_13 = {
    Text = "Какая милая реакция. Я вовсе не читала твои мысли."
  },
  AvgCommunicate_134116_Content_14 = {
    Text = "Просто когда ты так открыт передо мной и совсем не держишь защиту — тебя слишком легко понять."
  },
  AvgCommunicate_134116_Content_15 = {
    Text = "Хочешь уберечь маленькие секреты своей души? Тогда будь повнимательнее, когда болтаешь со мной."
  },
  AvgCommunicate_134116_Content_2 = {
    Text = "Какие ощущения? У меня какое-то нехорошее предчувствие..."
  },
  AvgCommunicate_134116_Content_3 = {
    Text = "Как бы это сказать... Примерно так: заурядные умы для меня теперь — словно раскрытый дневник, скучный и видный насквозь. Немного утомительно, знаете ли."
  },
  AvgCommunicate_134116_Content_4 = {
    Text = "Что?! Ты уже овладела чтением мыслей?!"
  },
  AvgCommunicate_134116_Content_5 = {
    Text = "Не так уж всё и страшно. В конце концов, в этом мире немало людей с крепким духом и упрямым характером, которые оборачивают свою душу слой за слоем, не позволяя другим легко заглянуть внутрь."
  },
  AvgCommunicate_134116_Content_6 = {
    Text = "А ещё есть такие, как ты — существа, окутанные вечной тайной."
  },
  AvgCommunicate_134116_Content_7 = {
    Text = "Не нервничай. Получить ответы к экзамену заранее — это так же скучно, как узнать концовку истории или имя убийцы до развязки."
  },
  AvgCommunicate_134116_Content_8 = {
    Text = "Мне доставляет огромное удовольствие этот процесс — направлять, строить догадки, нить за нитью снимая кокон, окутывающий душу."
  },
  AvgCommunicate_134116_Content_9 = {
    Text = "Без этой игры в кошки-мышки чем бы я отличалась от тех шарлатанов, которые ставят грубые диагнозы и попросту вырезают людям куски мозга?"
  },
  AvgCommunicate_134116_Option_10 = {Text = "Э-э…"},
  AvgCommunicate_134116_Option_12 = {Text = "?!!"},
  AvgCommunicate_134116_Option_2 = {
    Text = "Какие ощущения?"
  },
  AvgCommunicate_134116_Option_4 = {Text = "Что?!"},
  AvgCommunicate_134117_Content_1 = {
    Text = "Рифмы в стихах стали ещё более проникновенными."
  },
  AvgCommunicate_134117_Content_10 = {
    Text = "Я могу увести тебя в Мир поэзий, чтобы мы вместе бродили по нему."
  },
  AvgCommunicate_134117_Content_12 = {
    Text = "Это же прямо как котодама — Огромная Огромная сила слов!"
  },
  AvgCommunicate_134117_Content_13 = {
    Text = "Тогда я хочу испытать иллюзию выхода на пенсию, внезапного богатства и бесконечной еды — можешь меня туда отвести?"
  },
  AvgCommunicate_134117_Content_14 = {
    Text = "Это... наверное, да, можно! Дай мне немного времени, мне нужно хорошенько всё продумать..."
  },
  AvgCommunicate_134117_Content_2 = {
    Text = "Теперь я могу видеть эмоции, бушующие в ритмах песнопений, и силу, отражённую за этими образами."
  },
  AvgCommunicate_134117_Content_3 = {
    Text = "Не совсем понятно, но звучит как очень красивая картина."
  },
  AvgCommunicate_134117_Content_4 = {
    Text = "Да, поэзия — это ключ к постижению красоты. Она способна раскрывать всеобщие законы мира и отображать жизнь такой, какая она есть."
  },
  AvgCommunicate_134117_Content_5 = {
    Text = "В поэзии мы обретаем себя, находим мудрость истории и философии, находим чистое пристанище для духа."
  },
  AvgCommunicate_134117_Content_6 = {
    Text = "Ах, сама не заметила, как начала говорить сама с собой, прошу прощения..."
  },
  AvgCommunicate_134117_Content_7 = {
    Text = "Ничего страшного, мне нравится, как увлечённо ты говоришь о поэзии — в этом есть особое Очаровывание!"
  },
  AvgCommunicate_134117_Content_8 = {
    Text = "Спа... спасибо тебе, Страж. В общем, теперь я могу с помощью стихов заимствовать больше силы из того мира и создавать настоящую поэтическую иллюзию."
  },
  AvgCommunicate_134117_Content_9 = {
    Text = "Хочешь ли ты насладиться покоем, страстью или печалью, устремиться за ароматом цветов, морскими течениями или облаками —"
  },
  AvgCommunicate_134117_Option_12 = {
    Text = "Прямо как котодама."
  },
  AvgCommunicate_134117_Option_3 = {
    Text = "Звучит прекрасно."
  },
  AvgCommunicate_134117_Option_7 = {
    Text = "Ничего страшного."
  },
  AvgCommunicate_134118_Content_1 = {
    Text = "Ты преподнёс госпоже такую ценную вещь, ты..."
  },
  AvgCommunicate_134118_Content_10 = {
    Text = "Но ты сможешь съесть столько? Раньше повара жаловались, что ты опустошила все запасы масла и сыра, и мне пришлось за свой счёт пополнять запасы столовой."
  },
  AvgCommunicate_134118_Content_11 = {
    Text = "Ха, и кто тут втихаря ябедничает? Пусть только попадётся мне!"
