  AvgCommunicate_134118_Content_13 = {
    Text = "А если не доем — придёшь и поможешь!"
  },
  AvgCommunicate_134118_Content_14 = {
    Text = "М-мне тоже есть?! Я же лопну, а потом растолстею в расцвете лет!"
  },
  AvgCommunicate_134118_Content_15 = {
    Text = "Хватит болтать! Мы столько говорили, а я так и не упомянула твою награду. Так уж и быть, я, великодушная, буду оставлять тебе порцию каждого торта, который испеку собственными руками."
  },
  AvgCommunicate_134118_Content_16 = {
    Text = "Будь благодарен! Это шедевры гениального кондитера, которые другие и за деньги не купят!"
  },
  AvgCommunicate_134118_Content_17 = {
    Text = "Так что... эта кондитерская в итоге сама производит и сама потребляет!"
  },
  AvgCommunicate_134118_Content_2 = {
    Text = "Хмф, неплохо справился."
  },
  AvgCommunicate_134118_Content_3 = {
    Text = "Теперь госпожа может раскрутить как юлу десять — нет, сотню Пучинников за раз! Больше никому не придётся меня спасать!"
  },
  AvgCommunicate_134118_Content_4 = {
    Text = "Госпожа — Огромная Огромная сила!"
  },
  AvgCommunicate_134118_Content_5 = {
    Text = "Хотя сейчас жизнь уже не требует постоянно быть начеку, но Огромная Огромная сила — это такая штука, чем её больше, тем спокойнее на душе."
  },
  AvgCommunicate_134118_Content_6 = {
    Text = "Тот, у кого кулаки больше, никогда не останется в проигрыше!"
  },
  AvgCommunicate_134118_Content_7 = {
    Text = "Впрочем, использовать такую мощь только для работы на Мифсаг — это расточительство... О, придумала!"
  },
  AvgCommunicate_134118_Content_8 = {
    Text = "Раз столько щупалец могут работать независимо, я просто открою свою кондитерскую! Одна совмещу восемь должностей — и навсегда обеспечу себе неограниченный запас пирожных!"
  },
  AvgCommunicate_134118_Content_9 = {
    Text = "Их ещё и так можно использовать?"
  },
  AvgCommunicate_134118_Option_14 = {
    Text = "Мне тоже есть?"
  },
  AvgCommunicate_134118_Option_17 = {
    Text = "Поэтому..."
  },
  AvgCommunicate_134118_Option_4 = {
    Text = "Мёрфи — Огромная Огромная сила!"
  },
  AvgCommunicate_134118_Option_9 = {
    Text = "Их ещё и так можно использовать?"
  },
  AvgCommunicate_134119_Content_1 = {
    Text = "Ха-ха-ха... Ха-ха-ха-ха!"
  },
  AvgCommunicate_134119_Content_10 = {
    Text = "Перед абсолютной мощью завоевание — лишь долгая игра."
  },
  AvgCommunicate_134119_Content_11 = {
    Text = "Лишь бы тебе было хорошо…"
  },
  AvgCommunicate_134119_Content_12 = {
    Text = "Время принесёт тебе весть о моём триумфе. И тогда, как главному герою моего нового королевства, я пожалую тебе самый плодородный надел в качестве вотчины."
  },
  AvgCommunicate_134119_Content_13 = {
    Text = "Или… тебе больше по душе этот серый город — Лондиниум?"
  },
  AvgCommunicate_134119_Content_2 = {
    Text = "Тебя что, Огромная Огромная сила ударила в голову, и ты внезапно рехнулась?"
  },
  AvgCommunicate_134119_Content_3 = {
    Text = "Хм-хм, как мой величайший Генезис силы, я могу простить тебе маленькую дерзость."
  },
  AvgCommunicate_134119_Content_4 = {
    Text = "Ах… Момент, которого я так долго ждал, этот знакомый сладкий вкус, это ощущение, когда кровь закипает в жилах!"
  },
  AvgCommunicate_134119_Content_5 = {
    Text = "Теперь я могу с лёгкостью поднять айсберг и рассечь морскую бездну."
  },
  AvgCommunicate_134119_Content_6 = {
    Text = "Ни один вождь племени, ни один сильнейший воин среди мореходов не сможет выстоять против меня даже один раунд, и та безумная женщина тоже больше не сможет меня сдерживать."
  },
  AvgCommunicate_134119_Content_7 = {
    Text = "Скоро я покорю моря, а затем — все земли! Ха-ха-ха-ха-ха!"
  },
  AvgCommunicate_134119_Content_8 = {
    Text = "...Уверенность в себе — это хорошо, но не перебарщивай! Это уже Уровень мании величия!"
  },
  AvgCommunicate_134119_Content_9 = {
    Text = "Ты ничего не знаешь о силе великанов, малявка."
  },
  AvgCommunicate_134119_Option_11 = {
    Text = "Лишь бы тебе было хорошо…"
  },
  AvgCommunicate_134119_Option_2 = {
    Text = "Ты с ума сошла?"
  },
  AvgCommunicate_134120_Content_1 = {
    Text = "Моё пение... стало другим."
  },
  AvgCommunicate_134120_Content_10 = {
    Text = "Да, я буду!"
  },
  AvgCommunicate_134120_Content_11 = {
    Text = "Кстати, Страж, благодаря твоим наставлениям я согласилась на сотрудничество с музыкальной компанией. Первый альбом уже официально вышел, и, говорят, продаётся очень хорошо."
  },
  AvgCommunicate_134120_Content_12 = {
    Text = "Это же прекрасно! Поздравляю! И сколько копий продали?"
  },
  AvgCommunicate_134120_Content_13 = {
    Text = "Кажется... сто тысяч копий. Но мне не нужна валюта этой планеты, и раз уж мне больше нечем тебя отблагодарить, давай я просто переведу тебе всю выручку от продаж."
  },
  AvgCommunicate_134120_Content_14 = {Text = "Ура!!!"},
  AvgCommunicate_134120_Content_2 = {
    Text = "Страж, после того как ты помог мне постичь высший закон, мой голос, кажется, вступил в удивительный Резонанс с эфиром."
  },
  AvgCommunicate_134120_Content_3 = {
    Text = "Похоже, ты стала сильнее. Фейнт тоже наверняка обрадуется!"
  },
  AvgCommunicate_134120_Content_4 = {
    Text = "Как мне отблагодарить тебя, Страж? Воссоединиться с сестрой — это уже было счастьем, о котором прежняя я не смела и мечтать, а ты ещё подарил мне такое бесценное сокровище."
  },
  AvgCommunicate_134120_Content_5 = {
    Text = "Сейчас у меня ничего нет, и я больше не звезда, которой все восхищаются. Единственное, чем я могу отблагодарить тебя... Позволь мне спеть для тебя песню."
  },
  AvgCommunicate_134120_Content_6 = {
    Text = "Тинкт, ты уже нашла свой путь. И если ты хочешь исполнить моё желание..."
  },
  AvgCommunicate_134120_Content_7 = {
    Text = "Пой свободно — ради себя и ради меня."
  },
  AvgCommunicate_134120_Content_8 = {
    Text = "Не ради того, чтобы угодить кому-то, не ради выполнения чьих-то требований — только ради собственной радости."
  },
  AvgCommunicate_134120_Content_9 = {
    Text = "Моей собственной... радости."
  },
  AvgCommunicate_134120_Option_12 = {
    Text = "Это же прекрасно!"
  },
  AvgCommunicate_134120_Option_14 = {Text = "?!!"},
  AvgCommunicate_134120_Option_3 = {
    Text = "Замечательно!"
  },
  AvgCommunicate_134120_Option_6 = {
    Text = "А ты не думала о том, что..."
  },
  AvgCommunicate_134180_Content_1 = {
    Text = "Ветер наполняет паруса, птицы летят рядом стройной вереницей……"
  },
  AvgCommunicate_134180_Content_10 = {
    Text = "Я хочу вместе с тобой, с капитаном, со всеми — плыть и плыть по морю, бесконечно."
  },
  AvgCommunicate_134180_Content_11 = {
    Text = "Вместе переживать солнечные и дождливые дни, вместе заходить в самые разные порты, причаливать в разных странах."
  },
  AvgCommunicate_134180_Content_12 = {
    Text = "Вместе рыбачить, жарить рыбу… А ещё можно соскрести мидий с корпуса корабля и потушить их в красном вине."
  },
  AvgCommunicate_134180_Content_13 = {
    Text = "Поедем в следующий отпуск."
  },
  AvgCommunicate_134180_Content_14 = {
    Text = "Я долго думала, и… плавание — это самое счастливое время для меня."
  },
  AvgCommunicate_134180_Content_15 = {
    Text = "Я уведу всех от любых штормов, и мы будем счастливо плыть дальше вместе."
  },
  AvgCommunicate_134180_Content_16 = {
    Text = "Звучит прекрасно, но если плыть без остановки, то, кроме пробуждённых из области Глубоководья, всех укачает!"
  },
  AvgCommunicate_134180_Content_2 = {
    Text = "Я вижу, как нос корабля рассекает волны, я слышу, как матросы затягивают песню, я ощущаю знаки ветра и дождя."
  },
  AvgCommunicate_134180_Content_3 = {
    Text = "Теперь я яснее вижу тот курс, что ведёт к ясным и спокойным водам."
  },
  AvgCommunicate_134180_Content_4 = {
    Text = "Поздравляю тебя! Хилэстэ!"
  },
  AvgCommunicate_134180_Content_5 = {
    Text = "Теперь я, возможно, действительно смогу исполнить желания всех и привести корабли под моей защитой к безопасному берегу."
  },
  AvgCommunicate_134180_Content_6 = {
    Text = "Я больше никого не подведу."
  },
  AvgCommunicate_134180_Content_7 = {
    Text = "А как же твоё желание? Ты уже решила, чего хочешь?"
  },
  AvgCommunicate_134180_Content_8 = {
    Text = "Моё желание……"
  },
  AvgCommunicate_134180_Content_9 = {
    Text = "Я уже решила."
  },
  AvgCommunicate_134180_Option_13 = {
    Text = "Поедем в следующий отпуск."
  },
  AvgCommunicate_134180_Option_16 = {
    Text = "Звучит прекрасно."
  },
  AvgCommunicate_134180_Option_4 = {
    Text = "Поздравляю"
  },
  AvgCommunicate_134180_Option_7 = {
    Text = "А ты сама?"
  },
  AvgCommunicate_134181_Content_1 = {
    Text = "Ах… Призыв океана, такой нежный, такой тёплый."
  },
  AvgCommunicate_134181_Content_10 = {
    Text = "Это грубые выходки Роджерса оставили в тебе такой след, или ты считаешь меня настолько бездарным и ленивым художником?"
  },
  AvgCommunicate_134181_Content_11 = {
    Text = "В оттачивании мастерства нет коротких путей. Каждую свою скульптуру я вырезаю собственными руками, Удар за ударом."
  },
  AvgCommunicate_134181_Content_12 = {
    Text = "Не волнуйся, даже волосок твой не понадобится."
  },
  AvgCommunicate_134181_Content_13 = {
    Text = "Ха-ха… Возможно, твоё мастерство скульптора слишком велико — каждый раз, глядя на твои работы, мне кажется, что передо мной живой человек."
  },
  AvgCommunicate_134181_Content_14 = {
    Text = "Хм… Что ж, теперь, когда моя Огромная Огромная сила достигла предела, может быть, я и Правда смогу создать скульптуру, которая оживёт."
  },
  AvgCommunicate_134181_Content_15 = {
    Text = "В безмолвии глубокой ночи, когда ты не смотришь, глаза скульптуры медленно поворачиваются, а уголки губ слегка приподнимаются……"
  },
  AvgCommunicate_134181_Content_16 = {
    Text = "Когда я закончу свою новую работу, поставлю одну скульптуру у твоей кровати, чтобы она присматривала за тобой вместо меня. Как тебе идея?"
  },
  AvgCommunicate_134181_Content_17 = {
    Text = "Я тогда всю жизнь не смогу уснуть!!!"
  },
  AvgCommunicate_134181_Content_18 = {
    Text = "Я пошутила."
  },
  AvgCommunicate_134181_Content_19 = {
    Text = "Похоже, ты и Правда очень боишься таких простых страшилок. Какая прелесть."
  },
  AvgCommunicate_134181_Content_2 = {
    Text = "Ты ведь тоже его слышишь, Правда?"
  },
  AvgCommunicate_134181_Content_3 = {
    Text = "Он приглашает нас, они ждут нас… отправиться вместе в белоснежный дворец на дне морском."
  },
  AvgCommunicate_134181_Content_4 = {
    Text = "Кто? Боюсь, я оглох — ничего не слышу."
  },
  AvgCommunicate_134181_Content_5 = {
    Text = "Тогда это поцелуй музы, предназначенный лишь мне. Красота океана теперь слилась с моей душой."
  },
  AvgCommunicate_134181_Content_6 = {
    Text = "Ты всегда приносишь мне новое вдохновение для творчества. Ты нравишься мне всё больше и больше."
  },
  AvgCommunicate_134181_Content_7 = {
    Text = "Не хочешь стать моим постоянным помощником? Тебе ничего не нужно делать — просто приходи каждый день в мою мастерскую, посиди немного, выпей чашку чая, поболтай."
  },
  AvgCommunicate_134181_Content_8 = {
    Text = "Хоть мне и лестно твоё расположение, но… не проснусь ли я однажды каменной статуей?"
  },
  AvgCommunicate_134181_Content_9 = {
    Text = "Хе-хе, вот, значит, как ты обо мне думаешь?"
  },
  AvgCommunicate_134181_Option_13 = {
    Text = "Ты слишком искусный мастер."
  },
  AvgCommunicate_134181_Option_17 = {
    Text = "Не надо!!!"
  },
  AvgCommunicate_134181_Option_4 = {
    Text = "Я ничего не слышу."
  },
  AvgCommunicate_134181_Option_8 = {
    Text = "Меня превратят в скульптуру?"
  },
  AvgCommunicate_134187_Content_1 = {
    Text = "Пёсик, как дела в последнее время?"
  },
  AvgCommunicate_134187_Content_10 = {
    Text = "Не делай глупостей. Что бы ни случилось, Чёрный Пруд будет крепко держать тебя в оковах."
  },
  AvgCommunicate_134187_Content_11 = {
    Text = "Вы даже не представляете, какую силу могут дать мне знания."
  },
  AvgCommunicate_134187_Content_12 = {
    Text = "Я весьма довольна этим подарком, поэтому, мой любимый ученик, я тоже хочу сделать тебе Подарок."
  },
  AvgCommunicate_134187_Content_13 = {Text = "…?"},
  AvgCommunicate_134187_Content_14 = {
    Text = "Гадайте, гадайте, на что я теперь способна."
  },
  AvgCommunicate_134187_Content_15 = {
    Text = "Гадайте, сработают ли ваши самонадеянные ограничительные меры."
  },
  AvgCommunicate_134187_Content_16 = {
    Text = "Гадайте, будет ли та истина, которую я узрела, после обретения мной этой силы внедрена в сознание каждого из вас."
  },
  AvgCommunicate_134187_Content_17 = {
    Text = "Это самое важное домашнее задание. Совсем скоро, совсем скоро я приду проверить его лично."
  },
  AvgCommunicate_134187_Content_2 = {
    Text = "Твоя дерзость поразила меня — ты посмел прислать Подарок такого уровня."
  },
  AvgCommunicate_134187_Content_3 = {
    Text = "Если я скажу, что при транспортировке редких материалов произошёл серьёзный инцидент, ты поверишь?.."
  },
  AvgCommunicate_134187_Content_5 = {
    Text = "Ты недооценил и меня, и Мисагу."
  },
  AvgCommunicate_134187_Content_6 = {
    Text = "Мы готовы позволить каждому пробуждённому прикоснуться к этому пределу, потому что ради предотвращения гибели мы испробуем все способы."
  },
  AvgCommunicate_134187_Content_7 = {
    Text = "Это… то, чем учительница Доэль, и мы, больше всего отличаемся от тебя — даже если гибель предрешена, мы не покоримся ей."
  },
  AvgCommunicate_134187_Content_8 = {
    Text = "Эх, как я раньше не замечала, что система образования Мисаги воспитывает дурачков."
  },
  AvgCommunicate_134187_Content_9 = {
    Text = "К счастью, это настолько глупый и жалкий дурачок, что невозможно удержаться от нежности к нему."
  },
  AvgCommunicate_134187_Option_13 = {Text = "…?"},
  AvgCommunicate_134187_Option_3 = {
    Text = "Это случайность."
  },
  AvgCommunicate_134187_Option_5 = {
    Text = "Это от чистого сердца."
  },
  AvgCommunicate_134188_Content_1 = {
    Text = "Законы, так круто! Бах—! Бум—! Бабах—!"
  },
  AvgCommunicate_134188_Content_11 = {
    Text = "Раз так, расходы на Ежедневное обслуживание школы в этом месяце должны значительно сократиться…"
  },
  AvgCommunicate_134188_Content_12 = {
    Text = "Плохая домашка, появилась, Моск, убить!"
  },
  AvgCommunicate_134188_Content_13 = {
    Text = "Нет, нельзя считать домашнее задание врагом!"
  },
  AvgCommunicate_134188_Content_14 = {
    Text = "Моск, Моск?"
  },
  AvgCommunicate_134188_Content_16 = {
    Text = "Страж, это Нотира. Не волнуйтесь, Моск удержана, домашнее задание и класс в безопасности."
  },
  AvgCommunicate_134188_Content_17 = {
    Text = "Слава богу…"
  },
  AvgCommunicate_134188_Content_18 = {
    Text = "Нотира, мы с Мисагой и Моск всегда будем в тебе нуждаться."
  },
  AvgCommunicate_134188_Content_2 = {
    Text = "Запомни первое правило кодекса Мессагера, специальная редакция для Моск: ни при каких обстоятельствах нельзя направлять любое поражающее оружие на кого-либо из Мессагера."
  },
  AvgCommunicate_134188_Content_5 = {
    Text = "%player%, не волнуйся, Моск, контроль, может!"
  },
  AvgCommunicate_134188_Content_6 = {
    Text = "Моск, сдерживать, водоворот."
  },
  AvgCommunicate_134188_Content_7 = {
    Text = "Моск, Близкий Близкий друг, обнимашки."
  },
  AvgCommunicate_134188_Content_8 = {
    Text = "Моск, враг, бах—! бум—! бабах—!"
  },
  AvgCommunicate_134188_Option_2 = {
    Text = "Безопасность прежде всего."
  },
  AvgCommunicate_134189_Content_1 = {
    Text = "Мы боевые товарищи, поэтому я не буду говорить «спасибо»."
  },
  AvgCommunicate_134189_Content_2 = {
    Text = "Моё оружие заточено до предела — настолько остро, что может в мгновение перерезать горло рабовладельцу."
  },
  AvgCommunicate_134189_Content_3 = {
    Text = "Смысл сопротивления, смысл мести, смысл битвы — я до сих пор непрестанно размышляю об этом."
  },
  AvgCommunicate_134189_Content_4 = {
    Text = "Возможно, я продолжу размышлять об этом и дальше, до того дня, когда уже не смогу подняться на ноги."
  },
  AvgCommunicate_134189_Content_5 = {
    Text = "По крайней мере, я больше не буду блуждать в сомнениях."
  },
  AvgCommunicate_134189_Content_6 = {
    Text = "За моих боевых товарищей."
  },
  AvgCommunicate_134189_Content_7 = {
    Text = "За боевых товарищей — это вы дали мне освобождение и помогли твёрдо идти вперёд."
  },
  AvgCommunicate_134189_Content_8 = {
    Text = "Когда я буду вам нужна, я всегда доверю вам свою спину и буду сражаться бок о бок с вами."
  },
  AvgCommunicate_134189_Content_9 = {
    Text = "Продолжим сражаться вместе — ради того, за что следует отомстить, и ради наслаждения упоением битвы."
  },
  AvgCommunicate_134189_Option_6 = {
    Text = "За боевых товарищей."
  },
  AvgCommunicate_134201_Content_1 = {
    Text = "Страж, я подала заявление в учебную часть — меня не будет на тренировках ближайшие три дня."
  },
  AvgCommunicate_134201_Content_10 = {
    Text = "Но, преодолев свой предел, я поняла."
  },
  AvgCommunicate_134201_Content_11 = {Text = "Что?"},
  AvgCommunicate_134201_Content_13 = {
    Text = "Я — клинок первопроходца. Именно потому, что я всегда шла по этому пути, я смогла встретить всех вас и тебя."
  },
  AvgCommunicate_134201_Content_14 = {
    Text = "Моё стремление не даёт мне быть одинокой. Возможно, мы никогда не достигнем цели, но пока мы не сдаёмся, я могу приблизить тот идеальный, справедливый мир — ещё чуть-чуть, и ещё чуть-чуть."
  },
  AvgCommunicate_134201_Content_15 = {
    Text = "Я сама стану клинком — и буду идти, пока не достигну утопии, где каждый сможет жить в свете."
  },
  AvgCommunicate_134201_Content_16 = {
    Text = "Какое великое стремление, инструктор Эльва! Я буду поддерживать тебя безоговорочно!"
  },
  AvgCommunicate_134201_Content_17 = {
    Text = "Отлично. Раз так, я потрачу эти три дня на разработку ещё более суровой и сложной программы тренировок."
  },
  AvgCommunicate_134201_Content_18 = {
    Text = "Ты будешь в числе первых, кто её опробует. Не волнуйся — я буду сопровождать вас на протяжении всего процесса, тренируясь вместе со всеми."
  },
  AvgCommunicate_134201_Content_19 = {
    Text = "Подожди, мне кажется, это ещё можно обсудить…"
  },
  AvgCommunicate_134201_Content_2 = {
    Text = "Может, проблема с материалами? Ты в порядке? Нужна помощь?"
  },
  AvgCommunicate_134201_Content_3 = {
    Text = "Нет, как раз наоборот — всё идёт отлично. У меня произошёл прорыв, отличающийся от прежних."
  },
  AvgCommunicate_134201_Content_4 = {
    Text = "Я не совсем понимаю..."
  },
  AvgCommunicate_134201_Content_5 = {
    Text = "Я... после ухода из армии долгое время была потеряна."
  },
  AvgCommunicate_134201_Content_6 = {
    Text = "Я не знала, ради чего мне сражаться. Единственное, чему я могла следовать, — это справедливость, в достижении которой я даже не была уверена."
  },
  AvgCommunicate_134201_Content_7 = {
    Text = "Я хотела встать на сторону слабых, на сторону тех, кто не может за себя постоять, на сторону тех, с кем обходятся несправедливо."
  },
  AvgCommunicate_134201_Content_8 = {
    Text = "Но я прекрасно понимала: как бы сильной я ни стала, всегда найдётся то, что мне не под силу. Даже если бы время повернулось вспять, я всё равно не смогла бы предотвратить гибель Алана."
  },
  AvgCommunicate_134201_Content_9 = {
    Text = "Инструктор Эльва..."
  },
  AvgCommunicate_134201_Option_2 = {
    Text = "Что-то случилось?"
  },
  AvgCommunicate_134202_Content_1 = {
    Text = "Спасибо, что доверил мне такую ценную вещь, %player%."
  },
  AvgCommunicate_134202_Content_10 = {
    Text = "Мне кажется, это говорит о том, что помимо следов в памяти, мир можно измерить собственными шагами."
  },
  AvgCommunicate_134202_Content_11 = {
    Text = "Если не можешь удержать — просто иди вперёд, всё дальше и дальше. Мир и вы все запомните за меня."
  },
  AvgCommunicate_134202_Content_12 = {
    Text = "Даже у меня кровь закипает от воодушевления..."
  },
  AvgCommunicate_134202_Content_13 = {
    Text = "Я стану величайшим исследователем, лучшим мастером механики! %player%, я хочу официально пригласить тебя."
  },
  AvgCommunicate_134202_Content_14 = {
    Text = "Когда наступит день, когда всё будет решено, отправься со мной в приключение — создадим ещё больше драгоценных воспоминаний в этом мире."
  },
  AvgCommunicate_134202_Content_15 = {
    Text = "Возможно, этот день ещё далеко, а возможно — уже завтра."
  },
  AvgCommunicate_134202_Content_16 = {
    Text = "Это Приглашение действует бессрочно, я обязательно запомню это."
  },
  AvgCommunicate_134202_Content_2 = {
    Text = "Я очень долго её осмысляла, и теперь... мне кажется, что я снова стала целой."
  },
  AvgCommunicate_134202_Content_3 = {
    Text = "То есть теперь ты не будешь забывать?"
  },
  AvgCommunicate_134202_Content_4 = {
    Text = "Хм, дай подумать..."
  },
  AvgCommunicate_134202_Content_5 = {
    Text = "Ха-ха, всё равно не запоминаю!"
  },
  AvgCommunicate_134202_Content_6 = {
    Text = "Почему ты говоришь это с такой гордостью?!"
  },
  AvgCommunicate_134202_Content_7 = {
    Text = "Потому что, хоть я, возможно, и буду забывать многое, в прошлом и сейчас %player% всегда напоминает мне и помогает вспомнить."
  },
  AvgCommunicate_134202_Content_8 = {
    Text = "Кто я, где я, что мне делать — мне подскажут те, кому я доверяю больше всего."
  },
  AvgCommunicate_134202_Content_9 = {
    Text = "Может, именно поэтому, постигнув высший закон, хоть память и не улучшилась, я чувствую, будто весь мир раскинулся передо мной, словно бескрайняя Карта."
  },
  AvgCommunicate_134202_Option_3 = {
    Text = "Твоя память улучшилась?"
  },
  AvgCommunicate_134208_Content_1 = {
    Text = "Когда-то я думала, что ощутить радость неизведанного можно лишь играя роль зрителя."
  },
  AvgCommunicate_134208_Content_10 = {
    Text = "Хоть я и не до конца понимаю… но звучит так, будто это что-то хорошее?"
  },
  AvgCommunicate_134208_Content_11 = {
    Text = "С тех пор как я покинула ту Ворота, это величайшая удача, что мне довелось встретить."
  },
  AvgCommunicate_134208_Content_12 = {
    Text = "Страж Тайн, это сюрприз, который вы мне подарили, — тот, что я не могла предвидеть."
  },
  AvgCommunicate_134208_Content_13 = {
    Text = "Судьба никогда не обделяет щедрых дарителей."
  },
  AvgCommunicate_134208_Content_14 = {
    Text = "Я не могу коснуться ваших нитей, но пока вы сражаетесь за судьбу, моё веретено будет вечно вращаться для вас."
  },
  AvgCommunicate_134208_Content_2 = {
    Text = "Я уже очень, очень давно не испытывала подобного чувства…"
  },
  AvgCommunicate_134208_Content_3 = {
    Text = "Какие ощущения?"
  },
  AvgCommunicate_134208_Content_4 = {
    Text = "Новизна."
  },
  AvgCommunicate_134208_Content_5 = {
    Text = "Тихое распускание бутонов, переплетение слов на бумаге, нежное движение облаков в ветре…"
  },
  AvgCommunicate_134208_Content_6 = {
    Text = "И, конечно, люди — их распростёртые руки, падающие слёзы, их сердцебиение, подобное бою барабанов или каплям дождя…"
  },
  AvgCommunicate_134208_Content_7 = {
    Text = "Я вижу больше, чем прежде, но мой взор опустился ниже."
  },
  AvgCommunicate_134208_Content_8 = {
    Text = "Он больше не задерживается в небесах, Страж Тайн. Он опустился вниз — на каждую улицу, к каждому прохожему."
  },
  AvgCommunicate_134208_Content_9 = {
    Text = "Теперь мне не нужно притворяться. Я могу по-настоящему существовать как отдельная личность."
  },
  AvgCommunicate_134208_Option_10 = {
    Text = "Звучит как что-то хорошее?"
  },
  AvgCommunicate_134208_Option_3 = {
    Text = "Какие ощущения?"
  },
  AvgCommunicate_134242_Content_1 = {
    Text = "временный текст"
  },
  AvgCommunicate_134245_Content_1 = {
    Text = "Кажется, это очень ценная вещь — не проблема ли отдать её Сае?"
  },
  AvgCommunicate_134245_Content_12 = {
    Text = "Оказывается, у этого мира тоже есть своя красота, хотя он немного отличается от мира в моих воспоминаниях."
  },
  AvgCommunicate_134245_Content_13 = {
    Text = "Принципы устройства, логику движения — Сая уже полностью способна понять."
  },
  AvgCommunicate_134245_Content_14 = {
    Text = "Поэтому Переписывание этого мира в тот, что хранится в моих воспоминаниях, — сейчас мне, пожалуй, удалось бы сделать это очень легко."
  },
  AvgCommunicate_134245_Content_16 = {
    Text = "Хотя я знаю, что ты шутишь, но прошу — ни в коем случае не делай ничего подобного."
  },
  AvgCommunicate_134245_Content_18 = {
    Text = "Почему ты замолчал? Это же шутка, правда? Не молчи в такой момент!"
  },
  AvgCommunicate_134245_Content_19 = {
    Text = "Понимаешь, только что я просто ненадолго вышла и посмотрела на всех с новой точки зрения…"
  },
  AvgCommunicate_134245_Content_2 = {
    Text = "Я доверяю Сае, так что всё в порядке."
  },
  AvgCommunicate_134245_Content_20 = {
    Text = "Пока знакомые, добрые к Сае люди живы и здоровы — вот как это выглядит."
  },
  AvgCommunicate_134245_Content_21 = {
    Text = "Не могу сказать, что именно не так, но почему-то чувствую, что что-то определённо не так."
  },
  AvgCommunicate_134245_Content_22 = {
    Text = "И к тому же сейчас на твоём лице наверняка снова то самое выражение довольного проказника!"
  },
  AvgCommunicate_134245_Content_23 = {
    Text = "Не беспокойся — буду хорошо ладить со всеми в этом мире."
  },
  AvgCommunicate_134245_Content_24 = {
    Text = "Хм… Но мир из воспоминаний Саи, наверное, куда интереснее. Может, сходим туда все вместе? Сейчас это должно быть возможно!"
  },
  AvgCommunicate_134245_Content_25 = {
    Text = "Это звучит ещё страшнее!"
  },
  AvgCommunicate_134245_Content_3 = {
    Text = "Если это поможет тебе лучше понять этот мир, то и для исследования «как остановить Растоврение» это тоже должно быть большим подспорьем."
  },
  AvgCommunicate_134245_Content_4 = {
    Text = "Всё-таки в учёбе и исследованиях ты действительно очень сильна…"
  },
  AvgCommunicate_134245_Content_5 = {
    Text = "На самом деле это была случайная поставка… но сейчас уже, наверное, поздно передумывать?"
  },
  AvgCommunicate_134245_Content_6 = {
    Text = "Ой? Тогда, может, вернуть? Немного затрудняюсь."
  },
  AvgCommunicate_134245_Content_7 = {
    Text = "Что? Можно вернуть?"
  },
  AvgCommunicate_134245_Content_8 = {
    Text = "Хм, позволь Сае подумать…"
  },
  AvgCommunicate_134245_Content_9 = {
    Text = "Ответ — нет."
  },
  AvgCommunicate_134245_Option_2 = {
    Text = "Без проблем"
  },
  AvgCommunicate_134245_Option_5 = {
    Text = "Это случайность"
  },
  AvgCommunicate_134246_Content_1 = {
    Text = "Дорогой, любимый, замечательный благодетель Карабу~"
  },
  AvgCommunicate_134246_Content_10 = {
    Text = "Я проверю."
  },
  AvgCommunicate_134246_Content_11 = {
    Text = "Позвольте проверить данные колебаний вашего Индекса гнозиса."
  },
  AvgCommunicate_134246_Content_12 = {
    Text = "Редкость — на этот раз ты действительно не солгала."
  },
  AvgCommunicate_134246_Content_13 = {
    Text = "Хм-хм, теперь верите бедняжке Карабу~"
  },
  AvgCommunicate_134246_Content_14 = {
    Text = "Чтобы Карабу в будущем принесла благодетелю прибыль в сотни и тысячи раз больше, прошу благодетеля продолжать щедро вкладываться в меня!"
  },
  AvgCommunicate_134246_Content_15 = {
    Text = "Ещё восемь, нет — пять Озарений! И я непременно снова заставлю вас смотреть на меня другими глазами!"
  },
  AvgCommunicate_134246_Content_16 = {
    Text = "Невозможно."
  },
  AvgCommunicate_134246_Content_17 = {
    Text = "Не обманывай."
  },
  AvgCommunicate_134246_Content_18 = {
    Text = "Профессор Долл говорил мне, что исследование Озарения достигло своего предела — прорыва не будет ещё сотню лет."
  },
  AvgCommunicate_134246_Content_19 = {
    Text = "После постижения конечного закона Пробуждённый больше не может углублять личность."
  },
  AvgCommunicate_134246_Content_2 = {
    Text = "Вдруг такой медовый язык — чего на этот раз нужно?"
  },
  AvgCommunicate_134246_Content_21 = {
    Text = "Ха-ха, наверное, я случайно что-то напутал!"
  },
  AvgCommunicate_134246_Content_22 = {
    Text = "Пожалуйста, откатите память диалога на шесть реплик назад, желаю вам хорошего настроения!"
  },
  AvgCommunicate_134246_Content_3 = {
    Text = "Ну что вы такое говорите, за кого вы меня принимаете — будто я прихожу только когда что-то нужно."
  },
  AvgCommunicate_134246_Content_4 = {
    Text = "Ты именно такой человек…"
  },
  AvgCommunicate_134246_Content_5 = {
    Text = "Уу-уу, мне так обидно, благодетель так сильно меня недооценивает."
  },
  AvgCommunicate_134246_Content_6 = {
    Text = "Я пришла на этот раз, чтобы сообщить вам одну хорошую новость!"
  },
  AvgCommunicate_134246_Content_7 = {
    Text = "Ваши инвестиции принесли супер-, супер-впечатляющие результаты."
  },
  AvgCommunicate_134246_Content_8 = {
    Text = "Посмотрите — я уже совсем другой человек, переродилась, изменилась до неузнаваемости~"
  },
  AvgCommunicate_134246_Content_9 = {
    Text = "Правда?"
  },
  AvgCommunicate_134246_Option_10 = {
    Text = "Я проверю"
  },
  AvgCommunicate_134246_Option_16 = {
    Text = "Невозможно"
  },
  AvgCommunicate_134246_Option_17 = {
    Text = "Не обманывай"
  },
  AvgCommunicate_134246_Option_9 = {
    Text = "Правда?"
  },
  AvgCommunicate_134247_Content_1 = {
    Text = "временный текст"
  },
  AvgCommunicate_134249_Content_1 = {
    Text = "Страж…"
  },
  AvgCommunicate_134249_Content_10 = {
    Text = "У-у… Это чувство снова вернулось. Мне вдруг стало жарко и захотелось пить. В животе, внутри живота,"
  },
  AvgCommunicate_134249_Content_11 = {
    Text = "Страж, я что, заболела? Мой желудок размягчается, сердце тоже размягчается, всё мягкое, я не могу разобрать, будто я вот-вот растаю…"
  },
  AvgCommunicate_134249_Content_12 = {
    Text = "Глубокий вдох, Рейя. Ты не растаешь."
  },
  AvgCommunicate_134249_Content_13 = {
    Text = "Это нормальная реакция людей в близких отношениях, лекарства не нужны… И плётку тоже не нужно доставать!"
  },
  AvgCommunicate_134249_Content_14 = {
    Text = "А? Даже плётку не нужно? Как разочаровывает."
  },
  AvgCommunicate_134249_Content_16 = {
    Text = "…Э-э, если тебе так уж необходимо, может, обратись к Пандии…"
  },
  AvgCommunicate_134249_Content_17 = {Text = "Хе-хе."},
  AvgCommunicate_134249_Content_18 = {
    Text = "Страж, я постараюсь больше не сидеть на корточках у вашей двери."
  },
  AvgCommunicate_134249_Content_19 = {
    Text = "Но… не могли бы вы иногда оставлять для меня открытой Ворота на ночь? Окно тоже подойдёт."
  },
  AvgCommunicate_134249_Content_2 = {
    Text = "Плоть брата и моё тело стали совместимее, чем раньше. Она тихо дышит под кожей и больше не кричит, пытаясь Разрыв меня изнутри."
  },
  AvgCommunicate_134249_Content_20 = {
    Text = "Я не буду заходить, просто знание того, что есть путь, ведущий к вам в любой момент, поможет мне спать спокойнее."
  },
  AvgCommunicate_134249_Content_3 = {
    Text = "И жажда крови уже не так мучительна. Раньше было словно что-то застряло в горле — не выпьешь — задохнёшься. А теперь она будто… готова немного подождать."
  },
  AvgCommunicate_134249_Content_4 = {
    Text = "Это действительно хорошая новость."
  },
  AvgCommunicate_134249_Content_5 = {
    Text = "Вечерами в школе так тихо. Только фонтан журчит."
  },
  AvgCommunicate_134249_Content_6 = {
    Text = "Страж Тайн, вы дали мне столько сокровищ… Я этого достойна?"
  },
  AvgCommunicate_134249_Content_7 = {
    Text = "Конечно, стоит."
  },
  AvgCommunicate_134249_Content_8 = {
    Text = "…Вы каждый раз отвечаете так быстро."
  },
  AvgCommunicate_134249_Content_9 = {
    Text = "Рейя, ты очень нам помогла. Это меньшее, что я могу сделать."
  },
  AvgCommunicate_134250_Content_1 = {
    Text = "Тебе неизвестно, чем заканчивается содержание хищного зверя?"
  },
  AvgCommunicate_134250_Content_10 = {
    Text = "Я часто думаю — ты действительно такой, каким кажешься, или..."
  },
  AvgCommunicate_134250_Content_11 = {
    Text = "На самом деле ты всё время притворяешься, как те рабовладельцы."
  },
  AvgCommunicate_134250_Content_12 = {
    Text = "А ты как думаешь? Я не умею притворяться и не умею лгать."
  },
  AvgCommunicate_134250_Content_13 = {
    Text = "Ты можешь довериться своим чувствам. Я не стану тебя убеждать и не буду заставлять что-либо делать."
  },
  AvgCommunicate_134250_Content_14 = {
    Text = "Как говорила другая ты — мы друзья, мы соратники."
  },
  AvgCommunicate_134250_Content_15 = {
    Text = "Тц, не смей ставить меня в один ряд с этой слабачкой."
  },
  AvgCommunicate_134250_Content_16 = {
    Text = "Я давно сыта предательствами по горло. Мне вообще не нужны друзья."
  },
  AvgCommunicate_134250_Content_17 = {
    Text = "И мне не нужны никакие твои обещания."
  },
  AvgCommunicate_134250_Content_18 = {
    Text = "Просто дай мне больше силы — этого достаточно."
  },
  AvgCommunicate_134250_Content_19 = {
    Text = "А я отомщу твоим врагам вместе с тобой."
  },
  AvgCommunicate_134250_Content_2 = {
    Text = "Выросший зверь разорвёт цепи и — ррр! — перегрызёт глотку своему хозяину."
  },
  AvgCommunicate_134250_Content_20 = {
    Text = "Но в тот день, когда ты действительно меня предашь… даже если сбежишь на край света, я догоню тебя и перегрызу тебе горло."
  },
  AvgCommunicate_134250_Content_3 = {
    Text = "Сейчас наша с тобой связь в моих глазах хрупче железных цепей."
  },
  AvgCommunicate_134250_Content_4 = {
    Text = "Тебе не страшно?"
  },
  AvgCommunicate_134250_Content_5 = {
    Text = "Ты свободна, наша связь не предназначена для того, чтобы тебя ограничивать."
  },
  AvgCommunicate_134250_Content_6 = {
    Text = "Мне нечего бояться."
  },
  AvgCommunicate_134250_Content_8 = {
    Text = "Тц, красивые слова."
  },
  AvgCommunicate_134250_Content_9 = {
    Text = "Впрочем, я наблюдала за тобой так долго и до сих пор не заметила, чтобы ты хоть раз себя выдал."
  },
  AvgCommunicate_134250_Option_12 = {
    Text = "Как думаешь?"
  },
  AvgCommunicate_134250_Option_5 = {
    Text = "Ты свободна"
  },
  AvgCommunicate_134263_Content_1 = {
    Text = "Страж!!"
  },
  AvgCommunicate_134263_Content_10 = {
    Text = "Конечно. Я никогда не сомневался, что ты станешь сильнее."
  },
  AvgCommunicate_134263_Content_12 = {
    Text = "Ты и Правда странный человек."
  },
  AvgCommunicate_134263_Content_13 = {
    Text = "В такие моменты разве не стоит сказать что-нибудь вроде «Видишь, я в тебе не ошибся» или «Ты оправдал мои ожидания»?"
  },
  AvgCommunicate_134263_Content_14 = {
    Text = "Почему ты так спокоен?"
  },
  AvgCommunicate_134263_Content_16 = {
    Text = "Э-э... Потому что ты так старался — стать сильнее было само собой разумеющимся. Что тут ещё говорить."
  },
  AvgCommunicate_134263_Content_17 = {
    Text = "Те 50 монет, что ты вернул мне позапрошлый год, и 54 монеты за прошлый — я всё ещё их храню."
  },
  AvgCommunicate_134263_Content_18 = {
    Text = "Зачем хранить... Потрать их уже."
  },
  AvgCommunicate_134263_Content_19 = {
    Text = "Ладно, хватит об этом, есть дело поважнее."
  },
  AvgCommunicate_134263_Content_2 = {
    Text = "Эти узоры пылают жаром, Огромная Огромная сила глубин течёт под кожей, гораздо отчётливее, чем раньше!"
  },
  AvgCommunicate_134263_Content_20 = {
    Text = "Быстрее приходи к озеру, я тут тебя жду."
  },
  AvgCommunicate_134263_Content_21 = {
    Text = "Что случилось?"
  },
  AvgCommunicate_134263_Content_22 = {
    Text = "Придёшь — узнаешь."
  },
  AvgCommunicate_134263_Content_23 = {
    Text = "Ладно... Тогда подожди немного. Сейчас на улице дождь, мне нужно сначала вернуться в общежитие за зонтом."
  },
  AvgCommunicate_134263_Content_24 = {
    Text = "Хватит копаться, для наших дальнейших планов зонт не понадобится."
  },
  AvgCommunicate_134263_Content_25 = {
    Text = "Ты не промокнешь — мои перепончатые крылья достаточно большие."
  },
  AvgCommunicate_134263_Content_3 = {
    Text = "Ты знаешь, что это за ощущение?!"
  },
  AvgCommunicate_134263_Content_4 = {
    Text = "В общем, это невероятно, словами не описать, вам, людям, наверное, сложно понять."
  },
  AvgCommunicate_134263_Content_5 = {
    Text = "…Кейкос, ты в порядке?"
  },
  AvgCommunicate_134263_Content_6 = {
    Text = "Конечно в порядке, никогда ещё не чувствовал себя так хорошо."
  },
  AvgCommunicate_134263_Content_7 = {
    Text = "Я давно говорил, что твои вложения не пропадут зря. Моя кровь меня не обманет."
  },
  AvgCommunicate_134263_Content_8 = {
    Text = "Я знаю."
  },
  AvgCommunicate_134263_Content_9 = {
    Text = "…И это всё?"
  },
  AvgCommunicate_134264_Content_1 = {
    Text = "Прости меня, бледный посланник, я была не вполне к этому готова и, кажется, напугала тебя."
  },
  AvgCommunicate_134264_Content_10 = {
    Text = "Стоит лишь подумать об этом — и покой в моей душе многократно превосходит муки плоти."
  },
  AvgCommunicate_134264_Content_11 = {
    Text = "Я понимаю. Возможно, мои помыслы не столь возвышенны. Но хотя бы ради тебя, ради моего друга."
  },
  AvgCommunicate_134264_Content_12 = {
    Text = "Лишь бы достичь того идеального, мирного мира — я готова приложить все усилия, чего бы это ни стоило."
  },
  AvgCommunicate_134264_Content_13 = {
    Text = "Благодарю тебя, бледный посланник."
  },
  AvgCommunicate_134264_Content_14 = {
    Text = "Да настанет день, когда все страдания обретут покой, и да будем мы всегда идти плечом к плечу."
  },
  AvgCommunicate_134264_Content_15 = {
    Text = "Да снизойдёт покровительство Отца-бога на всё, что тебе дорого."
  },
  AvgCommunicate_134264_Content_2 = {
    Text = "Фух… Хорошо, что ты в порядке. Я не ожидал, что постижение закона вызовет подобный Эффект."
  },
  AvgCommunicate_134264_Content_3 = {
    Text = "Не беспокойся обо мне — в этом и состоит моё предназначение в этом мире."
  },
  AvgCommunicate_134264_Content_4 = {
    Text = "Ещё до того, как я достигла вершины и Отец-Бог открыл мне эти непостижимые тайны, я уже посвятила себя этому пути."
  },
  AvgCommunicate_134264_Content_5 = {
    Text = "Собрать страдания всех живых существ воедино и привести всё сущее к незапятнанной чистой земле, где мук больше не существует — это не бремя. Это благодать, дарованная мне Отцом-Богом."
  },
  AvgCommunicate_134264_Content_6 = {
    Text = "Мне всё же кажется, что ты несёшь слишком тяжкую ношу. Чужие страдания рассеиваются, но какой ценой…"
  },
  AvgCommunicate_134264_Content_7 = {
    Text = "Моё бледное пламя, у тебя очень мягкое сердце."
  },
  AvgCommunicate_134264_Content_8 = {
    Text = "Но будь спокоен. Телесные муки для меня — что шипы для земли: чем глубже они вонзаются, тем крепче я укореняюсь."
  },
  AvgCommunicate_134264_Content_9 = {
    Text = "Если в этом мире хоть один ещё страдает, он не будет одинок. Если хоть один ещё не избавился от моря страданий, я не достигну другого берега прежде него."
  },
  AvgCommunicate_134264_Option_11 = {
    Text = "Я понимаю"
  },
  AvgCommunicate_134264_Option_6 = {Text = "Но…"},
  AvgCommunicate_134265_Content_1 = {
    Text = "Ха-ха, вот это кайф, вот это да!"
  },
  AvgCommunicate_134265_Content_10 = {
    Text = "Спроси моих ребят — они знают меня столько лет, и когда они видели, чтобы я делала что-то подобное?!"
  },
  AvgCommunicate_134265_Content_11 = {
    Text = "Ох, теперь моя Огромная Огромная сила стала ещё мощнее, в следующий раз надо быть осторожнее, чтобы тебя не обжечь."
  },
  AvgCommunicate_134265_Content_12 = {
    Text = "Что... так это была ты? Тогда... те разы, когда мою одежду подменяли, тоже твоих рук дело?"
  },
  AvgCommunicate_134265_Content_13 = {
    Text = "Ну да, твоя одежда была испачкана вином и едой, не могла же я позволить тебе лечь в постель грязнулей."
  },
  AvgCommunicate_134265_Content_14 = {
    Text = "Спасибо тебе, Катхигу-Ра."
  },
  AvgCommunicate_134265_Content_15 = {
    Text = "Но в следующий раз, может, просто разбудишь меня?.."
  },
  AvgCommunicate_134265_Content_16 = {
    Text = "О, застеснялся? Да ладно тебе, мы же свои люди."
  },
  AvgCommunicate_134265_Content_17 = {
    Text = "Не то что какую-то одежду сменить — скажи мне хоть в Искра, хоть в воду за тебя броситься, и я даже не задумаюсь!"
  },
  AvgCommunicate_134265_Content_18 = {
    Text = "В крайнем случае, в следующий раз ты мне поможешь переодеться, и будем квиты."
  },
  AvgCommunicate_134265_Content_19 = {
    Text = "...Когда всё настолько нелогично, даже не знаешь, что на это ответить!"
  },
  AvgCommunicate_134265_Content_2 = {
    Text = "Такое небывалое чувство свободы! Сейчас я — само солнце!"
  },
  AvgCommunicate_134265_Content_3 = {
    Text = "Малыш, ты меня всё больше и больше впечатляешь."
  },
  AvgCommunicate_134265_Content_4 = {
    Text = "Только сейчас понял? У меня ещё много талантов!"
  },
  AvgCommunicate_134265_Content_5 = {
    Text = "О? Похоже, мы все привыкли считать тебя малышом, а это, пожалуй, не совсем уместно."
  },
  AvgCommunicate_134265_Content_6 = {
    Text = "Хм... Пожалуй, пора начать называть тебя «громилой»."
  },
  AvgCommunicate_134265_Content_7 = {
    Text = "Что ещё за «громила»?! Ты опять меня с серьёзным видом разыгрываешь, да?"
  },
  AvgCommunicate_134265_Content_8 = {
    Text = "Ха-ха-ха, ну а что поделать, если каждый раз, когда мы идём выпить, ты первым валишься с ног."
  },
  AvgCommunicate_134265_Content_9 = {
    Text = "И мне каждый раз приходится нести тебя в общежитие, снимать обувь, укрывать одеялом, вытирать лицо."
  },
  AvgCommunicate_134265_Option_12 = {
    Text = "Так это была ты?"
  },
  AvgCommunicate_134265_Option_7 = {Text = "?！"},
  AvgCommunicate_134267_Content_1 = {
    Text = "%player%, моя музыка стала ещё совершеннее."
  },
  AvgCommunicate_134267_Content_10 = {
    Text = "Моя музыка подобна безупречно работающему механизму. Она позволила мне стать частью лучшего оркестра, и, конечно, я этим гордился."
  },
  AvgCommunicate_134267_Content_11 = {
    Text = "Он был другим. Ансамбль был ему не по нраву — его мелодии, подобно солнцу или луне, могли лишь сиять в небе в одиночестве."
  },
  AvgCommunicate_134267_Content_12 = {
    Text = "Я всегда наблюдал за ним, стремился догнать его, но возможность поговорить с ним я утратил навсегда."
  },
  AvgCommunicate_134267_Content_13 = {
    Text = "Но… моё исполнение, достигшее ныне абсолютного совершенства, — это, пожалуй, лучший Лечение, который я смог дать после целой жизни поисков."
  },
  AvgCommunicate_134267_Content_14 = {
    Text = "Как трогательно… Так у тебя ещё и такое прошлое! Прямо легендарная история о двух музыкантах, вдохновлявших Близкий Близкий друг друга в расцвете сил…"
  },
  AvgCommunicate_134267_Content_15 = {
    Text = "Хм, это лишь самые обычные мысли вслух. На самом деле всё не так драматично."
  },
  AvgCommunicate_134267_Content_16 = {
    Text = "В любом случае, главное, что я хотел сказать — спасибо тебе, %player%."
  },
  AvgCommunicate_134267_Content_17 = {
    Text = "Позволь мне и впредь играть для тебя на флейте, провожая тебя в мирный сон каждую ночь."
  },
  AvgCommunicate_134267_Content_2 = {
    Text = "Без твоего наставления я, наверное, никогда не смогла бы сделать этот последний шаг — выверить мельчайшие погрешности, прежде недоступные человеческим силам."
  },
  AvgCommunicate_134267_Content_3 = {
    Text = "Идеальный ритм, безупречная интонация — всё звучит так восхитительно…"
  },
  AvgCommunicate_134267_Content_4 = {
    Text = "Точно! Я никогда не слышал такого упоительного исполнения!"
  },
  AvgCommunicate_134267_Content_5 = {
    Text = "Это результат гармонии музыки и расчёта, инструмента и тела, разума и мышц."
  },
  AvgCommunicate_134267_Content_6 = {
    Text = "Я наконец доказал, что в конце этого скучного и однообразного пути тоже может существовать столь совершенная музыка."
  },
  AvgCommunicate_134267_Content_7 = {
    Text = "Тоже? Что ты имеешь в виду?"
  },
  AvgCommunicate_134267_Content_8 = {
    Text = "В прошлом у меня был один Близкий Близкий друг. Его музыка была порождением абсолютной чувственности и безграничного творчества."
  },
  AvgCommunicate_134267_Content_9 = {
    Text = "Его небрежно расточаемый талант позволял ему при каждом выступлении импровизировать, создавая неповторимые произведения."
  },
  AvgCommunicate_134267_Option_14 = {
    Text = "Ууу-у-у…"
  },
  AvgCommunicate_134267_Option_4 = {
    Text = "Действительно"
  },
  AvgCommunicate_134267_Option_7 = {Text = "Тоже?"},
  AvgCommunicate_134268_Content_1 = {
    Text = "Мой самый почётный Гость, как мне отблагодарить тебя за твою щедрость?"
  },
  AvgCommunicate_134268_Content_10 = {
    Text = "Вот как, я понимаю. Ты не хочешь этих банальных празднеств — я тоже считаю, что они тебе не подходят."
  },
  AvgCommunicate_134268_Content_11 = {
    Text = "У меня есть неплохая идея. Быть может, ты захочешь отправиться со мной за пределы Города Погребённых Останков и встретить одного из уходящих?"
  },
  AvgCommunicate_134268_Content_12 = {
    Text = "Если нам выпадет такая честь, я надеюсь, что ты вместе со мной проводишь Его, поможешь Ему достичь Его конца и нового начала. Что скажешь?"
  },
  AvgCommunicate_134268_Content_13 = {
    Text = "Хоть это и немного неуместно... Я так и думал, что в конце всё равно будет трапеза — ведь таков обычай Города Погребённых Останков."
  },
  AvgCommunicate_134268_Content_14 = {
    Text = "Хм, я бы не стал называть это трапезой — всё так же, как в тех историях, что тебе уже известны."
  },
  AvgCommunicate_134268_Content_15 = {
    Text = "Это лишь самое торжественное и в то же время самое тихое прощание."
  },
  AvgCommunicate_134268_Content_16 = {
    Text = "Я с радостью приму участие, если мне позволят пропустить некоторые этапы..."
  },
  AvgCommunicate_134268_Content_17 = {
    Text = "Конечно, конечно."
  },
  AvgCommunicate_134268_Content_18 = {
    Text = "Тогда карета Города Погребённых Останков и я будем ждать тебя завтра утром у дверей."
  },
  AvgCommunicate_134268_Content_2 = {
    Text = "Благодаря твоему дару я обрёл силу, способную по-настоящему надёжно защитить Город Погребённых Останков."
  },
  AvgCommunicate_134268_Content_3 = {
    Text = "Обычные блюда не достойны твоего подношения, а мои сокровенные запасы не совсем по твоему вкусу."
  },
  AvgCommunicate_134268_Content_4 = {
    Text = "Какие приятные хлопоты, однако."
  },
  AvgCommunicate_134268_Content_5 = {
    Text = "Ты слишком любезен, Дюльсаин."
  },
  AvgCommunicate_134268_Content_6 = {
    Text = "Мы столько пережили вместе, тебе вовсе не обязательно заморачиваться с этими утомительными формальностями."
  },
  AvgCommunicate_134268_Content_7 = {
    Text = "О нет-нет, это вовсе не формальная любезность. Я серьёзно обдумываю, как устроить встречу с близким другом."
  },
  AvgCommunicate_134268_Content_8 = {
    Text = "Ты уже побывал на самом необычном балу Города Погребённых Останков. Как сделать наши отношения ещё ближе — это действительно непростая задача."
  },
  AvgCommunicate_134268_Content_9 = {
    Text = "Э-э... Если тебе интересно моё мнение, я бы просто хотел, чтобы всё было обычным, без каких-либо сюрпризов..."
  },
  AvgCommunicate_134268_Option_13 = {
    Text = "Я так и думал"
  },
  AvgCommunicate_134268_Option_9 = {Text = "Э-э..."},
  AvgCommunicate_134269_Content_1 = {
    Text = "Мой маленький росточек…"
  },
  AvgCommunicate_134269_Content_10 = {
    Text = "В моём теле зарождается Огромная Огромная сила «размножения», пробуждённая прикосновением к последнему пределу."
  },
  AvgCommunicate_134269_Content_11 = {
    Text = "Как сладостно, как упоительно… Ах, мне уже не хочется говорить с тобой через этот маленький кусочек металла."
  },
  AvgCommunicate_134269_Content_12 = {
    Text = "Тайис?"
  },
  AvgCommunicate_134269_Content_13 = {
    Text = "Приди ко мне, мой росточек, прямо сейчас, немедленно."
  },
  AvgCommunicate_134269_Content_14 = {
    Text = "Я хочу сжать твои тёплые ладони, коснуться твоей нежной кожи…"
  },
  AvgCommunicate_134269_Content_15 = {
    Text = "Я хочу Объять тебя и меня в лунном свете, как в тот вечер, когда мы дали Близкий Близкий друг другу обещание."
  },
  AvgCommunicate_134269_Content_16 = {
    Text = "Моей всё более изобильной силой — понемногу слиться с тобой воедино, и позволить твоему сладостному дыханию — понемногу согреть меня…"
  },
  AvgCommunicate_134269_Content_2 = {
    Text = "То, что ты обещал мне тогда — наш уговор под лунным светом среди песчаного моря — ты уже начал его исполнять."
  },
  AvgCommunicate_134269_Content_3 = {
    Text = "Я так счастлива."
  },
  AvgCommunicate_134269_Content_4 = {
    Text = "До мира, в котором все смогут жить спокойно, ещё далеко, но я буду стараться всегда."
  },
  AvgCommunicate_134269_Content_5 = {
    Text = "С самой нашей первой встречи я верила в тебя."
  },
  AvgCommunicate_134269_Content_6 = {
    Text = "Ты — тот, кого благословила Колесо Судьбы. У тебя есть и Огромная Огромная сила, и Решимость."
  },
  AvgCommunicate_134269_Content_7 = {
    Text = "Мой маленький росточек, ты так очарователен, когда серьёзно противостоишь всему миру."
  },
  AvgCommunicate_134269_Content_8 = {
    Text = "Я буду терпеливо и искренне ждать — ждать того дня, когда наш уговор исполнится."
  },
  AvgCommunicate_134269_Content_9 = {
    Text = "Обязательно!"
  },
  AvgCommunicate_134269_Option_12 = {
    Text = "Тайис?"
  },
  AvgCommunicate_134269_Option_4 = {
    Text = "Я буду стараться и дальше"
  },
  AvgCommunicate_134269_Option_9 = {
    Text = "Обязательно!"
  },
  AvgCommunicate_134270_Content_1 = {
    Text = "Я не стану тебя убивать."
  },
  AvgCommunicate_134270_Content_10 = {
    Text = "Когда я выпью тебя досуха, пойду и убью всех остальных."
  },
  AvgCommunicate_134270_Content_11 = {
    Text = "Тогда я… постараюсь прожить подольше?"
  },
  AvgCommunicate_134270_Content_12 = {
    Text = "Ха-ха-ха, забавный Лечение."
  },
  AvgCommunicate_134270_Content_13 = {
    Text = "Раз уж ты собираешься этим слабым телом защищать весь мир…"
  },
  AvgCommunicate_134270_Content_14 = {
    Text = "Тогда…"
  },
  AvgCommunicate_134270_Content_15 = {
    Text = "…И что же?"
  },
  AvgCommunicate_134270_Content_16 = {
    Text = "До тех пор я буду убивать только твоих врагов."
  },
  AvgCommunicate_134270_Content_17 = {
    Text = "Всё равно убивать собираешься…?!"
  },
  AvgCommunicate_134270_Content_2 = {
    Text = "...? А? Что мне сказать? Спасибо?"
  },
  AvgCommunicate_134270_Content_3 = {
    Text = "Этот мир стал невыносимо скучным после падения Рима."
  },
  AvgCommunicate_134270_Content_4 = {
    Text = "Убийства, убийства, убийства — чистая резня и кровь. Без Рима не осталось ничего."
  },
  AvgCommunicate_134270_Content_5 = {
    Text = "Твой Подарок помог мне сбросить эти оковы. А теперь я пойду оторву пару рук или перегрызу пару глоток."
  },
  AvgCommunicate_134270_Content_6 = {
    Text = "К сожалению, Ууахаши, в наше время убивать людей без специального разрешения — это преступление."
  },
  AvgCommunicate_134270_Content_7 = {
    Text = "К тому же я всё ещё твой связующий. Нельзя не только убивать меня, но и других людей тоже."
  },
  AvgCommunicate_134270_Content_8 = {Text = "Тц."},
  AvgCommunicate_134270_Content_9 = {
    Text = "Ладно, по крайней мере, на вкус ты лучше всех рабовладельцев."
  },
  AvgCommunicate_134271_Content_1 = {
    Text = "Хра~ни~тель~ ты занят? Мне нужно тебе кое-что сказать～"
  },
  AvgCommunicate_134271_Content_10 = {
    Text = "Ускользание?"
  },
  AvgCommunicate_134271_Content_11 = {
    Text = "Угу～ такое тёмное, холодное чувство, стоит ветру подуть — и оно накатывает, ощущение, будто все тебя бросили"
  },
  AvgCommunicate_134271_Content_12 = {
    Text = "Но теперь там тепло～ и светло～"
  },
  AvgCommunicate_134271_Content_13 = {
    Text = "И всё это благодаря %player%."
  },
  AvgCommunicate_134271_Content_14 = {
    Text = "Значит, это действительно искренняя благодарность?"
  },
  AvgCommunicate_134271_Content_15 = {
    Text = "Хм-хм～ конечно, я тоже иногда бываю серьёзной, между прочим!"
  },
  AvgCommunicate_134271_Content_16 = {
    Text = "Но в обмен на это — ты должен почаще проводить со мной время, ладно?"
  },
  AvgCommunicate_134271_Content_17 = {
    Text = "А иначе я хоро～шень～ко накажу тебя своими новыми умениями～"
  },
  AvgCommunicate_134271_Content_18 = {
    Text = "…Это что, твой способ благодарить?!"
  },
  AvgCommunicate_134271_Content_19 = {
    Text = "Ой, это же фирменный способ Пандии выражать любовь～ Чмок～ Не забудь быть благодарным!"
  },
  AvgCommunicate_134271_Content_2 = {
    Text = "Что ты опять задумала?"
  },
  AvgCommunicate_134271_Content_3 = {
    Text = "Ну что ты такое говоришь! Я пришла тебя искренне поблагодарить!"
  },
  AvgCommunicate_134271_Content_4 = {
    Text = "Те замечательные штучки, что ты мне дал раньше… от них моё тело стало таким горячим-горячим～"
  },
  AvgCommunicate_134271_Content_5 = {
    Text = "Будто что-то обжигающее течёт под кожей, сладкое и жгучее одновременно～"
  },
  AvgCommunicate_134271_Content_6 = {
    Text = "Хоть я и знаю, что побочных эффектов быть не должно, но ты уверена, что это не побочный Эффект?…"
  },
  AvgCommunicate_134271_Content_7 = {
    Text = "Конечно нет! Это ощущение просто восхитительное! В сто раз острее любой порки!"
