  AvgCommunicate_134271_Option_6 = {Text = "Хоть"},
  AvgCommunicate_134272_Content_1 = {
    Text = "Носитель～ Как же Карен отблагодарить Вас? Напитки, уборка, готовка — пожалуйста, распоряжайтесь Карен как угодно!"
  },
  AvgCommunicate_134272_Content_10 = {
    Text = "Стоит Карен только захотеть, и кожа Карен засверкает ярче самых дорогих драгоценных камней, засияет переливами прекраснее самого совершенного жемчуга."
  },
  AvgCommunicate_134272_Content_11 = {
    Text = "Если сейчас пойти на бал, Карен точно станет центром всеобщего внимания и больше не будет незаметной маленькой персоной, которую никто не замечает."
