  AvgCommunicate_134272_Content_2 = {
    Text = "Для начала давай исключим готовку!"
  },
  AvgCommunicate_134272_Content_3 = {
    Text = "Ой, мои навыки ведения хозяйства поставили под сомнение. Карен, наверное, должна расстроиться, но, но…"
  },
  AvgCommunicate_134272_Content_4 = {
    Text = "Столько-столько драгоценностей и украшений! Карен вся сияет, словно самый ослепительный драгоценный камень. Карен Правда очень трудно грустить!"
