  AvgCommunicate_134272_Content_8 = {
    Text = "А, точно, это та очень-очень ценная и очень-очень замечательная штука. И после этого Карен почувствовала, что обрела невероятно мощную способность."
  },
  AvgCommunicate_134272_Content_9 = {
    Text = "Эффективность ведения хозяйства значительно возросла, но что ещё важнее — тело Карен сияет и переливается."
  },
  AvgCommunicate_134272_Option_7 = {
    Text = "Это не заколка"
  },
  AvgCommunicate_134273_Content_1 = {
    Text = "%player%, моя связь с тобой стала ещё глубже."
  },
  AvgCommunicate_134273_Content_10 = {
    Text = "Результаты вычислений интегралов, ответы на экзаменационные вопросы по общим предметам и тому подобное — это тоже можно напрямую получить из бесконечных знаний?"
  },
  AvgCommunicate_134273_Content_12 = {
    Text = "Тебе действительно больше не придётся усердно запоминать множество вещей."
  },
  AvgCommunicate_134273_Content_13 = {
    Text = "Но, полагаю, смысл учёбы — в самом процессе обретения знаний и в закалке силы мышления."
  },
  AvgCommunicate_134273_Content_14 = {
    Text = "Сначала тебе нужно осознать, чего ты не знаешь и что тебе следует знать, — лишь тогда ты сможешь найти нужный Лечение в бескрайней сокровищнице."
  },
  AvgCommunicate_134273_Content_15 = {
    Text = "Ладно, я поняла. Хоть Лечение и отличается от того, что сказала Рамона, итог всё равно тот же."
  },
  AvgCommunicate_134273_Content_16 = {
    Text = "Буду учиться, буду учиться, ну разве нельзя?!"
  },
  AvgCommunicate_134273_Content_17 = {
    Text = "Рад видеть твою тягу к знаниям, не сдавайся. Я, как и прежде, буду рядом с тобой."
  },
  AvgCommunicate_134273_Content_2 = {
    Text = "Поздравляю тебя и благодарю за твои усилия. Теперь я могу собрать больше осколков сознания и скрывать более цельное существование в щелях между мирами."
  },
  AvgCommunicate_134273_Content_3 = {
    Text = "Ты можешь явиться в мир!?"
  },
  AvgCommunicate_134273_Content_4 = {
    Text = "К сожалению, я пока не могу по-настоящему проявить своё существование и покинуть Чёрную Бездну."
  },
  AvgCommunicate_134273_Content_5 = {
    Text = "Однако мой дух, мои сны, мой взор, устремлённый на бесчисленные миры, — всё это уже может существовать в большей полноте и передаваться тебе."
  },
  AvgCommunicate_134273_Content_6 = {
    Text = "По крайней мере, ты уже обладаешь ключом к бесконечному знанию."
  },
  AvgCommunicate_134273_Content_7 = {
    Text = "То есть, на любой мой вопрос можно получить Лечение?"
  },
  AvgCommunicate_134273_Content_8 = {
    Text = "Если это существует или может быть доказано."
  },
  AvgCommunicate_134273_Content_9 = {
    Text = "Хе-хе, например, я говорю — например."
  },
  AvgCommunicate_134273_Option_15 = {
    Text = "Я понимаю"
  },
  AvgCommunicate_134273_Option_7 = {
    Text = "Бесконечные знания?"
  },
  AvgCommunicate_134274_Content_1 = {
    Text = "Семя... стало более целостным."
  },
  AvgCommunicate_134274_Content_10 = {
    Text = "Такие шумные мероприятия для меня всё ещё слишком волнительны."
  },
  AvgCommunicate_134274_Content_11 = {
    Text = "Всё в порядке, я и Тинктура будем рядом с тобой."
  },
  AvgCommunicate_134274_Content_12 = {
    Text = "Конечно, если тебе комфортнее быть одной, я тоже полностью поддержу твоё решение!"
  },
  AvgCommunicate_134274_Content_13 = {
    Text = "Страж... спасибо. Если таково ваше с Тинктурой пожелание."
  },
  AvgCommunicate_134274_Content_14 = {
    Text = "Хм… Начну привыкать с дальнего угла в последнем ряду класса."
  },
  AvgCommunicate_134274_Content_2 = {
    Text = "Я чувствую, как Огромная Огромная сила, способная поддержать моё Почкование, постепенно заполняет пустоту в душе."
  },
  AvgCommunicate_134274_Content_3 = {
    Text = "Значит... ты теперь не будешь поглощать жизненную силу других?"
