  AvgCommunicate_134274_Content_6 = {
    Text = "Если я буду усердно тренироваться, следователям, которые со мной контактируют, больше не придётся надевать громоздкие защитные костюмы."
  },
  AvgCommunicate_134274_Content_7 = {
    Text = "Теперь у меня появилась возможность безопасно находиться рядом со всеми."
  },
  AvgCommunicate_134274_Content_8 = {
    Text = "Это замечательно! Теперь ты тоже сможешь участвовать в различных школьных мероприятиях, вечерах и вечеринках среди Пробуждённых."
  },
  AvgCommunicate_134274_Content_9 = {
    Text = "Ве-вечеринки... Мне кажется, научиться общаться с людьми гораздо сложнее, чем научиться контролировать инстинкты."
  },
  AvgCommunicate_134274_Option_11 = {
    Text = "Всё в порядке"
  },
  AvgCommunicate_134274_Option_3 = {
    Text = "Поэтому..."
