  AvgCommunicate_134274_Option_8 = {
    Text = "Это замечательно!"
  },
  AvgCommunicate_134275_Content_1 = {
    Text = "Подносить все драгоценности принцессе — это твоя великая честь."
  },
  AvgCommunicate_134275_Content_10 = {
    Text = "…Спасибо? Ты что, не пытаешься задобрить меня подарками, чтобы услышать пару слов похвалы или заставить меня исполнить какое-то твоё желание?"
  },
  AvgCommunicate_134275_Content_11 = {
    Text = "«Мёрфи», я дарю тебе подарки и хорошо к тебе отношусь просто потому, что ты — это ты."
  },
  AvgCommunicate_134275_Content_12 = {
    Text = "Неважно, принцесса ты, Божественная Матушка или кто-то ещё. Ты — мой Близкий Близкий друг, и больше мне ничего не нужно."
  },
  AvgCommunicate_134275_Content_14 = {
    Text = "Хмф! Это… это всё та же болтовня сладкоречивого льстеца! Думаешь, от таких слов я расплачусь от умиления?"
  },
  AvgCommunicate_134275_Content_15 = {
    Text = "Даже не мечтай. Какой ещё Близкий Близкий друг? Тебе достаточно быть верным последователем, и всё."
  },
  AvgCommunicate_134275_Content_16 = {
    Text = "Какие обидные слова, я сегодня ночью Правда буду плакать всю ночь напролёт, знаешь?"
