  AvgCommunicate_134275_Content_19 = {
    Text = "……Спасибо."
  },
  AvgCommunicate_134275_Content_2 = {
    Text = "Неплохо справился."
  },
  AvgCommunicate_134275_Content_20 = {
    Text = "Словом, отныне у сей принцессы будет достаточно сил, чтобы оберегать тебя, так что преисполнись благодарности и продолжай восхищаться мною!"
