  AvgCommunicate_134275_Content_4 = {
    Text = "А что такого? Эта Огромная Огромная сила и так по праву принадлежит мне, разве нет?"
  },
  AvgCommunicate_134275_Content_5 = {
    Text = "О, поняла. Ты хочешь награду, благословение, более высокое положение или, может, более почётный титул?"
  },
  AvgCommunicate_134275_Content_7 = {
    Text = "Что значит «……»? Как же бесишь, мне неинтересно играть с тобой в молчанку."
  },
  AvgCommunicate_134275_Content_8 = {
    Text = "Даю тебе последний шанс. Хочешь что-то — говори быстро, хватит ходить вокруг да около."
  },
  AvgCommunicate_134275_Content_9 = {
    Text = "А может быть такое, что я просто хочу услышать от тебя хотя бы «спасибо»?"
  },
  AvgCommunicate_134275_Option_16 = {
    Text = "Как обидно"
  },
  AvgCommunicate_134275_Option_3 = {Text = "И всё?"},
  AvgCommunicate_134275_Option_9 = {
    Text = "А может быть такое, что"
  },
  AvgCommunicate_134276_Content_1 = {
    Text = "Спасибо тебе, Страж Тайн, спасибо! Я... я даже не знаю, как выразить..."
  },
  AvgCommunicate_134276_Content_10 = {
    Text = "Примерно это ты имеешь в виду?"
  },
  AvgCommunicate_134276_Content_11 = {
    Text = "Я слышал, что цвета на картине несут в себе разные эмоции и атмосферу. Ты можешь следовать собственному творческому замыслу и создавать новые цвета."
