  AvgCommunicate_134276_Content_14 = {
    Text = "Прошу прощения, Страж Тайн!"
  },
  AvgCommunicate_134276_Content_15 = {
    Text = "У меня предчувствие, что моя следующая картина обретёт ещё более волшебные мазки."
  },
  AvgCommunicate_134276_Content_16 = {
    Text = "Может быть, мне и Правда удастся создать картину, соединённую с неизведанным. И тогда ты увидишь её первым!"
