  AvgCommunicate_134276_Content_4 = {
    Text = "Радужный кристалл? Мифрил? Перламутр? Порошок кристальных жуков? Крылья светящихся бабочек?"
  },
  AvgCommunicate_134276_Content_5 = {
    Text = "Нет, нет, нет... Такое невозможно Воссоздать этими банальными, заурядными вещами. Надо подумать ещё, ещё подумать..."
  },
  AvgCommunicate_134276_Content_6 = {
    Text = "Пикман? Похоже, ты уже полностью погрузился в своё искусство..."
  },
  AvgCommunicate_134276_Content_7 = {
    Text = "Тсс, как ты думаешь, каков истинный цвет вселенной? Такой особенный, как ты, наверняка сможет подарить мне необычное вдохновение!"
  },
  AvgCommunicate_134276_Content_8 = {
    Text = "Я думаю, что мир в глазах каждого человека, возможно, выглядит по-разному."
  },
  AvgCommunicate_134276_Content_9 = {
    Text = "О! Ты хочешь сказать… следовать своему сердцу… следовать своим чувствам и изображать вселенную в разных красках…"
