  AvgCommunicate_134276_Option_10 = {
    Text = "Возможно"
  },
  AvgCommunicate_134276_Option_8 = {
    Text = "Я думаю"
  },
  AvgCommunicate_134277_Content_1 = {
    Text = "Хра～ни～тель Тайн—"
  },
  AvgCommunicate_134277_Content_10 = {
    Text = "Я не буду тебя жалеть, не буду свысока строить предположения о логике твоих поступков. Я лишь хочу, чтобы тебе было весело в этом мире."
  },
  AvgCommunicate_134277_Content_12 = {
    Text = "Ого, и кто из нас двоих безумнее? Вот так запросто отдать силу такого уровня такой психопатке, как я?"
  },
  AvgCommunicate_134277_Content_13 = {
    Text = "Может, моё появление в этом мире и Правда было предначертано судьбой?"
  },
  AvgCommunicate_134277_Content_15 = {
    Text = "В общем, благодаря тебе я прикоснулась к своему «пределу» в вашем мире."
  },
  AvgCommunicate_134277_Content_16 = {
    Text = "А теперь давай, скорее выдавай мне задание! Мне уже не терпится снести пару-тройку голов и показать вам, на что я способна～"
  },
  AvgCommunicate_134277_Content_2 = {
    Text = "Девушка, оказавшаяся в чужом мире, получает дорогой Подарок, который сделает её сильнее… Знаешь, на что это очень похоже?"
  },
  AvgCommunicate_134277_Content_3 = {
    Text = "Прежде чем ты скажешь что-нибудь из ряда вон выходящее, хочу заявить: ты — часть Мисагарда. Мы помогаем Близкий Близкий друг другу, и именно поэтому я отдал тебе те материалы."
  },
  AvgCommunicate_134277_Content_4 = {
    Text = "Правда? Это не какое-нибудь скучное завуалированное социальное поведение?"
  },
  AvgCommunicate_134277_Content_5 = {
    Text = "«Она не может вернуться домой, бедняжка, давайте будем к ней добрее.»"
  },
  AvgCommunicate_134277_Content_6 = {
    Text = "«Ей так тяжело справляться одной, давайте ей поможем.» — неужели это не одна из тех банальных причин, которые так часто встречаются в обычном обществе?"
  },
  AvgCommunicate_134277_Content_7 = {
    Text = "Во-первых, с какой стороны ни посмотри, Мося, ты и слово «банальный» не имеете ничего общего!"
  },
  AvgCommunicate_134277_Content_8 = {
    Text = "Хм☆хм, такая оценка мне по душе."
  },
  AvgCommunicate_134277_Content_9 = {
    Text = "Во-вторых, каким бы ни было твоё представление о себе и каким бы ни был твой внешний облик, для меня, как ты и сказала, «Мося» — это «Мося»."
  },
  AvgCommunicate_134277_Option_7 = {
    Text = "Во-первых"
  },
  AvgCommunicate_134278_Content_1 = {
    Text = "Благодарю тебя, мой дорогой. Ты принёс мне столько счастья и позволил мне навсегда сохранить мои амбиции."
  },
  AvgCommunicate_134278_Content_10 = {
    Text = "Какую бы благодарность ты ни пожелал — я смогу это устроить."
  },
  AvgCommunicate_134278_Content_11 = {
    Text = "Даже если у меня этого пока нет — будь то звёзды или луна, — я готова найти способ достать их для тебя."
  },
  AvgCommunicate_134278_Content_12 = {
    Text = "Выбирать на свой вкус? Всё что угодно?"
  },
  AvgCommunicate_134278_Content_13 = {
    Text = "Слово, данное однажды, дороже золота — это незаменимый пропуск в мире славы и власти."
  },
  AvgCommunicate_134278_Content_14 = {
    Text = "В таком случае я хочу, чтобы мадам дала мне одно обещание. Что касается его содержания, мне нужно ещё подумать."
  },
  AvgCommunicate_134278_Content_16 = {
    Text = "Ха-ха-ха-ха, какой хитрый выбор! Ты нравишься мне всё больше и больше."
  },
  AvgCommunicate_134278_Content_17 = {
    Text = "Конечно, мой дорогой, у тебя предостаточно времени, чтобы всё обдумать."
  },
  AvgCommunicate_134278_Content_18 = {
    Text = "Если у тебя найдётся время, приходи сегодня вечером в мою резиденцию. Возможно, когда мы останемся наедине... тебе будет проще придумать какую-нибудь восхитительную «хорошую идею»."
  },
  AvgCommunicate_134278_Content_2 = {
    Text = "Служить вам, мадам, — для меня великая честь."
  },
  AvgCommunicate_134278_Content_3 = {
    Text = "Хе-хе, послушный, умный, храбрый, верный, и вдобавок — в самую меру... красивый."
  },
  AvgCommunicate_134278_Content_4 = {
    Text = "Кто посмеет сказать, что ты не идеальный..."
  },
  AvgCommunicate_134278_Content_5 = {
    Text = "...Идеальный — что?"
  },
  AvgCommunicate_134278_Content_6 = {
    Text = "Ты, кажется, немного нервничаешь?"
  },
  AvgCommunicate_134278_Content_7 = {
    Text = "Мадам всегда умеет лишить дара речи."
  },
  AvgCommunicate_134278_Content_8 = {
    Text = "Некоторые вещи не нужно выражать словами. Все твои чувства, что ты проявлял всё это время, — я их приняла."
  },
  AvgCommunicate_134278_Content_9 = {
    Text = "Земли, имущество, бесчисленные редкие сокровища и произведения искусства, встречи с множеством знаменитостей и звёзд... С моей нынешней силой всё это легко достижимо."
  },
  AvgCommunicate_134278_Option_12 = {
    Text = "Правда, всё что угодно?"
  },
  AvgCommunicate_134278_Option_14 = {
    Text = "Я хочу получить обещание от мадам."
  },
  AvgCommunicate_134278_Option_2 = {
    Text = "Для меня это честь"
  },
  AvgCommunicate_134278_Option_5 = {
    Text = "Идеальный?"
  },
  AvgCommunicate_134279_Content_1 = {
    Text = "Страж Тайн, вы ещё не спите?"
  },
  AvgCommunicate_134279_Content_10 = {
    Text = "Но всё, что вы вложили в меня… собралось внутри меня в новое озеро. Ещё более бескрайнее, чем то море."
  },
  AvgCommunicate_134279_Content_11 = {
    Text = "Оно сказало мне: больше не нужно бояться."
  },
  AvgCommunicate_134279_Content_12 = {
    Text = "Я понимаю, что эту боль, возможно, нельзя растворить, но сколько бы раз ни понадобилось — я готов вытянуть тебя на берег."
  },
  AvgCommunicate_134279_Content_13 = {
    Text = "…Если бы папа и мама могли услышать ваши слова, они наверняка были бы спокойны."
  },
  AvgCommunicate_134279_Content_14 = {
    Text = "Я думаю… может быть, они где-то там, в море, и смотрят на меня сейчас."
  },
  AvgCommunicate_134279_Content_15 = {
    Text = "Отныне я обращу обретённую силу в прилив, что будет хранить вас."
  },
  AvgCommunicate_134279_Content_16 = {
    Text = "Быть может… вы согласитесь исполнить ещё одну дерзкую просьбу?"
  },
  AvgCommunicate_134279_Content_17 = {
    Text = "Какую? Если это в моих силах, я с радостью соглашусь."
  },
  AvgCommunicate_134279_Content_18 = {
    Text = "Когда погода прояснится, не прогуляетесь ли вы со мной к морю?"
  },
  AvgCommunicate_134279_Content_19 = {
    Text = "Мне так много хочется вам рассказать, хватит и одного дня."
  },
  AvgCommunicate_134279_Content_2 = {
    Text = "Если я помешала вашему отдыху, прошу прощения…"
  },
  AvgCommunicate_134279_Content_20 = {
    Text = "Конечно, без проблем. Обязательно."
  },
  AvgCommunicate_134279_Content_3 = {
    Text = "Нет, я ещё не сплю. Что случилось?"
  },
  AvgCommunicate_134279_Content_4 = {
    Text = "После того как я получила ваш Подарок, я погрузилась в Глубокий сон и увидела сон. Мне приснилось то самое море и Закат за окнами санатория."
  },
  AvgCommunicate_134279_Content_5 = {
    Text = "Но на этот раз… я не вошла в воду."
  },
  AvgCommunicate_134279_Content_6 = {
    Text = "Я стояла на берегу и смотрела на море. Оно по-прежнему дарило мне покой, но я не хотела идти вперёд."
  },
  AvgCommunicate_134279_Content_7 = {
    Text = "Если такое предположение не покажется дерзким… Может быть, на этот раз у тебя появилась причина остаться?"
  },
  AvgCommunicate_134279_Content_8 = {Text = "Угу."},
  AvgCommunicate_134279_Content_9 = {
    Text = "Когда-то боль раздавила меня, и ничто, кроме моря, что смывает и вбирает в себя всё, не могло унести ту тяжесть, что застряла в моём горле."
  },
  AvgCommunicate_134279_Option_12 = {
    Text = "Нимфия…"
  },
  AvgCommunicate_134279_Option_17 = {Text = "Что?"},
  AvgCommunicate_134279_Option_7 = {
    Text = "Потому что…"
  },
  AvgCommunicate_134280_Content_1 = {
    Text = "%player%, вчера ночью мне снова приснился тот сон."
  },
  AvgCommunicate_134280_Content_10 = {
    Text = "Возможно, это Эффект Конечного Закона."
  },
  AvgCommunicate_134280_Content_11 = {
    Text = "Да, поэтому я хочу сказать — от имени всех «24» благодарю тебя, %player%."
  },
  AvgCommunicate_134280_Content_12 = {
    Text = "Спасибо, что позволил нам услышать Близкий Близкий друг друга, увидеть Близкий Близкий друг друга, понять Близкий Близкий друг друга, принять Близкий Близкий друг друга."
  },
  AvgCommunicate_134280_Content_13 = {
    Text = "Это не моя заслуга."
  },
  AvgCommunicate_134280_Content_14 = {
    Text = "Нет, именно ваши наставления и утешение успокоили все мятущиеся души."
  },
  AvgCommunicate_134280_Content_15 = {
    Text = "Именно ваше присутствие заставило все реки слиться воедино."
  },
  AvgCommunicate_134280_Content_16 = {
    Text = "«Мы» никогда не забудем вашу доброту."
  },
  AvgCommunicate_134280_Content_2 = {
    Text = "Мне казалось, что я вернулась к подножию заснеженных гор крайнего севера, в тёмную пещеру."
  },
  AvgCommunicate_134280_Content_3 = {
    Text = "Бесчисленные сгустки слизи отражали бесчисленные тени «24»…"
  },
  AvgCommunicate_134280_Content_4 = {
    Text = "Все они… это ты, все они — часть тебя."
  },
  AvgCommunicate_134280_Content_5 = {
    Text = "Я знаю."
  },
  AvgCommunicate_134280_Content_6 = {
    Text = "Посреди хаоса мне послышалось, будто кто-то что-то мне сказал."
  },
  AvgCommunicate_134280_Content_7 = {
    Text = "Голос был таким приглушённым, я не могла разобрать слов…"
  },
  AvgCommunicate_134280_Content_8 = {
    Text = "Но после того как тот человек ушёл, я почувствовала, что весь окружающий шум утих."
  },
  AvgCommunicate_134280_Content_9 = {
    Text = "Хаотичный шёпот в ушах стал гармоничным и естественным, словно стройная мелодия…"
  },
  AvgCommunicate_134280_Option_4 = {
    Text = "Все они — это ты."
  },
  AvgCommunicate_134281_Content_1 = {
    Text = "Страж, ты веришь в судьбу?"
  },
  AvgCommunicate_134281_Content_10 = {
    Text = "…Как обычный человек, я уже не в силах представить, насколько это кайфово. Позволь мне, скрипя зубами, спросить — каково это вообще?"
  },
  AvgCommunicate_134281_Content_11 = {
    Text = "Как бы описать… Например, сейчас я почувствовала лёгкий голод…"
  },
  AvgCommunicate_134281_Content_12 = {
    Text = "? И что дальше?"
  },
  AvgCommunicate_134281_Content_13 = {
    Text = "Ох, прости за ожидание — только что кто-то постучал в Ворота. Это мисс Мейсон поделилась свежеиспечённым фунтовым кексом."
  },
  AvgCommunicate_134281_Content_14 = {Text = "Что???"},
  AvgCommunicate_134281_Content_15 = {
    Text = "Вот так. А потом… мне захотелось пить."
  },
  AvgCommunicate_134281_Content_16 = {
    Text = "О? Только что дворецкий мистера Дюльсена принёс Приглашение — меня зовут продегустировать его коллекцию вин, хранящуюся в ближайшем ресторане."
  },
  AvgCommunicate_134281_Content_17 = {
    Text = "…Хватит. В следующий раз ты не могла бы от всей души захотеть помочь мне с домашним заданием?"
  },
  AvgCommunicate_134281_Content_18 = {
    Text = "Ха-ха-ха, слушаюсь, %player%! Ты ведь мой главный спонсор, покровитель, верный товарищ и незаменимый Ватсон."
  },
  AvgCommunicate_134281_Content_19 = {
    Text = "Детектив удачи всегда рада служить тебе."
  },
  AvgCommunicate_134281_Content_2 = {
    Text = "Я верю в судьбу. И более того — я верю, что мне досталась самая удачливая Колесо Судьбы."
  },
  AvgCommunicate_134281_Content_3 = {
    Text = "Все неожиданные радости, свалившиеся с неба богатства, невероятные удачи, что вдруг случаются со мной, — я принимаю их совершенно невозмутимо."
  },
  AvgCommunicate_134281_Content_4 = {
    Text = "Когда привыкаешь к благосклонности судьбы, все приятные события становятся чем-то обыденным."
  },
  AvgCommunicate_134281_Content_5 = {
    Text = "От твоих слов и завидно, и досадно одновременно."
  },
  AvgCommunicate_134281_Content_6 = {
    Text = "Не торопись, я ещё не закончила. Встретить тебя — это самая большая удача из всех моих удач."
  },
  AvgCommunicate_134281_Content_7 = {
    Text = "То, что ты мне даёшь, всегда приносит новые сюрпризы."
  },
  AvgCommunicate_134281_Content_8 = {
    Text = "Вот как сейчас — Огромная Огромная сила, хлынувшая после постижения высшего закона, позволяет мне отчётливо предчувствовать каждый Приход удачи."
  },
  AvgCommunicate_134281_Content_9 = {
    Text = "Удачные события сыплются, словно дождь — сначала мелкая морось, а потом — хлынул Реальность ливень."
  },
  AvgCommunicate_134281_Option_10 = {
    Text = "И каково это?"
  },
  AvgCommunicate_134281_Option_14 = {Text = "???"},
  AvgCommunicate_134281_Option_5 = {
    Text = "Вызывает и зависть, и досаду"
  },
  AvgCommunicate_137645_Content_1 = {
    Text = "Страж."
  },
  AvgCommunicate_137645_Content_10 = {
    Text = "Хотя у тебя так много ног — разве не нечестно участвовать в беговых соревнованиях?.."
  },
  AvgCommunicate_137645_Content_11 = {
    Text = "У Кастора есть крылья, а Нодитла взяла с собой своё транспортное средство."
  },
  AvgCommunicate_137645_Content_12 = {
    Text = "Обычно я тку в театре и совсем не привыкла к физическим нагрузкам. Впрочем, я уже записала на соревнования свою служанку."
  },
  AvgCommunicate_137645_Content_13 = {
    Text = "Сложно представить, почему тебя вообще интересуют подобные вещи."
  },
  AvgCommunicate_137645_Content_14 = {
    Text = "Наблюдать за тем, как люди ради одной цели проявляют неиссякаемую жизненную силу и несгибаемую волю — это поистине приятное зрелище."
  },
  AvgCommunicate_137645_Content_15 = {
    Text = "И ещё… мне немного любопытно, какой же магией обладает тот торт в качестве приза, раз даже Тави им увлеклась."
  },
  AvgCommunicate_137645_Content_16 = {
    Text = "Лишь бы это не был какой-нибудь выбор, способный разрушить целый мир… тогда всё в порядке…"
  },
  AvgCommunicate_137645_Content_17 = {
    Text = "Эм, ты ведь не собираешься манипулировать исходом соревнования нитями судьбы? Правда?"
  },
  AvgCommunicate_137645_Content_18 = {
    Text = "…Арахна?"
  },
  AvgCommunicate_137645_Content_2 = {
    Text = "Что случилось?"
  },
  AvgCommunicate_137645_Content_20 = {
    Text = "Увидимся на трибунах, Страж."
  },
  AvgCommunicate_137645_Content_3 = {
    Text = "Как ты считаешь… какая Колесо Судьбы может считаться справедливой и правильной?"
  },
  AvgCommunicate_137645_Content_4 = {
    Text = "Справедливой и правильной?.. Наверное, та, что защищает интересы большинства людей."
  },
  AvgCommunicate_137645_Content_5 = {
    Text = "А если… неизбежно приходится жертвовать интересами меньшинства? Ты признаёшь такое направление судьбы, не так ли?"
  },
  AvgCommunicate_137645_Content_6 = {
    Text = "Ты… почему вдруг спрашиваешь об этом? Не поймите меня неправильно!"
  },
  AvgCommunicate_137645_Content_7 = {
    Text = "Если ты снова собираешься уничтожить какой-нибудь мир, пожалуйста, подумай хорошенько, Арахна!"
  },
  AvgCommunicate_137645_Content_8 = {
    Text = "Не беспокойся, Страж, это всего лишь беговые соревнования."
  },
  AvgCommunicate_137645_Content_9 = {
    Text = "Уф… напугала меня…"
  },
  AvgCommunicate_137645_Option_2 = {
    Text = "Что случилось?"
  },
  AvgCommunicate_137646_Content_1 = {
    Text = "Страж, узнав, что тебе предстоит дальнее путешествие для участия в расследовании, я специально написала для тебя одно произведение."
  },
  AvgCommunicate_137646_Content_10 = {
    Text = "У тебя просто невероятный вкус в названиях, Арахна…"
  },
  AvgCommunicate_137646_Content_11 = {
    Text = "Каждая нить пряжи имеет своего предназначенного ей хозяина. И каждая история найдёт своего читателя."
  },
  AvgCommunicate_137646_Content_12 = {
    Text = "Броское название позволяет этим замечательным историям достичь тех, кто должен их прочесть."
  },
  AvgCommunicate_137646_Content_13 = {
    Text = "Например, это произведение с наибольшими продажами…"
  },
  AvgCommunicate_137646_Content_14 = {
    Text = "«Кулинарный путеводитель по глубоководным существам»? Наибольшие продажи?"
  },
  AvgCommunicate_137646_Content_15 = {
    Text = "Надеюсь, Дульсейн не скупила по экземпляру для каждого жителя Города Погребённых Костей…"
  },
  AvgCommunicate_137646_Content_16 = {
    Text = "Тулу знает об этом?"
  },
  AvgCommunicate_137646_Content_18 = {
    Text = "Именно эта острая проницательность в отношении человеческих сердец и судеб заставляет меня искренне восхищаться тобой."
  },
  AvgCommunicate_137646_Content_19 = {
    Text = "«Все любят хранителя тайн»."
  },
  AvgCommunicate_137646_Content_2 = {
    Text = "Сначала хотела поставить для тебя пьесу, но, учитывая удобство переноски, всё же написала роман."
  },
  AvgCommunicate_137646_Content_20 = {
    Text = "Возьми это произведение с собой в путь."
  },
  AvgCommunicate_137646_Content_3 = {Text = "Это…"},
  AvgCommunicate_137646_Content_4 = {
    Text = "«Великий Страж»? «Робинзон Страж»? «Мир Хранителя тайн»?"
  },
  AvgCommunicate_137646_Content_5 = {
    Text = "Что ты вообще обычно пишешь?! Неужели кто-то это читает???"
  },
  AvgCommunicate_137646_Content_6 = {
    Text = "Не стоит недооценивать свою популярность в Мисаге — всё это крайне востребованные произведения."
  },
  AvgCommunicate_137646_Content_7 = {
    Text = "Столь драматичная Колесо Судьбы непременно должна быть явлена этому миру."
  },
  AvgCommunicate_137646_Content_8 = {
    Text = "На самом деле, не только ты. Я ткала истории и о судьбах других людей."
  },
  AvgCommunicate_137646_Content_9 = {
    Text = "«Пять лет на поле боя, три года в симуляции», «Послеродовой уход за мышами», «Большой смотр искусства восковых капель»…"
  },
  AvgCommunicate_137646_Option_3 = {Text = "Это…"},
  AvgCommunicate_137647_Content_1 = {
    Text = "Соединять людей из разных времён и пространств невидимыми нитями…"
  },
  AvgCommunicate_137647_Content_10 = {
    Text = "Я с нетерпением жду, Страж."
  },
  AvgCommunicate_137647_Content_2 = {
    Text = "Человеческая цивилизация всегда умеет меня удивить."
  },
  AvgCommunicate_137647_Content_3 = {
    Text = "Удивить?"
  },
  AvgCommunicate_137647_Content_4 = {
    Text = "Но разве не ты сама выбрала эти судьбы?"
  },
  AvgCommunicate_137647_Content_5 = {
    Text = "Я выбираю лишь направление, но всю цивилизацию и историю вы создаёте сами."
  },
  AvgCommunicate_137647_Content_6 = {
    Text = "Нити судьбы, что тянутся естественным образом, в конце концов породят новые творения и неведомые истоки."
  },
  AvgCommunicate_137647_Content_7 = {
    Text = "Именно потому, что я свидетельствую всему этому, именно ради радости от этого плетения, я и продолжаю нести свою ответственность."
  },
  AvgCommunicate_137647_Content_8 = {
    Text = "Понятно.."
  },
  AvgCommunicate_137647_Content_9 = {
    Text = "Если появится что-то новое, прошу, позволь мне тоже насладиться этим."
  },
  AvgCommunicate_137647_Option_3 = {
    Text = "Удивить?"
  },
  AvgCommunicate_140194_Content_1 = {
    Text = "Какое удивительное ощущение, никто совершенно не испугался……"
  },
  AvgCommunicate_140194_Content_10 = {
    Text = "Все относятся к Сае очень ласково, так что всё в порядке!"
  },
  AvgCommunicate_140194_Content_11 = {
    Text = "……Наверное. Пока что."
  },
  AvgCommunicate_140194_Content_12 = {
    Text = "Пока что…… обещай!"
  },
  AvgCommunicate_140194_Content_13 = {
    Text = "Пока что～"
  },
  AvgCommunicate_140194_Content_2 = {
    Text = "Доктор Дуэр специально разработала особый феромон. Теперь Сая в глазах любого человека выглядит как обычная человеческая девушка."
  },
  AvgCommunicate_140194_Content_4 = {
    Text = "Эм, хоть это и удобно, но если честно……"
  },
  AvgCommunicate_140194_Content_5 = {
    Text = "Никто не пугается, увидев Саю — немного обидно, да?"
  },
  AvgCommunicate_140194_Content_6 = {Text = "…?"},
  AvgCommunicate_140194_Content_7 = {
    Text = "Как бы сказать, хм…… просто во время «охоты» это немного затрудняет дело……"
  },
  AvgCommunicate_140194_Content_8 = {
    Text = "Благодаря всем, о еде можно не беспокоиться…… но иногда всё же хочется…… хм……"
  },
  AvgCommunicate_140194_Content_9 = {
    Text = "Хоть я давно привыкла к подобным высказываниям от пробуждённых, но это всё равно опасно, очень опасные слова, Сая!"
  },
  AvgCommunicate_140195_Content_1 = {
    Text = "«Заявка на закупку»"
  },
  AvgCommunicate_140195_Content_10 = {
    Text = "Я буду делать вид, что ничего не знаю."
  },
  AvgCommunicate_140195_Content_2 = {
    Text = "Часть 4 больших бытовых холодильника... Хотя бюджет академии не особо ограничен, но для чего они нужны?"
  },
  AvgCommunicate_140195_Content_3 = {
    Text = "Сая, насколько я помню, в первый же день твоего переезда в Мисагр ты уже подала заявку на холодильник для общежития."
  },
  AvgCommunicate_140195_Content_4 = {
    Text = "Ну, если нужно объяснить... на всякий случай, наверное..."
  },
  AvgCommunicate_140195_Content_5 = {
    Text = "Или, скажем так, свежесть — это очень важно..."
  },
  AvgCommunicate_140195_Content_7 = {
    Text = "Прости, но одобрить ещё больше холодильников я не могу. Однако вот контакты Сюй и Дюлесайн."
  },
  AvgCommunicate_140195_Content_9 = {
    Text = "Вам будет о чём приятно побеседовать на тему рецептов."
  },
  AvgCommunicate_140196_Content_11 = {
    Text = "Неправильно, это шлёп-шлёп!"
  },
  AvgCommunicate_140196_Content_12 = {
    Text = "Похоже, феромон, разработанный профессором Дуэр, на мисс Мос не действует."
  },
  AvgCommunicate_140196_Content_13 = {
    Text = "Но даже несмотря на это, отношение мисс Моск ко мне осталось прежним."
  },
  AvgCommunicate_140196_Content_14 = {
    Text = "То есть, это значит, эм, как бы сказать..."
  },
  AvgCommunicate_140196_Content_15 = {
    Text = "В каком-то смысле у тебя поистине выдающиеся навыки общения, Моск..."
  },
  AvgCommunicate_140196_Content_2 = {
    Text = "A……Abandon, а, вот оно что. Хе-хе."
  },
  AvgCommunicate_140196_Content_3 = {Text = "?"},
  AvgCommunicate_140196_Content_4 = {
    Text = "Я сейчас изучаю разные языки. ……Очень интересно."
  },
  AvgCommunicate_140196_Content_6 = {
    Text = "Помимо общего языка, я узнала много нового, например вот это——"
  },
  AvgCommunicate_140196_Content_7 = {
    Text = "Буль-буль?"
  },
  AvgCommunicate_140196_Content_8 = {
    Text = "Шлёп-шлёп!"
  },
  AvgCommunicate_140196_Content_9 = {
    Text = "Правильно!"
  },
  AvgCommunicate_140196_Option_8 = {
    Text = "Шлёп-шлёп!"
  },
  AvgCommunicate_141374_Content_1 = {
    Text = "Торжественная благодарность, пожалуй, прозвучит немного чопорно, и всё же — от всего сердца: спасибо тебе, ради меня самого и ради всего Эпоянса."
  },
  AvgCommunicate_141374_Content_10 = {
    Text = "Я проявляю эти качества потому, что такова моя природа."
  },
  AvgCommunicate_141374_Content_12 = {
    Text = "Не говори такие вещи с таким гордым видом."
  },
  AvgCommunicate_141374_Content_13 = {
    Text = "Так что помочь мне прикоснуться к тому пределу и вырваться из-под Его контроля — это действительно огромная услуга."
  },
  AvgCommunicate_141374_Content_14 = {
    Text = "Многое из того, что прежде казалось невозможным, теперь больше не является проблемой."
  },
  AvgCommunicate_141374_Content_15 = {
    Text = "Ещё не поздно забрать всё обратно?"
  },
  AvgCommunicate_141374_Content_16 = {
    Text = "Успокойся, Понтос, в Лондиниуме действует полноценная система законов!"
  },
  AvgCommunicate_141374_Content_2 = {
    Text = "Такая внезапная серьёзность — это и правда немного непривычно."
  },
  AvgCommunicate_141374_Content_3 = {
    Text = "Ты, наверное, не представляешь, что это значит: до тех пор, пока я не стал достаточно силён, Эпоянс на самом деле не мог вырваться из-под контроля того древнего существа."
  },
  AvgCommunicate_141374_Content_4 = {
    Text = "Такова была моя сделка с Ним. К счастью, Он не питал злого умысла — можно даже сказать, был великодушен."
  },
  AvgCommunicate_141374_Content_5 = {
    Text = "Однако Он всё же не принадлежит к роду человеческому. Под Его властью Эпоянс становился бы всё более непредсказуемым, а люди в Эпоянсе — всё более склонными к крайностям."
  },
  AvgCommunicate_141374_Content_6 = {
    Text = "Получается, ты раньше тоже был таким из-за Его влияния? Таким, ну…"
  },
  AvgCommunicate_141374_Content_7 = {
    Text = "Дай угадаю — ты хочешь сказать: Паранойя, злопамятность или мания контроля?"
  },
  AvgCommunicate_141374_Content_9 = {Text = "Нет."},
  AvgCommunicate_141374_Option_2 = {
    Text = "Немного непривычно"
  },
  AvgCommunicate_141374_Option_6 = {
    Text = "Неужели"
  },
  AvgCommunicate_143429_Content_1 = {
    Text = "Хотя эти служители культа, поклоняющиеся лжебогам, глупы до смешного, нельзя не признать, что у некоторых из них вкус весьма недурён."
  },
  AvgCommunicate_143429_Content_10 = {
    Text = "Да и эпохи там совсем не те!"
  },
  AvgCommunicate_143429_Content_11 = {
    Text = "Я же считаю, что если ты воспримешь побольше подобных влияний и укрепишь свои амбиции, это может значительно сократить число случаев, когда ты попадаешь в беду на выездных заданиях и зовёшь на помощь."
  },
  AvgCommunicate_143429_Content_12 = {
    Text = "Конечно, если почаще называть меня дядей, я с удовольствием буду всегда прикрывать нерадивых малышей."
  },
  AvgCommunicate_143429_Content_13 = {
    Text = "…Я прямо сейчас пойду поговорю с Голиафом."
  },
  AvgCommunicate_143429_Content_14 = {
    Text = "Внесу их в список запрещённых фильмов Мисага — нечего всем подряд рекомендовать!"
  },
  AvgCommunicate_143429_Content_2 = {
    Text = "Несколько дней назад, когда он тайно от Мириам часто покидал Мисаг, я уже была в шоке…"
  },
  AvgCommunicate_143429_Content_3 = {
    Text = "Ты случайно не о Голиафе говоришь?…"
  },
  AvgCommunicate_143429_Content_4 = {
    Text = "Хм, во-первых, я восхищаюсь его решимостью унижаться ради достижения своих целей."
  },
  AvgCommunicate_143429_Content_5 = {
    Text = "Во-вторых, рекомендованные им постановки и правда очень интересные."
  },
  AvgCommunicate_143429_Content_6 = {
    Text = "Трудно представить, что Голиаф ещё и в театр ходит."
  },
  AvgCommunicate_143429_Content_7 = {
    Text = "Он порекомендовал мне «Прошлое Лео», «Учи■», всем очень понравилось."
  },
  AvgCommunicate_143429_Content_8 = {
    Text = "Сегодня вечером в Эпоянс должны показывать «Волка Лондиниума»."
  },
  AvgCommunicate_143429_Content_9 = {
    Text = "Нет, подождите, Мисаг не допускает появления главарей банд, и культ волчьей хватки тоже не разрешён!"
  },
  AvgCommunicate_143429_Option_2 = {
    Text = "Ты случайно не имеешь в виду"
  },
  AvgCommunicate_143430_Content_1 = {
    Text = "Шестое заявление о переводе за этот месяц — похоже, правила деканата работают не всегда."
  },
  AvgCommunicate_143430_Content_10 = {
    Text = "Ах, жаль."
  },
  AvgCommunicate_143430_Content_11 = {
    Text = "Эй?? Эй?! Почему какой-то Мар взял листок с ответами на экзамен и уселся писать мою курсовую?!"
  },
  AvgCommunicate_143430_Content_12 = {
    Text = "На тебе слишком много всего лежит — даже если ты сказал это в шутку, это значит, что тебе нужно как следует Расслабление, малыш."
  },
  AvgCommunicate_143430_Content_13 = {
    Text = "Только на этот раз — хотя мне это и в радость, я всё же постараюсь не превращаться в того родителя, что балует ребёнка."
  },
  AvgCommunicate_143430_Content_14 = {
    Text = "А теперь открой окно — я возьму тебя погулять на вечер и покажу, как можно забыть о реальности без всякого Эпоянса."
  },
  AvgCommunicate_143430_Content_15 = {Text = "…Ура!"},
  AvgCommunicate_143430_Content_3 = {
    Text = "Средний балл, посещаемость, коэффициент практической конверсии… и, хм, давление с трудоустройством, которого нет у Хранителей, но которое испытывает большинство обычных студентов."
  },
  AvgCommunicate_143430_Content_4 = {
    Text = "Даже когда Разъедание совсем рядом, насущные проблемы всё равно пугают до дрожи."
  },
  AvgCommunicate_143430_Content_5 = {
    Text = "Желание сбежать от реальности — это нормально. Может, возьмёшь и меня в Эпоянс?…"
  },
  AvgCommunicate_143430_Content_6 = {
    Text = "Ты серьёзно?"
  },
  AvgCommunicate_143430_Content_7 = {
    Text = "За окном и правда слышен звук хлопающих крыльев, или это у меня Фантазм после трёх ночей подготовки к экзаменам?"
  },
  AvgCommunicate_143430_Content_8 = {
    Text = "Такой шанс упускать нельзя — даже если потом весь Мисаг будет меня преследовать, я с огромным удовольствием соглашусь."
  },
  AvgCommunicate_143430_Content_9 = {
    Text = "Нет-нет-нет-нет-нет-нет, я шучу, пожалуйста, ни в коем случае не делай этого."
  },
  AvgCommunicate_143431_Content_1 = {
    Text = "Что-то нужно?"
  },
  AvgCommunicate_143431_Content_10 = {
    Text = "Хахахахаха, ладно, не делай такую Эмоцию."
  },
  AvgCommunicate_143431_Content_11 = {
    Text = "Достать его личную печать — не проблема. А что касается адреса благотворительного вечера — как насчёт Эпоянса?"
  },
  AvgCommunicate_143431_Content_12 = {
    Text = "Следующим шагом полиция арестует нас всех за нарушение частной собственности."
  },
  AvgCommunicate_143431_Content_14 = {
    Text = "Ну что ж, жаль. Я на несколько дней уйду в Уклонение."
  },
  AvgCommunicate_143431_Content_15 = {
    Text = "Убить его, когда он потеряет бдительность, пожалуй, будет куда интереснее."
  },
  AvgCommunicate_143431_Content_16 = {Text = "???!"},
  AvgCommunicate_143431_Content_2 = {
    Text = "Э-э, Понтос, не хочешь ли ты подумать о том, чтобы вернуться в Эпоянс на какое-то время."
  },
  AvgCommunicate_143431_Content_3 = {
    Text = "Профессор Декстер уже целых два месяца не появлялся в школе."
  },
  AvgCommunicate_143431_Content_4 = {
    Text = "Ха, трусливая грязная тварь — сейчас, наверное, в бешенстве срывается на каком-нибудь несчастном из своих подчинённых."
  },
  AvgCommunicate_143431_Content_5 = {
    Text = "Не беспокойся, пока он не вернулся к своему Генезису, у него ещё нет права называться моим Противником."
  },
  AvgCommunicate_143431_Content_6 = {
    Text = "Проблема в том, что целая куча документов ждёт его личной печати, и что теперь делать с благотворительным банкетом этого года! Заставить директора Чорта и профессора Долл присутствовать на подобном мероприятии сложнее, чем попросить их взорвать Мисаг."
  },
  AvgCommunicate_143431_Content_7 = {
    Text = "Если вести мероприятие будет учитель Сильвия, то беспокоиться придётся уже о совсем других вещах…"
  },
  AvgCommunicate_143431_Content_8 = {
    Text = "Как грустно, малыш. Я знаю, что в Мисаге тебя опекает множество людей, и ты больше не нуждаешься во мне, а я сделал для тебя так много, ты даже…"
  },
  AvgCommunicate_145234_Content_1 = {
    Text = "Стало тихо."
  },
  AvgCommunicate_145234_Content_10 = {
    Text = "Значит, ты больше не хочешь продолжать сражаться?"
  },
  AvgCommunicate_145234_Content_11 = {
    Text = "Хе-хе-хе-хе..."
  },
  AvgCommunicate_145234_Content_12 = {
    Text = "Конечно, нет."
  },
  AvgCommunicate_145234_Content_13 = {
    Text = "Мне больше не нужно использовать бой, чтобы успокоить тело, но…"
  },
  AvgCommunicate_145234_Content_14 = {
    Text = "Теперь я могу свободнее использовать всю свою Силу, чтобы бросать вызов тем, кому я хочу бросить вызов!"
  },
  AvgCommunicate_145234_Content_15 = {
    Text = "Думаю, мне стоит сказать тебе спасибо."
  },
  AvgCommunicate_145234_Content_16 = {
    Text = "Ты привёл меня к вершине, о которой я всегда мечтал. Но…"
  },
  AvgCommunicate_145234_Content_17 = {
    Text = "Путь Силы никогда не имеет конца. Не так ли, Хранитель?"
  },
  AvgCommunicate_145234_Content_2 = {
    Text = "Тихо? Что ты имеешь в виду?"
  },
  AvgCommunicate_145234_Content_3 = {
    Text = "Кровь больше не кипит, кости больше не охвачены Беспокойством, и мой меч больше не рычит…"
  },
  AvgCommunicate_145234_Content_4 = {
    Text = "С самого момента моего рождения они не умолкали."
  },
  AvgCommunicate_145234_Content_5 = {
    Text = "Теперь они все затихли."
  },
  AvgCommunicate_145234_Content_6 = {
    Text = "Это плохо?"
  },
  AvgCommunicate_145234_Content_7 = {
    Text = "Вы в порядке?"
  },
  AvgCommunicate_145234_Content_8 = {
    Text = "Прежний шум был от Голода, от Тревоги из-за недостаточной силы и скорости."
  },
  AvgCommunicate_145234_Content_9 = {
    Text = "Но теперь они исчезли. Моё тело… впервые ощутило насыщение."
  },
  AvgCommunicate_145234_Option_6 = {
    Text = "Это плохо?"
  },
  AvgCommunicate_145234_Option_7 = {
    Text = "Вы в порядке?"
  },
  AvgCommunicate_146392_Content_1 = {
    Text = "Здесь?"
  },
  AvgCommunicate_146392_Content_10 = {
    Text = "Я заплатила ей, чтобы она передала это дело мне."
  },
  AvgCommunicate_146392_Content_11 = {
    Text = "Ты нашла его?"
  },
  AvgCommunicate_146392_Content_12 = {
    Text = "Оно прямо передо мной. Похоже, крепко спит."
  },
  AvgCommunicate_146392_Content_13 = {
    Text = "Жду, когда оно проснётся."
  },
  AvgCommunicate_146392_Content_14 = {
    Text = "Всё понятно…"
  },
  AvgCommunicate_146392_Content_15 = {
    Text = "Дай подумаю, чем бы ты могла себя занять, пока ждёшь…"
  },
  AvgCommunicate_146392_Content_16 = {
    Text = "А, придумала! Ты можешь…"
  },
  AvgCommunicate_146392_Content_17 = {
    Text = "Глаз двигается… Оно просыпается."
  },
  AvgCommunicate_146392_Content_18 = {
    Text = "Ухожу."
  },
  AvgCommunicate_146392_Content_19 = {
    Text = "Эй? Лотан?"
  },
  AvgCommunicate_146392_Content_2 = {Text = "?"},
  AvgCommunicate_146392_Content_3 = {
    Text = "Лотан? Я думал, тебе неинтересно возиться с такими вещами."
  },
  AvgCommunicate_146392_Content_4 = {
    Text = "Немного скучно, вот и тестирую механическую штуковину, которую дала Долл."
  },
  AvgCommunicate_146392_Content_5 = {
    Text = "Может, когда-нибудь пригодится."
  },
  AvgCommunicate_146392_Content_6 = {
    Text = "Ты и скучать умеешь?"
  },
  AvgCommunicate_146392_Content_7 = {
    Text = "Я думал, ты либо дерёшься, либо на Пути к очередной драке."
  },
  AvgCommunicate_146392_Content_8 = {
    Text = "Кстати, ты где сейчас? Кажется, я не видела тебя уже несколько дней…"
  },
  AvgCommunicate_146392_Content_9 = {
    Text = "Говорят, Даффодил ведёт Преследование какого-то могущественного древнего существа."
  },
  AvgCommunicate_146392_Option_14 = {
    Text = "Всё понятно…"
  },
  AvgCommunicate_146392_Option_6 = {
    Text = "Ты и скучать умеешь?"
  },
  AvgCommunicate_146393_Content_1 = {
    Text = "Рог. Зубы. Когти. Кусок мяса. Глазное яблоко. Щупальце."
  },
  AvgCommunicate_146393_Content_10 = {
    Text = "Надеюсь, ты окажешься таким же крепким, как они."
  },
  AvgCommunicate_146393_Content_12 = {
    Text = "Благодарю покорно!"
  },
  AvgCommunicate_146393_Content_2 = {
    Text = "Выбирай."
  },
  AvgCommunicate_146393_Content_3 = {
    Text = "Это снова рубрика «угадай, что тебе понравится»?…"
  },
  AvgCommunicate_146393_Content_4 = {
    Text = "Я принесла того монстра, которого подстрелила в прошлый раз."
  },
  AvgCommunicate_146393_Content_5 = {
    Text = "Всё равно деть некуда — возьми кусочек на память."
  },
  AvgCommunicate_146393_Content_6 = {
    Text = "Что-то ничего из этого не хочется…"
  },
  AvgCommunicate_146393_Content_7 = {
    Text = "Наверное, нехорошо хотеть всё сразу…"
  },
  AvgCommunicate_146393_Content_8 = {
    Text = "Так сложно выбрать… Может, ты сама выберешь?…"
  },
  AvgCommunicate_146393_Content_9 = {
    Text = "У него неплохие рога — выдержали три удара моего меча, прежде чем сломаться. Тебе подойдут."
  },
  AvgCommunicate_146393_Option_6 = {
    Text = "Что-то ничего из этого не хочется…"
  },
  AvgCommunicate_146393_Option_7 = {
    Text = "Наверное, нехорошо хотеть всё сразу…"
  },
  AvgCommunicate_146394_Content_1 = {
    Text = "У меня возникла проблема."
  },
  AvgCommunicate_146394_Content_10 = {
    Text = "Я уходил трижды. Каждый раз, когда я уходил, они начинали приносить себя в жертву — они считают это неким испытанием от бога."
  },
  AvgCommunicate_146394_Content_11 = {
    Text = "Кучка сумасшедших."
  },
  AvgCommunicate_146394_Content_12 = {
    Text = "Но зачем ты вообще возвращался??"
  },
  AvgCommunicate_146394_Content_13 = {
    Text = "Мой меч остался воткнутым в туше этой твари — я его не вытащил."
  },
  AvgCommunicate_146394_Content_14 = {
    Text = "Теперь они поклоняются и этому мечу тоже."
  },
  AvgCommunicate_146394_Content_16 = {
    Text = "Мне нужен способ заставить их вернуть мне меч, и при этом постараться, чтобы они не покончили с собой у меня на глазах."
  },
  AvgCommunicate_146394_Content_17 = {
    Text = "Ты лучше разбираешься в образе мышления этих слабых существ, помоги мне придумать что-нибудь."
  },
  AvgCommunicate_146394_Content_18 = {
    Text = "……Что ты имеешь в виду, Эй!"
  },
  AvgCommunicate_146394_Content_2 = {
    Text = "Надо же, у тебя тоже бывают проблемы!"
  },
  AvgCommunicate_146394_Content_3 = {
    Text = "Говорят, была какая-то очень сильная тварь — я её убил."
  },
  AvgCommunicate_146394_Content_4 = {
    Text = "После её гибели все жители планеты у неё под ногами повылезали наружу."
  },
  AvgCommunicate_146394_Content_5 = {
    Text = "Эти люди называют меня богом, бьют передо мной поклоны и даже воздвигли золотую статую — страшное уродство."
  },
  AvgCommunicate_146394_Content_6 = {
    Text = "Хахахахахаха"
  },
  AvgCommunicate_146394_Content_7 = {
    Text = "Не смейся."
  },
  AvgCommunicate_146394_Content_8 = {
    Text = "Почему бы тебе просто не уйти?"
  },
  AvgCommunicate_146394_Content_9 = {
    Text = "Тебе не нравится, когда тебя почитают?"
  },
  AvgCommunicate_146394_Option_6 = {
    Text = "Хахахаха"
  },
  AvgCommunicate_146394_Option_8 = {
    Text = "Нельзя просто уйти?"
  },
  AvgCommunicate_146394_Option_9 = {
    Text = "Тебе не нравится, когда тебя почитают?"
  },
  AvgCommunicate_148438_Content_1 = {
    Text = "Ты уже всё знаешь?"
  },
  AvgCommunicate_148438_Content_10 = {
    Text = "Хи-хи, не думай так много, от лишних мыслей становишься скучным и унылым~"
  },
  AvgCommunicate_148438_Content_11 = {
    Text = "Конечно же, если Хранитель тоже неудержимо влечётся к этой фее и хочет следовать за ней каждую минуту, лишь бы завоевать её искреннее чувство — это вполне понятно~"
  },
  AvgCommunicate_148438_Content_12 = {Text = "Фу……"},
  AvgCommunicate_148438_Content_13 = {
    Text = "Самое сладкое яблоко в карамели уже лежит на столе в вашей комнате."
  },
  AvgCommunicate_148438_Content_14 = {
    Text = "Вы непременно-непременно должны есть его медленно, смаковать каждый кусочек и наслаждаться им в одиночестве~"
  },
  AvgCommunicate_148438_Content_2 = {
    Text = "Значит, ты с таким трудом добилась разрешения на выход только ради того, чтобы купить Айгис, Ожье и Мёрфи лимитированные сахарные яблоки, которых Они никогда не пробовали?"
  },
  AvgCommunicate_148438_Content_3 = {
    Text = "Мелкие… кхм-кхм, эти благочестивые дети, пусть и не платят взносы в полном объёме, сыграли крайне важную роль в распространении феей своих благодатей."
  },
  AvgCommunicate_148438_Content_4 = {
    Text = "Уметь поддерживать связь со своей паствой, побуждая Их ещё активнее нести благую весть церкви, — это, конечно, тоже одна из тяжких обязанностей, лежащих на плечах этой феи~"
  },
  AvgCommunicate_148438_Content_5 = {
    Text = "Даже если на этот раз была веская причина, почему деньги списали с моего счёта……"
  },
  AvgCommunicate_148438_Content_7 = {
    Text = "Не обращай внимания на такие мелочи, смотри — дети теперь свято верят в это, так когда же Хранитель наконец присоединится к ним?"
  },
  AvgCommunicate_148438_Content_9 = {
    Text = "Так и не пойму, ты иногда всё же проявляешь искренность, или ты как лук — вечно скрываешь свои истинные цели под слоями шелухи……"
  },
  AvgCommunicate_148439_Content_1 = {
    Text = "«Изображение»"
  },
  AvgCommunicate_148439_Content_10 = {
    Text = "«Изображение успешно загружено»"
  },
  AvgCommunicate_148439_Content_11 = {
    Text = "«Изображение»"
  },
  AvgCommunicate_148439_Content_12 = {
    Text = "Что… это и правда письмо с извинениями…"
  },
  AvgCommunicate_148439_Content_13 = {
    Text = "Прости… Карабу, я не должна была так реагировать в тот редкий момент, когда ты искренне раскаялась."
  },
  AvgCommunicate_148439_Content_14 = {
    Text = "Я прямо сейчас отзову только что поданную жалобу с предложением о домашнем аресте… запрете на все заявки о выходе… Готово! Я отозвала все свои жалобы против тебя."
  },
  AvgCommunicate_148439_Content_15 = {
    Text = "Отлично~ Хи-хи, Хранитель, если я правильно помню, после отзыва жалобы в течение одного месяца нельзя подавать повторную жалобу на того же Пробуждённого, верно?"
  },
  AvgCommunicate_148439_Content_17 = {
    Text = "У меня нехорошее предчувствие."
  },
  AvgCommunicate_148439_Content_18 = {
    Text = "Ну что вы, фея не станет так неблагодарно играть на искренних чувствах %player%. Каждое слово в письме с извинениями — чистая правда. Когда вернусь с прогулки, обязательно принесу тебе самое сладкое красное яблоко~"
  },
  AvgCommunicate_148439_Content_19 = {
    Text = "Подожди, почему Айгис пришла ко мне в слезах и говорит, что не знает, в чём провинилась, но надеется, что я прощу её, когда увижу письмо с извинениями?"
  },
  AvgCommunicate_148439_Content_2 = {
    Text = "Загрузка……"
  },
  AvgCommunicate_148439_Content_20 = {
    Text = "И ты обещала передать его от её имени, а она, чтобы убедиться, что я на неё не злюсь, решила ещё раз извиниться лично?!"
  },
  AvgCommunicate_148439_Content_21 = {
    Text = "Эй, Карабу, Карабу!!"
  },
  AvgCommunicate_148439_Content_3 = {Text = "?"},
  AvgCommunicate_148439_Content_4 = {
    Text = "Карабу, этот трюк ты уже использовала однажды, что бы ты ни говорила — я не открою эту картинку."
  },
  AvgCommunicate_148439_Content_5 = {
    Text = "Нет, %player%… Я серьёзно всё обдумала и раскаялась. Вы и все в Мисаге так добры ко мне — я не должна была тащить сюда свои старые привычки, в это святое место."
  },
  AvgCommunicate_148439_Content_6 = {
    Text = "В конце концов, изначально я не по своей воле оказалась в такой ситуации."
  },
  AvgCommunicate_148439_Content_7 = {
    Text = "Поэтому я написала искреннее письмо с извинениями — собственноручно, слово за словом. Вот только, как назло, именно в этот момент связь через Серебро начала барахлить…"
  },
  AvgCommunicate_148439_Content_8 = {
    Text = "Вполне понятно, что вы не хотите мне верить. Я буду терпеливо ждать того дня, когда вы снова захотите доверять мне…"
  },
  AvgCommunicate_148439_Content_9 = {
    Text = "…Почему у меня смутно ноет совесть? Но в любом случае я ни за что не…"
  },
  AvgCommunicate_148440_Content_1 = {
    Text = "«Изображение»"
  },
  AvgCommunicate_148440_Content_10 = {
    Text = "Что ты говоришь! Да кто же будет возвращать?"
  },
  AvgCommunicate_148440_Content_11 = {Text = "А?"},
  AvgCommunicate_148440_Content_12 = {
    Text = "Даже притворяться не будешь?"
  },
  AvgCommunicate_148440_Content_13 = {
    Text = "Хи-хи, служение фее само по себе является твоей величайшей честью — оно приведёт тебя в высшее блаженство, так что мирское вознаграждение, конечно же, не идёт ни в какое сравнение."
  },
  AvgCommunicate_148440_Content_14 = {
    Text = "Хватит об этом, если не переведёшь деньги побыстрее, карту уже не восстановить."
  },
  AvgCommunicate_148440_Content_16 = {
    Text = "Я уже открыл и посмотрел — это просто грубая Технология Серебра с поддельным изображением…"
  },
  AvgCommunicate_148440_Content_17 = {
    Text = "О? Ты открыл? Ты сделал это добровольно~Замечательно! Фея навсегда запомнит подношение %player%."
  },
  AvgCommunicate_148440_Content_18 = {
    Text = "Подождите, почему мне пришло уведомление, что списали 1000 Леонских флоринов — это же моя полевая надбавка!"
  },
  AvgCommunicate_148440_Content_2 = {
    Text = "Загрузка……"
  },
  AvgCommunicate_148440_Content_20 = {
    Text = "Ладно, ладно, не ожидала, что ты такой богатый — на этот раз возьму только 200 Леонских флоринов в качестве платы за то, что научила тебя не открывать незнакомую Технологию Серебра в коммуникаторе. Цени милосердие феи, хорошо?"
  },
  AvgCommunicate_148440_Content_21 = {
    Text = "«Перевод · 800 Леонских флоринов»"
  },
  AvgCommunicate_148440_Content_3 = {
    Text = "«Изображение повреждено»"
  },
  AvgCommunicate_148440_Content_4 = {
    Text = "……Что ты отправил?"
  },
  AvgCommunicate_148440_Content_5 = {Text = "Ой!.."},
  AvgCommunicate_148440_Content_6 = {
    Text = "Вот беда, там была восточная карта, добытая с огромным трудом преданными верующими феи, и оригинал тоже повреждён — это определённо злые силы @2 мешают нам отправиться на восток!"
  },
  AvgCommunicate_148440_Content_7 = {
    Text = "%player%l, сколько у тебя ещё Леонских флоринов? Быстро отдавай все, пока ещё есть шанс восстановить……"
  },
  AvgCommunicate_148440_Content_8 = {
    Text = "Когда доберёшься до востока, вернёшь десятикратно, да? Эта схема в Мисаге уже слишком избита."
  },
  AvgCommunicate_148440_Content_9 = {
    Text = "Мошенничество без развития не имеет будущего."
  },
  AvgCommunicate_149803_Content_1 = {
    Text = "Охранное задание, порученное мне академией, выполнено. Есть ли что-нибудь, что вы хотите, чтобы я сделала, господин?"
  },
  AvgCommunicate_149803_Content_10 = {
    Text = "В любом случае, если вы не хотите сидеть без дела, через несколько дней в академии будет много мероприятий — может, сходите развлечься?"
  },
  AvgCommunicate_149803_Content_11 = {
    Text = "...Раз это приказ господина, я подчинюсь."
  },
  AvgCommunicate_149803_Content_12 = {
    Text = "Я пока пойду на патрулирование."
  },
  AvgCommunicate_149803_Content_13 = {
    Text = "Надеюсь, вы потом действительно послушаетесь!"
  },
  AvgCommunicate_149803_Content_2 = {
    Text = "Не хочешь немного отдохнуть?"
  },
  AvgCommunicate_149803_Content_3 = {
    Text = "В этом нет необходимости."
  },
  AvgCommunicate_149803_Content_4 = {
    Text = "К тому же... у меня нет права наслаждаться подобным покоем."
  },
  AvgCommunicate_149803_Content_5 = {
    Text = "Та тёмная тень время от времени всё ещё нашёптывает мне на ухо."
  },
  AvgCommunicate_149803_Content_6 = {
    Text = "Возможно, когда у меня есть дело, мне на самом деле спокойнее."
  },
  AvgCommunicate_149803_Content_7 = {
    Text = "Вот и всё, господин, не беспокойтесь об этом."
  },
  AvgCommunicate_149803_Content_8 = {
    Text = "Пожалуй, мне стоит объяснить вам необходимость безделья."
  },
  AvgCommunicate_149803_Content_9 = {
    Text = "Чем больше отдыхаешь, тем лучше сражаешься."
  },
  AvgCommunicate_149803_Option_8 = {
    Text = "Пожалуй, мне стоит объяснить вам необходимость безделья."
  },
  AvgCommunicate_149803_Option_9 = {
    Text = "Чем больше отдыхаешь, тем лучше сражаешься."
  },
  AvgCommunicate_149950_Content_10 = {
    Text = "Хм......ты насмехаешься надо мной? Это предел того, насколько я сейчас могу управлять этим телом!"
  },
  AvgCommunicate_149950_Content_11 = {
    Text = "Что ты задумал? Продолжать подстрекать его и манипулировать им?"
  },
  AvgCommunicate_149950_Content_12 = {
    Text = "Если бы я мог, то давно бы уже......"
  },
  AvgCommunicate_149950_Content_13 = {
    Text = "Ладно, стать щитом или стеной вместо острого клинка — похоже, тоже неплохо......"
  },
  AvgCommunicate_149950_Content_14 = {
    Text = "Что касается господина, которому он доверяет и которому служит, — тебя, — пообщавшись, должен признать: довольно интересно."
  },
  AvgCommunicate_149950_Content_15 = {
    Text = "Я всё понял — это Ожье оказал на тебя обратное влияние."
  },
  AvgCommunicate_149950_Content_17 = {Text = "???"},
  AvgCommunicate_149950_Content_18 = {
    Text = "Господин, прошу прощения. Я только что на несколько минут потерял сознание."
  },
  AvgCommunicate_149950_Content_19 = {
    Text = "Когда пришёл в себя, увидел, что коммуникатор светится."
  },
  AvgCommunicate_149950_Content_2 = {
    Text = "Наконец-то я тебя вижу......"
  },
  AvgCommunicate_149950_Content_20 = {
    Text = "Почему-то кажется, что только что снова услышал этот давно забытый раздражающий голос......"
  },
  AvgCommunicate_149950_Content_21 = {
    Text = "Как бы это сказать......похоже, ты и та сила внутри тебя уже научились вполне мирно сосуществовать."
  },
  AvgCommunicate_149950_Content_22 = {
    Text = "......Я прочитал запись."
  },
  AvgCommunicate_149950_Content_23 = {
    Text = "Я беспокоился, что Оно, как прежде, скажет что-нибудь злобное и агрессивное."
  },
  AvgCommunicate_149950_Content_24 = {
    Text = "Это действительно удивительно — прежде всегда Он разъедал меня, но теперь, похоже, всё наоборот."
  },
  AvgCommunicate_149950_Content_25 = {
    Text = "Наверное, это хорошо. По крайней мере... это означает, что я окончательно победила Его."
  },
  AvgCommunicate_149950_Content_26 = {
    Text = "Конечно, не потому ли, что сила Ожье возросла, контроль над этой незримой сущностью достиг такого уровня?"
  },
  AvgCommunicate_149950_Content_27 = {
    Text = "Да, должно быть, так. Всё это перемены, произошедшие благодаря вам."
  },
  AvgCommunicate_149950_Content_28 = {
    Text = "К тому же для меня постигнутый «Конечный Закон» — это не только сила..."
  },
  AvgCommunicate_149950_Content_29 = {
    Text = "Но и убеждение защищать других — оно горит в моей груди куда сильнее, чем прежде. Думаю, именно в этом и кроется первопричина."
  },
  AvgCommunicate_149950_Content_3 = {
    Text = "Ты не Ожье. Кто ты?"
  },
  AvgCommunicate_149950_Content_4 = {
    Text = "Немедленно верни коммуникатор хозяину!"
  },
  AvgCommunicate_149950_Content_5 = {
    Text = "Смешно. Если бы не моё существование, как бы этот ребёнок выжил и как бы остался здесь в качестве Пробуждённого?"
  },
  AvgCommunicate_149950_Content_6 = {
    Text = "Ты......та незримая сущность, что прикрепилась к нему?"
  },
  AvgCommunicate_149950_Content_7 = {
    Text = "Именно так. Хранитель тайн Мисаги, неужели ты меня не узнаёшь."
  },
  AvgCommunicate_149950_Content_8 = {
    Text = "Э......ты всё время был так крепко подавлен Ожье, что я попросту никогда тебя не видел."
  },
  AvgCommunicate_149950_Option_3 = {
    Text = "Ты не Ожье. Кто ты?"
  },
  AvgCommunicate_149950_Option_4 = {
    Text = "Немедленно верни коммуникатор хозяину!"
  },
  AvgCommunicate_149986_Content_1 = {
    Text = "Господин, я пришла пригласить вас."
  },
  AvgCommunicate_149986_Content_10 = {
    Text = "...Дерево."
  },
  AvgCommunicate_149986_Content_11 = {Text = "А?"},
  AvgCommunicate_149986_Content_12 = {
    Text = "Вероятно, потому что я прошла профессиональную подготовку — сколько бы хаоса ни творилось вокруг, я могу твёрдо стоять на сцене."
  },
  AvgCommunicate_149986_Content_13 = {
    Text = "Что же вообще происходит в вашем спектакле?!"
  },
  AvgCommunicate_149986_Content_14 = {
    Text = "Не знаю, я всего лишь дерево."
  },
  AvgCommunicate_149986_Content_15 = {
    Text = "...Ладно. По ходу спектакля Дженкин, играющая принцессу, должна спуститься с небес, а Лили, играющая принца, — поймать её."
  },
  AvgCommunicate_149986_Content_16 = {
    Text = "Айгис, играющая тёмного властелина, ещё должна спуститься в зал и взаимодействовать со зрителями."
  },
  AvgCommunicate_149986_Content_17 = {
    Text = "Я уже не хочу комментировать это распределение ролей..."
  },
  AvgCommunicate_149986_Content_18 = {
    Text = "Но разве это не считается спойлером?"
  },
  AvgCommunicate_149986_Content_19 = {
    Text = "Потому что я не хочу ничего скрывать от вас."
  },
  AvgCommunicate_149986_Content_2 = {
    Text = "Театральный кружок готовит постановку сказочного спектакля, в котором участвуют несовершеннолетние Пробуждённые из Мисага."
  },
  AvgCommunicate_149986_Content_20 = {
    Text = "К тому же, судя по репетициям, каждый раз случается что-то непредвиденное, так что я не могу гарантировать, что господин увидит на самом деле."
  },
  AvgCommunicate_149986_Content_21 = {
    Text = "...Это и правда очень интригует."
  },
  AvgCommunicate_149986_Content_22 = {
    Text = "Все эти действия в представлении несут в себе определённую долю опасности."
  },
  AvgCommunicate_149986_Content_23 = {
    Text = "Поэтому, исполняя роль дерева, мне необходимо по возможности следить за обстановкой на сцене и в зале, обеспечивая безопасность актёров и зрителей."
  },
  AvgCommunicate_149986_Content_24 = {
    Text = "Выходит, ты на самом деле подрабатываешь телохранителем... Звучит утомительно."
  },
  AvgCommunicate_149986_Content_25 = {
    Text = "Да. Как бы то ни было, не беспокойтесь. Пока я на сцене, я не позволю никому пострадать."
  },
  AvgCommunicate_149986_Content_3 = {
    Text = "Немного неловко об этом говорить... но я тоже выйду на сцену. Надеюсь, вы придёте посмотреть."
  },
  AvgCommunicate_149986_Content_4 = {
    Text = "! Я очень жду этого."
  },
  AvgCommunicate_149986_Content_5 = {
    Text = "Впрочем, не ожидал, что ты согласишься участвовать в подобном мероприятии."
  },
  AvgCommunicate_149986_Content_6 = {
    Text = "Да, я уже давно не ребёнок и не очень подхожу для этого."
  },
  AvgCommunicate_149986_Content_7 = {
    Text = "Но они настояли..."
  },
  AvgCommunicate_149986_Content_8 = {
    Text = "Я не хотела портить им настроение, к тому же поняла, что эту роль действительно могу сыграть только я."
  },
  AvgCommunicate_149986_Content_9 = {
    Text = "Так какую же роль будет играть Ожье? Рыцаря?"
  },
  AvgCommunicate_149987_Content_1 = {
    Text = "Господин, скажите, есть ли в последнее время курсы, связанные с Феноменом Растворения?"
  },
  AvgCommunicate_149987_Content_10 = {
    Text = "Какое усердие... Если бы я занимался так же старательно, как ты, точно не переживал бы из-за экзаменов."
  },
  AvgCommunicate_149987_Content_11 = {
    Text = "Пожалуйста, не хвалите меня так — обязанности, которые вы несёте, куда тяжелее моих."
  },
  AvgCommunicate_149987_Content_12 = {
    Text = "К тому же это лишь необходимая работа, которую я выполняю ради искупления."
  },
  AvgCommunicate_149987_Content_13 = {
    Text = "Но ты учишься очень быстро — кто знает, может, у Ожье есть задатки учёного."
  },
  AvgCommunicate_149987_Content_14 = {
    Text = "Как и все в детстве, каждый задумывается о будущем."
  },
  AvgCommunicate_149987_Content_15 = {
    Text = "Ожье, ты когда-нибудь думал о том, кем хочешь стать, когда вырастешь?"
  },
  AvgCommunicate_149987_Content_16 = {
    Text = "Вы знаете, что я стал Пробуждённым — у меня больше нет возможности вырасти."
  },
  AvgCommunicate_149987_Content_17 = {
    Text = "Но можно же помечтать о планах на будущее! Не нужно быть таким пессимистом."
  },
  AvgCommunicate_149987_Content_18 = {
    Text = "Неужели у Ожье нет ничего, чего он хотел бы, помимо «защиты других»?"
  },
  AvgCommunicate_149987_Content_19 = {
    Text = "Благодарю вас за поддержку."
  },
  AvgCommunicate_149987_Content_2 = {
    Text = "Я хочу изучить это более глубоко."
  },
  AvgCommunicate_149987_Content_20 = {
    Text = "Что касается других желаний... Простите, я так ничего и не могу придумать."
  },
  AvgCommunicate_149987_Content_21 = {
    Text = "Когда это тело перестанет быть запятнано грехом, тогда и подумаю."
  },
  AvgCommunicate_149987_Content_3 = {
    Text = "Конечно, конечно, потом схожу туда вместе с тобой."
  },
  AvgCommunicate_149987_Content_4 = {
    Text = "Но почему Ожье вдруг захотел изучать это направление?"
  },
  AvgCommunicate_149987_Content_5 = {
    Text = "Сегодня кто-то спросил меня, связана ли сила, окутывающая моё тело, с Р-слизью."
  },
  AvgCommunicate_149987_Content_6 = {
    Text = "Понятно, если судить только по форме, они и правда немного похожи."
  },
  AvgCommunicate_149987_Content_7 = {
    Text = "Да, меня всегда интересовала природа этой незримой субстанции — возможно, достаточно хорошо изучив её, я смогу лучше ею управлять."
  },
  AvgCommunicate_149987_Content_8 = {
    Text = "Хотя, приехав в Мисаг, я обнаружил, что непостижимых существ здесь куда больше, чем я мог представить......"
  },
  AvgCommunicate_149987_Content_9 = {
    Text = "Поэтому я решил сначала глубже изучить знания, связанные с Р-слизью, — ведь это и есть враг, с которым мой господин сражается уже долгое время."
  },
  AvgCommunicate_149988_Content_1 = {
    Text = "Ах, мой непослушный пёсик, что вечно носится по всему свету."
  },
  AvgCommunicate_149988_Content_10 = {
    Text = "Никому нет дела."
  },
  AvgCommunicate_149988_Content_11 = {
    Text = "Так или иначе, не забывай: ты мой личный прирученный пёсик, и угроза твоей жизни — это потеря моих активов."
  },
  AvgCommunicate_149988_Content_12 = {
    Text = "К тому же, это место — тщательно отобранная мной щель, не тронутая эрозией."
  },
  AvgCommunicate_149988_Content_13 = {
    Text = "Будь осторожен, не разрушь этот мир."
  },
  AvgCommunicate_149988_Content_2 = {
    Text = "Сигнал снова пропадает, куда это ты забрался на этот раз?"
  },
  AvgCommunicate_149988_Content_3 = {
    Text = "Я на Континенте Северного конца."
  },
  AvgCommunicate_149988_Content_4 = {
    Text = "Я в высокогорье."
  },
  AvgCommunicate_149988_Content_5 = {
    Text = "Скоро предстоит восхождение. Я беспокоюсь о своей физической форме."
  },
  AvgCommunicate_149988_Content_6 = {
    Text = "Воздух в высокогорье действительно очень разрежённый — мне кажется, стоит пробежать несколько шагов, и я задохнусь."
  },
  AvgCommunicate_149988_Content_7 = {
    Text = "И при этом ты ещё хочешь идти в горы? Какой же ты самонадеянный и безрассудный пёсик."
  },
  AvgCommunicate_149988_Content_8 = {
    Text = "Я знаю, что ты беспокоишься обо мне, но у меня есть дело, которое необходимо завершить."
  },
  AvgCommunicate_149988_Content_9 = {
    Text = "Не волнуйся, здесь тоже есть старший Уильям, с нами ничего не случится."
  },
  AvgCommunicate_149988_Option_3 = {
    Text = "Континент Северного конца."
  },
  AvgCommunicate_149988_Option_4 = {
    Text = "В высокогорье."
  },
  AvgCommunicate_150103_Content_1 = {
    Text = "Я ощутил, как с далёкого края донеслась едва слышная дрожь нити судьбы."
  },
  AvgCommunicate_150103_Content_10 = {
    Text = "Это звено судьбы?"
  },
  AvgCommunicate_150103_Content_11 = {
    Text = "Я должен хранить молчание."
  },
  AvgCommunicate_150103_Content_12 = {
    Text = "А как же те люди из прежнего мира? Что с ними будет?"
  },
  AvgCommunicate_150103_Content_13 = {
    Text = "Они вернутся к чистейшей своей форме — Серебру."
  },
  AvgCommunicate_150103_Content_14 = {
    Text = "А тот Бог-Царь выловит эти осколки из пелены дождя и после долгого сна воссоздаст мир заново."
  },
  AvgCommunicate_150103_Content_15 = {
    Text = "Я буду свидетелем этого вместе с тобой."
  },
  AvgCommunicate_150103_Content_2 = {
    Text = "Полагаю, ты уже миновал узловую точку судьбы и достиг земли обетованной, которую так долго искал."
  },
  AvgCommunicate_150103_Content_3 = {
    Text = "Не могу поверить."
  },
  AvgCommunicate_150103_Content_4 = {
    Text = "Мир исчез."
  },
  AvgCommunicate_150103_Content_5 = {
    Text = "Я вижу, как небо растворяется, снега обрушиваются, вершины рассыпаются."
  },
  AvgCommunicate_150103_Content_6 = {
    Text = "Они — истинные подделки."
  },
  AvgCommunicate_150103_Content_7 = {
    Text = "Ты всегда знал, ты всегда мог видеть?"
  },
  AvgCommunicate_150103_Content_8 = {
    Text = "Я всегда стоял за пределами сцены мира, вечно прядя нити."
  },
  AvgCommunicate_150103_Content_9 = {
    Text = "Включая желание Карабу? Ведь без её желания мир бы не рассеялся."
  },
  AvgCommunicate_150103_Option_3 = {
    Text = "Я вижу…"
  },
  AvgCommunicate_150103_Option_4 = {
    Text = "Мир исчез…"
  },
  AvgCommunicate_57593_Content_1 = {
    Text = "Напарник, ты прочитал те книги по истории и естествознанию, которые я тебе в прошлый раз принёс?"
  },
  AvgCommunicate_57593_Content_10 = {
    Text = "А? Обязательно так серьёзно?.."
  },
  AvgCommunicate_57593_Content_11 = {
    Text = "Это обязательные книги для каждого следователя. Даже если придётся зубрить — ты должен это выучить."
  },
  AvgCommunicate_57593_Content_12 = {
    Text = "Я планирую заниматься с тобой по часу в день. Если хочешь закончить побыстрее, я не против позаниматься с тобой и всю ночь."
  },
  AvgCommunicate_57593_Content_13 = {
    Text = "Н-нет, лучше помедленнее... Я думаю, часа вполне достаточно! Слишком много информации мешает закреплению материала!"
  },
  AvgCommunicate_57593_Content_14 = {
    Text = "Отлично, у тебя очень хороший настрой к учёбе."
  },
  AvgCommunicate_57593_Content_15 = {
    Text = "Не забудь взять тетрадь, я буду в любой момент проверять, как ты повторяешь материал."
  },
  AvgCommunicate_57593_Content_17 = {
    Text = "Ненавижу свой болтливый язык..."
  },
  AvgCommunicate_57593_Content_2 = {
    Text = "Э-э, ну, это, в общем, можно сказать, что... прочитал."
  },
  AvgCommunicate_57593_Content_3 = {
    Text = "Сколько прочитал?"
  },
  AvgCommunicate_57593_Content_4 = {
    Text = "Примерно... оглавление."
  },
  AvgCommunicate_57593_Content_6 = {
    Text = "Эти книги слишком толстые и скучные! Стоит только взглянуть на эти мелкие буковки — и сразу засыпаешь..."
  },
  AvgCommunicate_57593_Content_7 = {
    Text = "Зато после чтения я всегда отлично сплю..."
  },
  AvgCommunicate_57593_Content_8 = {
