  AvgCommunicate_57594_Content_12 = {
    Text = "Без проблем, это мой долг как напарника."
  },
  AvgCommunicate_57594_Content_13 = {
    Text = "Учительница Доэр тоже очень рада и решила составить для тебя эксклюзивный набор дополнительных заданий."
