  AvgCommunicate_57594_Content_6 = {
    Text = "О, Правда? Забыл(а) тебе сказать — учительница Доэр стоит прямо рядом со мной и всё видит."
  },
  AvgCommunicate_57594_Content_7 = {
    Text = "Внезапно ощутил(а) пылающую страсть к учёбе."
  },
  AvgCommunicate_57594_Content_8 = {
    Text = "Как это так — у меня остались несданные задания?! Разве можно это оставить без внимания?"
  },
  AvgCommunicate_57594_Content_9 = {
