  AvgCommunicate_57903_Content_1 = {
    Text = "Добрый день, Бледный посланец."
  },
  AvgCommunicate_57903_Content_10 = {
    Text = "Должен признать, весьма изящно."
  },
  AvgCommunicate_57903_Content_2 = {
    Text = "Здравствуйте, епископ Сальвадор."
  },
  AvgCommunicate_57903_Content_3 = {
    Text = "Похоже, ты получил новейший коммуникатор. Как он тебе?"
  },
  AvgCommunicate_57903_Content_4 = {
    Text = "Очень интересная и удобная вещь. Несмотря на сотни миль между нами, мы можем общаться, словно лицом к лицу."
  },
  AvgCommunicate_57903_Content_5 = {
    Text = "Если бы у каждого в мире было такое устройство, расстояние между людьми наверняка не казалось бы таким огромным, как сейчас."
  },
  AvgCommunicate_57903_Content_6 = {
    Text = "Впрочем, я понимаю уникальность этой технологии — ты знаешь, что она передаёт информацию, устанавливая связь с другими разумами?"
