  AvgCommunicate_57903_Content_7 = {
    Text = "Я знаю лишь то, что внутри серебряное ядро."
  },
  AvgCommunicate_57903_Content_8 = {
    Text = "Ты это увидел?"
  },
  AvgCommunicate_57903_Content_9 = {
    Text = "Именно так. Наш разум связан с серебряным ядром, а оно, в свою очередь, связано с серебряными ядрами в других подобных устройствах."
  },
  AvgCommunicate_57903_Option_2 = {
    Text = "Здравствуйте, епископ Сальвадор."
  },
  AvgCommunicate_57903_Option_7 = {
    Text = "Я знаю лишь то, что внутри серебряное ядро."
