  AvgCommunicate_57903_Option_8 = {
    Text = "Ты это увидел?"
  },
  AvgCommunicate_57904_Content_1 = {
    Text = "Страж, большое спасибо за припасы, доставленные вчера в санаторий. И, пожалуйста, передайте мою благодарность лорду Декстеру за его постоянную поддержку."
  },
  AvgCommunicate_57904_Content_10 = {
    Text = "Это единственное, что я могу сделать для этого ребёнка."
