  AvgCommunicate_57904_Content_2 = {
    Text = "Это наш долг."
  },
  AvgCommunicate_57904_Content_3 = {
    Text = "Без вас санаторий не продержался бы до сегодняшнего дня."
  },
  AvgCommunicate_57904_Content_4 = {
    Text = "Директор, должно быть, тоже будет вам очень благодарна."
  },
  AvgCommunicate_57904_Content_5 = {
    Text = "Управлять санаторием в одиночку — ты молодец, что справляешься."
  },
  AvgCommunicate_57904_Content_6 = {
    Text = "То, что я делаю, не так уж и много."
  },
  AvgCommunicate_57904_Content_7 = {
    Text = "Я лишь надеюсь, что пациенты санатория смогут обрести хоть немного покоя."
  },
  AvgCommunicate_57904_Content_8 = {
    Text = "Если будет время, пожалуйста, почаще приводите Лили навестить нас."
