  },
  AvgCommunicate_57918_Content_9 = {
    Text = "Трудно поверить, что ты отправляешь такие картинки."
  },
  AvgCommunicate_57918_Option_3 = {
    Text = "Просто удобное средство связи."
  },
  AvgCommunicate_57919_Content_1 = {
    Text = "Страж! Выходи гулять!"
  },
  AvgCommunicate_57919_Content_2 = {
    Text = "Хорошо, а куда хочет пойти Орета?"
  },
  AvgCommunicate_57919_Content_3 = {
    Text = "Друг говорит, что хочет туда, где есть вода!"
  },
  AvgCommunicate_57919_Content_4 = {
    Text = "Вода… Как насчёт пляжа? У меня как раз сегодня выходной."
  },
  AvgCommunicate_57919_Content_5 = {
    Text = "Ура-ура! А можно я позову Дженкина и остальных?"
  },
  AvgCommunicate_57919_Content_6 = {
    Text = "Конечно, встретимся у ворот школы."
  },
  AvgCommunicate_57919_Content_7 = {
    Text = "Отлично! На пляж, на пляж— Выдвигаемся—"
  },
  AvgCommunicate_57919_Option_2 = {
    Text = "Давай!"
  },
  AvgCommunicate_57919_Option_4 = {
    Text = "Вода…"
  },
  AvgCommunicate_57919_Option_6 = {
    Text = "Конечно, встретимся у ворот школы."
  },
  AvgCommunicate_57920_Content_1 = {
    Text = "Ты видел(а)?"
  },
  AvgCommunicate_57920_Content_2 = {
    Text = "В маленьком саду за общежитием появились белые цветы."
  },
  AvgCommunicate_57920_Content_3 = {
    Text = "Они очень красивые."
  },
  AvgCommunicate_57920_Content_4 = {
    Text = "Да, маленькие, крохотные, но такие стойкие…"
  },
  AvgCommunicate_57920_Content_5 = {
    Text = "Как думаешь, мои семена тоже смогут дать такие же цветы?"
  },
  AvgCommunicate_57920_Content_6 = {
    Text = "Конечно смогут!"
  },
  AvgCommunicate_57920_Option_3 = {
    Text = "Они очень красивые."
  },
  AvgCommunicate_57920_Option_6 = {
    Text = "Конечно смогут!"
  },
  AvgCommunicate_57956_Content_1 = {
    Text = "В последнее время меня кое-что беспокоит."
  },
  AvgCommunicate_57956_Content_2 = {
    Text = "Что случилось?"
  },
  AvgCommunicate_57956_Content_3 = {
    Text = "Если не возражаешь, можешь рассказать мне?"
  },
  AvgCommunicate_57956_Content_4 = {
    Text = "Та дама, которая всё время сидит в каком-то странном устройстве и ежедневно пьёт огромное количество тёмной жидкости, уже три дня ночует в моей комнате."
  },
  AvgCommunicate_57956_Content_5 = {
    Text = "Я знаю, что она боится темноты, и понимаю боль того, кто следует за путеводной звездой, но никогда не сможет вернуться на родину, однако…"
  },
  AvgCommunicate_57956_Content_6 = {
    Text = "Она хочет следовать за мной даже в уборную, и это, признаться, немного неловко."
  },
  AvgCommunicate_57956_Content_7 = {
    Text = "Я поговорю с Винкёр."
  },
  AvgCommunicate_57956_Content_8 = {
    Text = "Тогда заранее благодарю."
  },
  AvgCommunicate_57956_Content_9 = {
    Text = "Но, прошу, будь с ней помягче. В конце концов, это не её вина."
  },
  AvgCommunicate_57956_Option_2 = {
    Text = "Что случилось?"
  },
  AvgCommunicate_57956_Option_3 = {
    Text = "Если не возражаешь, можешь рассказать мне?"
  },
  AvgCommunicate_57956_Option_7 = {
    Text = "Я поговорю с Винкёр."
  },
  AvgCommunicate_57957_Content_1 = {
    Text = "Получил(-а) мой Подарок?"
  },
  AvgCommunicate_57957_Content_2 = {
    Text = "Мне стоило догадаться — кроме тебя, никто бы не подарил мне это."
  },
  AvgCommunicate_57957_Content_3 = {
    Text = "Как и любое искусство, скульптура — это нечто очень личное."
  },
  AvgCommunicate_57957_Content_4 = {
    Text = "Не каждый способен, подобно мне, видеть в этих каменных творениях продолжение себя, продолжение жизни."
  },
  AvgCommunicate_57957_Content_5 = {
    Text = "Но ты — другое дело, не так ли?"
  },
  AvgCommunicate_57957_Content_6 = {
    Text = "Моя дорогая «Коралловая дева»?"
  },
  AvgCommunicate_57957_Option_2 = {
    Text = "Мне стоило догадаться."
  },
  AvgCommunicate_57958_Content_1 = {
    Text = "Уважаемый {Male=господин,Female=госпожа}, можно занять немного вашего времени?"
  },
  AvgCommunicate_57958_Content_10 = {
    Text = "Ничего страшного. Ради распространения благодати Господа нашего я не откажусь ни от одной заблудшей души."
  },
  AvgCommunicate_57958_Content_11 = {
    Text = "Завтра в три часа ночи я проведу церемонию в зале Мисагр, дабы поведать миру о великих деяниях Господа нашего."
  },
  AvgCommunicate_57958_Content_12 = {
    Text = "Как человеку, имеющему глубокую связь с Господом нашим, Хранителю тайн {Male=господин,Female=госпожа} надлежит явиться вовремя."
  },
  AvgCommunicate_57958_Content_2 = {
    Text = "Я хотел бы рассказать вам о нашем Юном Короле и Спасителе — Тулу."
  },
  AvgCommunicate_57958_Content_3 = {
    Text = "Прошу главного жреца помнить о своём положении и не использовать подобные уличные агитационные выражения."
  },
  AvgCommunicate_57958_Content_4 = {
    Text = "Юлиетт как-то посоветовала мне: чтобы расширить паству, нужно использовать более мягкие и активные методы проповеди."
  },
  AvgCommunicate_57958_Content_5 = {
    Text = "Полагаю, в её словах есть доля истины."
  },
  AvgCommunicate_57958_Content_6 = {
    Text = "Если это поможет нести благодать Господа нашего, я готова попробовать освоить современные способы общения."
  },
  AvgCommunicate_57958_Content_7 = {
    Text = "Забыл(-а) тебе сказать — на самом деле мне больше нравится Хас…"
  },
  AvgCommunicate_57958_Content_9 = {
    Text = "Кощунство… Невежество…"
  },
  AvgCommunicate_57958_Option_3 = {
    Text = "Займитесь чем-нибудь полезным"
  },
  AvgCommunicate_57958_Option_7 = {
    Text = "Мне больше нравится Хас…"
  },
  AvgCommunicate_57959_Content_1 = {Text = "Эй."},
  AvgCommunicate_57959_Content_10 = {
    Text = "Как будто жалкие людишки способны меня поймать."
  },
  AvgCommunicate_57959_Content_11 = {
    Text = "Забудь, разберусь сама."
  },
  AvgCommunicate_57959_Content_2 = {
    Text = "Хо Фэн у тебя коммуникатор?"
  },
  AvgCommunicate_57959_Content_3 = {
    Text = "Хо Фэн у тебя коммуникатор?"
  },
  AvgCommunicate_57959_Content_4 = {
    Text = "Мисагр — не единственная Огромная Огромная сила, овладевшая технологией серебряного ядра."
  },
  AvgCommunicate_57959_Content_5 = {
    Text = "Так что ты хочешь сказать? Не думаю, что ты связался со мной только ради того, чтобы похвастаться своим коммуникатором."
  },
  AvgCommunicate_57959_Content_6 = {
    Text = "Не такой уж и глупый."
  },
  AvgCommunicate_57959_Content_7 = {
    Text = "Немедленно приходи на Бёрн-стрит, 38. Есть дело."
  },
  AvgCommunicate_57959_Content_8 = {
    Text = "…Какие у тебя дела в полицейском участке?"
  },
  AvgCommunicate_57959_Content_9 = {
    Text = "Тебя что, арестовали?"
  },
  AvgCommunicate_57959_Option_2 = {
    Text = "Во-первых, меня зовут не «эй»."
  },
  AvgCommunicate_57959_Option_3 = {
    Text = "Во-вторых, откуда у тебя коммуникатор?"
  },
  AvgCommunicate_57959_Option_5 = {
    Text = "Что ты хочешь сказать?"
  },
  AvgCommunicate_57959_Option_8 = {
    Text = "…Какие у тебя дела в полицейском участке?"
  },
  AvgCommunicate_57987_Content_1 = {
    Text = "Оказывается, через эту коробочку можно напрямую получать пожелания людей."
  },
  AvgCommunicate_57987_Content_10 = {
    Text = "У людей всегда бывает много желаний."
  },
  AvgCommunicate_57987_Content_11 = {
    Text = "Я сделаю для тебя всё, что в моих силах."
