  AvgCommunicate_57988_Content_13 = {
    Text = "Тут столько всего абсурдного, что даже не знаю, с чего начать!"
  },
  AvgCommunicate_57988_Content_14 = {
    Text = "Хоть и похвально, что ты до сих пор не сдаёшься в этом деле с силой крови, но, может, тебе стоит допустить мысль, что тебя обманывают?"
  },
  AvgCommunicate_57988_Content_15 = {
    Text = "Вот как, значит, даже ты мне не веришь."
