  },
  AvgCommunicate_57990_Content_5 = {
    Text = "Через месяц у меня небольшое выступление в концертном зале Мисагр, и я хотела бы, чтобы кто-нибудь послушал мои песни до этого."
  },
  AvgCommunicate_57990_Content_6 = {
    Text = "Если позвать Фейнт, она в любом случае скажет, что всё хорошо. А другие... других мне как-то неловко просить."
  },
  AvgCommunicate_57990_Content_7 = {
    Text = "Подумав хорошенько, я решила, что Страж Тайн — самый надёжный человек, которому я больше всего доверяю."
  },
  AvgCommunicate_57990_Content_8 = {
