  AvgCommunicate_60943_Content_1 = {
    Text = "Напарник, в этот раз людей не хватает, мне нужно заранее отправиться на передовую позицию для подготовки, так что, боюсь, я не смогу действовать вместе с тобой."
  },
  AvgCommunicate_60943_Content_10 = {
    Text = "Я знаю, ты всегда думаешь обо всех."
  },
  AvgCommunicate_60943_Content_11 = {
    Text = "Но, может, тебе пора научиться спокойно доверять мне свою спину? Напарница."
  },
  AvgCommunicate_60943_Content_13 = {
    Text = "Ты права."
  },
  AvgCommunicate_60943_Content_14 = {
    Text = "Тогда на этот раз я рассчитываю на твою поддержку, напарница."
  },
  AvgCommunicate_60943_Content_2 = {
    Text = "Я написал для тебя несколько вариантов плана действий на случай кризиса. Если возникнет непредвиденная ситуация, можешь свериться с оглавлением."
  },
  AvgCommunicate_60943_Content_3 = {
    Text = "Кроме того, я запросил для тебя дополнительные экстренные духовные сущности. Хоть людей и не хватает, я постараюсь добиться, чтобы кто-нибудь сопровождал тебя."
  },
  AvgCommunicate_60943_Content_4 = {
    Text = "Рамона."
  },
  AvgCommunicate_60943_Content_5 = {
    Text = "Я знаю, что ты за меня переживаешь. Спасибо тебе за всё, что ты для меня делаешь."
  },
  AvgCommunicate_60943_Content_6 = {
    Text = "Но я уже не та слабая и наивная девочка, что пришла сюда в первый день. Я справлюсь."
  },
  AvgCommunicate_60943_Content_7 = {
    Text = "Конечно, я доверяю твоим способностям, просто..."
  },
  AvgCommunicate_60943_Content_8 = {
    Text = "Прости, я привыкла просчитывать всё наперёд. Когда меня нет рядом, я невольно думаю о худшем исходе."
  },
  AvgCommunicate_60943_Content_9 = {
    Text = "Я не могу смириться с тем, что не смогу предотвратить наихудший Конец..."
  },
  AvgCommunicate_60943_Option_10 = {
    Text = "Я знаю, ты всегда думаешь обо всех."
  },
  AvgCommunicate_60943_Option_4 = {
    Text = "Рамона."
  },
  AvgCommunicate_66973_Content_1 = {
