  },
  AvgCommunicate_66973_Content_12 = {
    Text = "Конечно, сестра навсегда останется самым важным для меня человеком, и я тоже буду всегда заботиться о ней."
  },
  AvgCommunicate_66973_Content_13 = {
    Text = "Похоже, на следующих вечеринках настанет моя очередь направлять сестру."
  },
  AvgCommunicate_66973_Content_14 = {
    Text = "Если будет возможность, Страж тоже присоединяйся к игре!"
  },
  AvgCommunicate_66973_Content_15 = {
    Text = "Без проблем!"
  },
  AvgCommunicate_66973_Content_2 = {
    Text = "Не за что! Всегда рада помочь!"
  },
  AvgCommunicate_66973_Content_3 = {
    Text = "Раньше я всегда полагалась на сестру, а она при мне всегда держалась стойко, даже немного жёстко."
  },
  AvgCommunicate_66973_Content_4 = {
    Text = "Не ожидала, что в такой обстановке сестра тоже может растеряться. Я никогда раньше не видела её такой смущённой."
  },
  AvgCommunicate_66973_Content_5 = {
    Text = "Хм? А я думала, Фейнт всегда была такой сдержанной по характеру."
  },
  AvgCommunicate_66973_Content_6 = {
    Text = "Нет, на самом деле у сестры очень сильный характер, и она невероятно решительна!"
  },
  AvgCommunicate_66973_Content_7 = {
    Text = "Когда я была в растерянности и уязвима, именно сестра подсказывала мне, что делать. Она всегда гладила меня по голове и нежно утешала."
  },
  AvgCommunicate_66973_Content_8 = {
    Text = "Вот как, этого я не ожидала."
  },
  AvgCommunicate_66973_Content_9 = {
    Text = "Но теперь нам больше не грозит Рождённый войной за выживание, и сестра наконец-то может заводить друзей на людях."
  },
  AvgCommunicate_66973_Option_11 = {
    Text = "Да, у вас с сестрой действительно очень крепкая связь..."
  },
  AvgCommunicate_66973_Option_15 = {
