  },
  AvgCommunicate_66974_Content_1 = {
    Text = "Голодна."
  },
  AvgCommunicate_66974_Content_10 = {
    Text = "Ну разумеется…"
  },
  AvgCommunicate_66974_Content_11 = {
    Text = "Я голодна!"
  },
  AvgCommunicate_66974_Content_12 = {
    Text = "Ладно, ладно, дай подумать… Может, выпьешь моей крови? Дам глотнуть разок, чтобы утолить жажду."
  },
  AvgCommunicate_66974_Content_13 = {
    Text = "Ты… Правда добрый ко мне."
