  AvgCommunicate_66975_Content_10 = {
    Text = "Ну так это же хорошо."
  },
  AvgCommunicate_66975_Content_11 = {
    Text = "Хмф, Карен тут же стиснула зубы, выложила все свои сбережения, скупила все украшения и нацепила их на себя."
  },
  AvgCommunicate_66975_Content_12 = {
    Text = "М-м… и тебе не тяжело было."
  },
  AvgCommunicate_66975_Content_13 = {
    Text = "А потом, потом, когда Карен пришла прислуживать госпоже Сорель, та лишь взглянула и сказала, что все эти камни — подделки! Фальшивки!!"
