  },
  AvgCommunicate_66975_Content_17 = {
    Text = "По... потому что Карен так любит всё блестящее, что как только появляются деньги, сразу тратит их на блестяшки, поэтому и не удалось много накопить..."
  },
  AvgCommunicate_66975_Content_18 = {
    Text = "Ладно... В любом случае, если тебе просто нравятся блестящие камни, то эти камни действительно достаточно блестящие, а работа достаточно изящная."
  },
  AvgCommunicate_66975_Content_19 = {
    Text = "По сравнению с покупкой настоящих камней ты ещё и сэкономила кучу денег — чего тут расстраиваться?"
  },
  AvgCommunicate_66975_Content_2 = {
    Text = "?? Что случилось?"
  },
  AvgCommunicate_66975_Content_20 = {
    Text = "Ой, а ведь и Правда!"
  },
  AvgCommunicate_66975_Content_21 = {
    Text = "Карен сразу почувствовала, что осталась в выигрыше! Спасибо тебе, Носитель!"
  },
  AvgCommunicate_66975_Content_3 = {
    Text = "Дафодель, эта коварная злодейка! Она выманила все сбережения, которые Карен копила годами тяжёлой работы!"
  },
  AvgCommunicate_66975_Content_4 = {
    Text = "Дафодель обманула тебя? Что ты у неё покупала?"
  },
  AvgCommunicate_66975_Content_5 = {
    Text = "Всё из-за того, что Карен листала журнал и вздыхала, глядя на цены ювелирных украшений, а эта злодейка это заметила."
  },
  AvgCommunicate_66975_Content_6 = {
    Text = "Она сказала Карен, что у неё есть партия украшений с драгоценными камнями по сниженной цене — мол, фасон устаревший и никто не покупает, но они идеально подходят к винтажному шарму Карен…"
  },
  AvgCommunicate_66975_Content_7 = {
