    Text = "Что ты понимаешь! Мои новые рецепты привели тех поваров в полный восторг!"
  },
  AvgCommunicate_66983_Content_13 = {
    Text = "Вчера их уже начали массово выпекать и продавать в столовой, и за ними выстроилась целая очередь!"
  },
  AvgCommunicate_66983_Content_14 = {
    Text = "Так вот, те новые пирожные, которые вчера разобрали в мгновение ока, — это ты их сделала!"
  },
  AvgCommunicate_66983_Content_15 = {
    Text = "Ахахахаха, я крута, да? Давай, назови меня гением!"
  },
  AvgCommunicate_66983_Content_16 = {
    Text = "Гений!"
  },
  AvgCommunicate_66983_Content_17 = {
    Text = "Хотя я вдруг поняла, что пирожные, сделанные своими руками, кажутся ещё вкуснее. Пожалуй, и дальше так буду делать — неплохо ведь."
  },
  AvgCommunicate_66983_Content_18 = {
    Text = "Как приятно — даже наша барышня наконец-то познала радость труда."
  },
  AvgCommunicate_66983_Content_2 = {
    Text = "Что я слышу?! Что за Удар тебя постиг??"
  },
  AvgCommunicate_66983_Content_3 = {
    Text = "Какой ещё Удар, у меня всё прекрасно!"
  },
  AvgCommunicate_66983_Content_4 = {
    Text = "Тогда в чём дело?"
  },
  AvgCommunicate_66983_Content_5 = {
    Text = "Эх, просто мне уже надоели пирожные из столовой, а эти повара — пустоголовые, даже не думают выпускать что-нибудь новенькое!"
  },
  AvgCommunicate_66983_Content_6 = {
    Text = "Действительно, никто не нуждается в пирожных так сильно, как ты…"
  },
  AvgCommunicate_66983_Content_7 = {
    Text = "Это всё потому, что они такие бестолковые! Поэтому я ворвалась на кухню и заставила их научить меня делать пирожные."
  },
  AvgCommunicate_66983_Content_8 = {
    Text = "А? Ты — и на кухню?"
  },
  AvgCommunicate_66983_Content_9 = {
    Text = "Не ожидал, да? А потом я обнаружила, что делать пирожные совсем не так уж сложно! У меня просто врождённый талант!"
  },
  AvgCommunicate_66983_Option_11 = {
    Text = "Вот это и есть главное, да! Не слипнется от такого количества?"
  },
  AvgCommunicate_66983_Option_14 = {
    Text = "Так вот, те новые пирожные, которые вчера разобрали в мгновение ока, — это ты их сделала!"
  },
  AvgCommunicate_66983_Option_16 = {
    Text = "Гений!"
  },
  AvgCommunicate_66983_Option_18 = {
    Text = "Как приятно — даже наша барышня наконец-то познала радость труда."
  },
  AvgCommunicate_66983_Option_2 = {
    Text = "Что я слышу?! Что за Удар тебя постиг??"
  },
  AvgCommunicate_66983_Option_4 = {
    Text = "Тогда в чём дело?"
  },
  AvgCommunicate_66983_Option_6 = {
    Text = "Действительно, никто не нуждается в пирожных так сильно, как ты…"
  },
  AvgCommunicate_66983_Option_8 = {
    Text = "А? Ты — и на кухню?"
  },
  AvgCommunicate_66984_Content_1 = {
    Text = "%player%{Male=господин,Female=госпожа}, у меня возникла небольшая проблема, и я хотела бы попросить тебя о помощи."
  },
  AvgCommunicate_66984_Content_10 = {
    Text = "Но в ответе я написала, что у меня уже есть партнёр для танцев."
  },
  AvgCommunicate_66984_Content_11 = {
    Text = "На самом деле, я только сейчас пришла искать своего милого партнёра."
  },
  AvgCommunicate_66984_Content_12 = {
    Text = "Думаю, {Male=он,Female=она} не позволит мне отправиться на бал в одиночестве, Правда?"
  },
  AvgCommunicate_66984_Content_13 = {
    Text = "Что скажешь?"
  },
  AvgCommunicate_66984_Content_14 = {
    Text = "Для меня это честь, госпожа."
  },
  AvgCommunicate_66984_Content_15 = {
    Text = "Похоже, мне нужно срочно подучить танцевальные па и этикет, чтобы не наступить госпоже на ногу."
  },
  AvgCommunicate_66984_Content_16 = {
    Text = "Ты всегда такой надёжный и заботливый, мой рыцарь."
  },
  AvgCommunicate_66984_Content_2 = {
    Text = "Что же поставило в Тупик нашу госпожу Сорейль?"
  },
  AvgCommunicate_66984_Content_3 = {
    Text = "Я весь внимание."
  },
  AvgCommunicate_66984_Content_4 = {
    Text = "Через несколько дней мне нужно идти на вечерний бал — ну, ты понимаешь, из тех, где кучка чопорных и жеманных людей собирается вместе от нечего делать."
  },
  AvgCommunicate_66984_Content_5 = {
    Text = "Досадно то, что в последнее время один совершенно бесцеремонный тип не даёт мне покоя. Он тоже будет на том балу и уже громогласно пригласил меня стать его партнёршей по танцам."
  },
  AvgCommunicate_66984_Content_6 = {
    Text = "Какой неприятный человек. Хотите, я разберусь с ним для вас, госпожа?"
  },
  AvgCommunicate_66984_Content_7 = {
    Text = "Хе-хе-хе, ты всё лучше и лучше шутишь."
  },
  AvgCommunicate_66984_Content_8 = {
    Text = "К сожалению, сейчас это невозможно — мир взрослых так устроен. Впрочем, я уже отклонила его Приглашение."
  },
  AvgCommunicate_66984_Content_9 = {
    Text = "Тогда разве проблема не решена?"
  },
  AvgCommunicate_66984_Option_14 = {
    Text = "Для меня это честь, госпожа."
  },
  AvgCommunicate_66984_Option_2 = {
    Text = "Что же поставило в Тупик нашу госпожу Сорейль?"
  },
  AvgCommunicate_66984_Option_3 = {
    Text = "Я весь внимание."
  },
  AvgCommunicate_66984_Option_6 = {
    Text = "Какой неприятный человек. Хотите, я разберусь с ним для вас, госпожа?"
  },
  AvgCommunicate_66984_Option_9 = {
    Text = "Тогда разве проблема не решена?"
  },
  AvgCommunicate_66985_Content_1 = {
    Text = "Мой маленький рыцарь, благодаря твоей помощи на том балу я наконец-то избавилась от того назойливого человека."
  },
  AvgCommunicate_66985_Content_10 = {
    Text = "Загадать желание? Тогда я загадываю роскошный ужин при свечах наедине с прекрасной леди Сорель."
  },
  AvgCommunicate_66985_Content_11 = {
    Text = "Только ты и я, без необходимости общаться с кем-либо ещё."
  },
  AvgCommunicate_66985_Content_12 = {
    Text = "Как пожелаете, хитрый маленький плутишка."
  },
  AvgCommunicate_66985_Content_13 = {
    Text = "Что бы вы хотели попробовать? Расскажите, я составлю вам компанию за трапезой."
  },
  AvgCommunicate_66985_Content_14 = {
    Text = "Это настоящее испытание для воображения человека, который каждый день ест в столовой. Тогда позвольте мне попробовать то, что вы любите больше всего, госпожа."
  },
  AvgCommunicate_66985_Content_15 = {
    Text = "Хе-хе, какой умелый льстец."
  },
  AvgCommunicate_66985_Content_16 = {
    Text = "Тогда я буду ждать вашего визита в моей резиденции."
  },
  AvgCommunicate_66985_Content_2 = {
    Text = "В благодарность за твою отзывчивость и щедрость я хотела бы сделать для тебя что-нибудь в знак моей признательности."
  },
  AvgCommunicate_66985_Content_3 = {
    Text = "Вы слишком любезны, леди Сорель. Я думал, наши отношения уже не требуют подобных благодарностей."
  },
  AvgCommunicate_66985_Content_4 = {
    Text = "Я и Правда не люблю выражать благодарность на словах — в большинстве случаев это лишь лицемерная вежливость."
  },
  AvgCommunicate_66985_Content_5 = {
    Text = "Однако... возможность попросить у меня что угодно — неужели тебе совсем не интересно?"
  },
  AvgCommunicate_66985_Content_6 = {
    Text = "Ого, любая просьба? Если бы те благородные господа об этом услышали, они бы умерли от зависти."
  },
  AvgCommunicate_66985_Content_7 = {
    Text = "Ты всегда заслуживаешь от меня особого отношения."
  },
  AvgCommunicate_66985_Content_8 = {
    Text = "Вот это задачка, так сложно выбрать... А если набраться наглости и попросить особняк, школа не узнает?.."
  },
  AvgCommunicate_66985_Content_9 = {
    Text = "Не беспокойся, я всё улажу. Можешь смело загадывать желание."
  },
  AvgCommunicate_66985_Option_10 = {
    Text = "Загадать желание?"
  },
  AvgCommunicate_66985_Option_14 = {
    Text = "Тогда позвольте мне попробовать то, что вы любите больше всего."
  },
  AvgCommunicate_66985_Option_3 = {
    Text = "Вы слишком любезны, леди Сорель."
  },
  AvgCommunicate_66985_Option_6 = {
    Text = "Ого, любая просьба?"
  },
  AvgCommunicate_66985_Option_8 = {
    Text = "Вот это задачка..."
  },
  AvgCommunicate_66986_Content_1 = {
    Text = "Мы с Лотан только что провели бой. Ничья."
  },
  AvgCommunicate_66986_Content_10 = {
    Text = "Ахаха... Думаю, у меня не так уж много лишних мыслей, так что пока воздержусь..."
  },
  AvgCommunicate_66986_Content_11 = {
    Text = "Тогда ты тоже сильный."
  },
  AvgCommunicate_66986_Content_12 = {
    Text = "Жаль только, что у того водопада всё время кто-то рыбачит — шумно."
  },
  AvgCommunicate_66986_Content_13 = {
    Text = "Однажды я вышла из-под водопада, чтобы попросить его вести себя потише, а он с перепугу швырнул мне рыбу в лицо и убежал."
  },
  AvgCommunicate_66986_Content_14 = {
    Text = "Интересно, придёт ли он в следующий раз."
  },
  AvgCommunicate_66986_Content_15 = {
    Text = "Хм... Думаю, скорее всего нет..."
  },
  AvgCommunicate_66986_Content_2 = {
    Text = "Что у вас случилось?"
  },
  AvgCommunicate_66986_Content_3 = {
    Text = "Вы не поссорились?"
  },
  AvgCommunicate_66986_Content_4 = {
    Text = "Нет, просто спарринг между воинами."
  },
  AvgCommunicate_66986_Content_5 = {
    Text = "Раньше она говорила, что мой стиль боя недостаточно чист. Кажется, теперь я понимаю, что она имела в виду."
  },
  AvgCommunicate_66986_Content_6 = {
    Text = "Я нашла способ стать чище. Теперь я стала сильнее."
  },
  AvgCommunicate_66986_Content_7 = {
    Text = "Это хорошо, но что за способ стать чище?"
  },
  AvgCommunicate_66986_Content_8 = {
    Text = "Встать под водопад и позволить потоку воды смыть все лишние мысли."
  },
  AvgCommunicate_66986_Content_9 = {
    Text = "Очень помогает. Хочешь пойти со мной?"
  },
  AvgCommunicate_66986_Option_10 = {
    Text = "Ахаха... Думаю, у меня не так уж много лишних мыслей, так что пока воздержусь..."
  },
  AvgCommunicate_66986_Option_15 = {
    Text = "Хм... Думаю, скорее всего нет..."
  },
  AvgCommunicate_66986_Option_2 = {
    Text = "Что у вас случилось?"
  },
  AvgCommunicate_66986_Option_3 = {
    Text = "Вы не поссорились?"
  },
  AvgCommunicate_66986_Option_7 = {
    Text = "Это хорошо, но что за способ стать чище?"
  },
  AvgCommunicate_66987_Content_1 = {
    Text = "Страж, ты знаешь какие-нибудь рецепты из рыбы?"
  },
  AvgCommunicate_66987_Content_10 = {
    Text = "Какая добрая и милая старушка."
  },
  AvgCommunicate_66987_Content_11 = {
    Text = "Да, поэтому я тоже хочу научиться готовить рыбу. В следующий раз я приготовлю для неё сама."
  },
  AvgCommunicate_66987_Content_12 = {
    Text = "Как трогательно! Обязательно приготовь! Я прямо сейчас пойду выпытаю рецепт у повара в столовой!"
  },
  AvgCommunicate_66987_Content_13 = {
    Text = "Спасибо."
  },
  AvgCommunicate_66987_Content_2 = {
    Text = "Рецепты?? Ты собираешься готовить?"
  },
  AvgCommunicate_66987_Content_3 = {
    Text = "Ну, в прошлый раз я напугала рыбака, и после этого у водопада долго было тихо."
  },
  AvgCommunicate_66987_Content_4 = {
    Text = "Недавно сюда стала приходить одна старушка — рыбачить. Она никогда не шумела, поэтому я и не показывалась."
  },
  AvgCommunicate_66987_Content_5 = {
    Text = "Однажды она развела костёр и стала жарить пойманную рыбу."
  },
  AvgCommunicate_66987_Content_6 = {
    Text = "Запах был такой вкусный, что мой живот издал звук, и она меня заметила."
  },
  AvgCommunicate_66987_Content_7 = {
    Text = "А? Она тоже испугалась тебя?"
  },
  AvgCommunicate_66987_Content_8 = {
    Text = "Нет, она пригласила меня разделить с ней жареную рыбу. Было очень вкусно."
  },
  AvgCommunicate_66987_Content_9 = {
    Text = "А потом она стала приходить на рыбалку с маленькой кастрюлькой, варить уху и делиться со мной."
  },
  AvgCommunicate_66987_Option_10 = {
    Text = "Какая добрая и милая старушка."
  },
  AvgCommunicate_66987_Option_12 = {
    Text = "Как трогательно! Обязательно приготовь! Я прямо сейчас пойду выпытаю рецепт у повара в столовой!"
  },
  AvgCommunicate_66987_Option_2 = {
    Text = "Рецепты?? Ты собираешься готовить?"
  },
  AvgCommunicate_66987_Option_7 = {
    Text = "А? Она тоже испугалась тебя?"
  },
  AvgCommunicate_66988_Content_1 = {
    Text = "Недавно снова заработал кругленькую сумму, но чуть не погиб. Хорошо, что богиня удачи всегда на моей стороне."
  },
  AvgCommunicate_66988_Content_10 = {
    Text = "Но когда мы начали драться, сработавшая ловушка случайно попала в него самого."
  },
  AvgCommunicate_66988_Content_11 = {Text = "А?"},
  AvgCommunicate_66988_Content_12 = {
    Text = "Я ещё и оказала ему экстренную помощь, остановила кровотечение — только так удалось доставить его в полицию живым."
  },
  AvgCommunicate_66988_Content_13 = {
    Text = "Полиция выплатила мне премию, а преступник снова оказался в тюрьме. Говорят, ему теперь заменят срок на пожизненный."
  },
  AvgCommunicate_66988_Content_14 = {
    Text = "Ему оставалось всего несколько лет до освобождения, зачем же было творить такие глупости, эх…"
  },
  AvgCommunicate_66988_Content_15 = {
    Text = "Даже не знаю, кому из вас двоих не повезло больше…"
  },
  AvgCommunicate_66988_Content_16 = {
    Text = "Хотя, погоди, я вроде помню, что вчера за тобой гнались люди из игорного дома, требуя вернуть долг. А куда делась твоя премия?"
  },
  AvgCommunicate_66988_Content_17 = {
    Text = "А-ха-ха… Всё-таки моя удача тоже не бесконечна. Если потратить её заранее, то за игорным столом неизбежно случаются промахи…"
  },
  AvgCommunicate_66988_Content_18 = {
    Text = "Знаешь, после этого на душе как-то сразу полегчало."
  },
  AvgCommunicate_66988_Content_2 = {
    Text = "Что случилось??"
  },
  AvgCommunicate_66988_Content_3 = {
    Text = "Ну, ты же знаешь, я обычно беру на стороне детективные заказы. Из-за слишком высокого процента раскрываемости я всегда очень востребована."
  },
  AvgCommunicate_66988_Content_4 = {
    Text = "Но, с другой стороны, те преступники, которых я отправила за решётку, скрежещут зубами от ненависти ко мне."
  },
  AvgCommunicate_66988_Content_5 = {
    Text = "Ну, они и Правда проигрывают совершенно необъяснимым образом."
  },
  AvgCommunicate_66988_Content_6 = {
    Text = "Пару дней назад один преступник сбежал из тюрьмы, пришёл в игорный дом, куда я часто хожу, и караулил меня там несколько дней, пока наконец не дождался."
  },
  AvgCommunicate_66988_Content_7 = {
    Text = "Он пришёл тебе отомстить?!"
  },
  AvgCommunicate_66988_Content_8 = {
    Text = "Именно. Он долго следил за мной и в конце концов загнал меня в переулок."
  },
  AvgCommunicate_66988_Content_9 = {
    Text = "Он заранее расставил в переулке ловушки, чтобы покончить со мной."
  },
  AvgCommunicate_66988_Option_11 = {Text = "А?"},
  AvgCommunicate_66988_Option_15 = {
    Text = "Даже не знаю, кому из вас двоих не повезло больше…"
  },
  AvgCommunicate_66988_Option_18 = {
    Text = "Знаешь, после этого на душе как-то сразу полегчало."
  },
  AvgCommunicate_66988_Option_2 = {
    Text = "Что случилось??"
  },
  AvgCommunicate_66988_Option_5 = {
    Text = "Ну, они и Правда проигрывают совершенно необъяснимым образом."
  },
  AvgCommunicate_66988_Option_7 = {
    Text = "Он пришёл тебе отомстить?!"
  },
  AvgCommunicate_66989_Content_1 = {
    Text = "Страж, я подготовила ответы на твои вопросы о протоколах кризисного реагирования для следователей."
  },
  AvgCommunicate_66989_Content_10 = {
    Text = "Пусть я и отношусь к твоим просьбам с большим вниманием, чем та Рамона, но ты забыла — я тоже когда-то была ею."
  },
  AvgCommunicate_66989_Content_11 = {
    Text = "Если хочешь меня обмануть, тебе ещё тренироваться и тренироваться."
  },
  AvgCommunicate_66989_Content_12 = {
    Text = "Эх… Мою искренность в итоге не оценили!"
  },
  AvgCommunicate_66989_Content_13 = {
    Text = "Так что насчёт того задания, ой, то есть того вопроса — может, хоть немного объяснишь ход решения?"
  },
  AvgCommunicate_66989_Content_14 = {
    Text = "Рамона?"
  },
  AvgCommunicate_66989_Content_15 = {
    Text = "Рамона—"
  },
  AvgCommunicate_66989_Content_2 = {
    Text = "Отлично! Я знала, что на тебя можно положиться!"
  },
  AvgCommunicate_66989_Content_3 = {
    Text = "Спасибо, но с такими вопросами можно было обратиться к Рамоне из твоего мира — она бы тоже помогла. Почему ты пришла ко мне?"
  },
  AvgCommunicate_66989_Content_4 = {
