  AvgCommunicate_67006_Content_1 = {
    Text = "Мы заметили, что так называемый технический прогресс и развитие торговли в нынешнюю эпоху по-прежнему скучны, однако в области подушек появилось немало новшеств."
  },
  AvgCommunicate_67006_Content_10 = {
    Text = "Продавец вцепился в нас и заявил, что мы — прирождённый тестировщик сна, и непременно хотел, чтобы мы постоянно тестировали для них подушки."
