  },
  AvgCommunicate_67019_Content_7 = {
    Text = "Но не беспокойся, у меня богатый опыт проведения месс, и я в состоянии справиться с этими хлопотами."
  },
  AvgCommunicate_67019_Content_8 = {
    Text = "Даже с богатым опытом у тебя всего две руки. Если можно, позволь мне заранее прийти и помочь тебе!"
  },
  AvgCommunicate_67019_Content_9 = {
    Text = "Всё-таки для столь грандиозного мероприятия подготовка должна быть как можно более тщательной."
  },
  AvgCommunicate_67019_Option_12 = {
    Text = "Без проблем, до встречи!"
  },
  AvgCommunicate_67019_Option_4 = {
    Text = "С удовольствием!"
  },
  AvgCommunicate_67019_Option_8 = {
    Text = "Если можно, позволь мне заранее прийти и помочь тебе!"
  },
  AvgCommunicate_67020_Content_1 = {
    Text = "Эх, с тех пор как Мисагер издала ограничительный приказ, ни одна милашка больше не приходит поболтать со мной."
  },
  AvgCommunicate_67020_Content_10 = {
    Text = "Ладно, тогда мне остаётся лишь молиться, чтобы солнце поскорее село."
  },
  AvgCommunicate_67020_Content_11 = {
    Text = "Ах, уже предвкушаю сегодняшний лунный Погоня за светом."
  },
  AvgCommunicate_67020_Content_2 = {
    Text = "Говорят, без твоего сопровождения никому нельзя со мной встречаться."
  },
  AvgCommunicate_67020_Content_3 = {
    Text = "Ну ты и ну, скажи-ка, это ведь ты приревновал и нажаловался в школу?"
  },
  AvgCommunicate_67020_Content_4 = {
    Text = "Это ведь ты первая соблазняла учеников пить странные напитки…"
  },
  AvgCommunicate_67020_Content_5 = {
    Text = "Это был дар любви! Неужели в твоих глазах я настолько низка?"
  },
  AvgCommunicate_67020_Content_6 = {
    Text = "Каждый день я жду тебя в одиночестве, а ты, оказывается, так обо мне думаешь…"
  },
  AvgCommunicate_67020_Content_7 = {
    Text = "Стой! Я понял, я буду чаще приходить к тебе."
  },
  AvgCommunicate_67020_Content_8 = {
    Text = "Какой понимающий ребёнок. Но я хочу видеть тебя каждое мгновение — прямо сейчас хочу, ни минуты ждать не желаю."
  },
  AvgCommunicate_67020_Content_9 = {
    Text = "Сегодня вечером, я приду сегодня вечером, ладно?!"
  },
  AvgCommunicate_67020_Option_4 = {
    Text = "Это ведь ты первая соблазняла учеников пить странные напитки…"
  },
  AvgCommunicate_67020_Option_7 = {
