  },
  AvgCommunicate_67020_Option_9 = {
    Text = "Сегодня вечером, я приду сегодня вечером, ладно?!"
  },
  AvgCommunicate_67021_Content_1 = {
    Text = "Страж, прошу прощения за Беспокойство. Скажи, у тебя в ближайшее время найдётся свободное время?"
  },
  AvgCommunicate_67021_Content_10 = {
