  AvgCommunicate_67021_Content_3 = {
    Text = "Дело в том, что скоро в Лондиниуме пройдёт поэтическая ярмарка. Там будут продаваться множество новых и старых книг, а также соберутся поэты для обмена опытом."
  },
  AvgCommunicate_67021_Content_4 = {
    Text = "Организаторы также пригласили меня выставить свой стенд, чтобы поделиться своим сборником стихов."
