  AvgCommunicate_67022_Content_3 = {
    Text = "Я разработала специальную сферу для сна, которая ночью поддерживает постоянное освещение внутри. Так не нужен мощный Погоня за светом, и при этом вокруг не останется ни одного тёмного угла."
  },
  AvgCommunicate_67022_Content_4 = {
    Text = "Звучит неплохо — наконец-то тебе не придётся каждый день вламываться в чужие комнаты, а потом быть выставленной за Ворота."
  },
  AvgCommunicate_67022_Content_5 = {
    Text = "Нет! Чтобы предотвратить любые неполадки сферы для сна и избежать внешних опасностей, мне нужно разместить её в помещении, где есть люди."
