  AvgCommunicate_67022_Content_7 = {
    Text = "Именно! Я передам кнопку аварийной перезагрузки сферы для сна человеку, которому доверяю, и тогда всё будет абсолютно надёжно!"
  },
  AvgCommunicate_67022_Content_8 = {
    Text = "К тому же моя привычка спать при свете больше не будет мешать другим. Просто идеально!"
