  AvgCommunicate_67025_Content_10 = {
    Text = "Обязательно оставьте мне одно место!!!"
  },
  AvgCommunicate_67025_Content_2 = {
    Text = "Даже те ученики, которые раньше не участвовали в физических тренировках, стали записываться на занятия. Энтузиазм всех меня по-настоящему удивляет."
