  AvgCommunicate_67025_Content_4 = {
    Text = "Действительно, чтобы щенки и ученики лучше сработались Близкий Близкий друг с другом, я выбирала ещё не достигших зрелости щенков."
  },
  AvgCommunicate_67025_Content_5 = {
    Text = "Хотя я, как и все, обожаю этих малышей, но щенки требуют гораздо больше ухода и обучения, чем взрослые собаки."
