  AvgCommunicate_67025_Content_6 = {
    Text = "Теперь число записавшихся растёт, соответственно нужно больше щенков, и мне уже сложно справляться одной."
  },
  AvgCommunicate_67025_Content_7 = {
    Text = "Это проще простого — стоит инструктору Эльве только объявить набор, и желающих ухаживать за щенками будет хоть отбавляй. Боюсь, щенков на всех не хватит."
  },
  AvgCommunicate_67025_Content_8 = {
    Text = "Ты предлагаешь набрать добровольцев? Это действительно хорошая идея."
  },
  AvgCommunicate_67025_Content_9 = {
    Text = "Тогда я сейчас пойду к ректору Хёллерту и подам заявку. Если всё пройдёт гладко, ученики смогут увидеть ещё больше щенков."
