  },
  AvgCommunicate_67026_Content_6 = {
    Text = "На этот счёт у меня есть идея: если мы включим в тренировки работу со служебными собаками, может, у всех появится больше мотивации?"
  },
  AvgCommunicate_67026_Content_7 = {
    Text = "Служебные собаки? То есть на занятиях будут собачки?"
  },
  AvgCommunicate_67026_Content_8 = {
    Text = "Да, на самом деле это распространённый метод в армии — присутствие служебных собак значительно снижает стресс у солдат."
  },
  AvgCommunicate_67026_Content_9 = {
    Text = "С пушистыми собачками рядом — это же настоящее счастье!"
  },
  AvgCommunicate_67026_Option_11 = {
    Text = "Какие же они молодцы, эти собачки."
  },
  AvgCommunicate_67026_Option_13 = {
    Text = "Инструктор Эльва! Я согласен!"
  },
  AvgCommunicate_67026_Option_2 = {
    Text = "Предложение — тренировки отличные, в следующий раз лучше не проводить…"
  },
  AvgCommunicate_67026_Option_4 = {
    Text = "Шучу, просто физподготовка слишком скучная, совсем нет мотивации…"
  },
  AvgCommunicate_67026_Option_7 = {
    Text = "Служебные собаки? То есть на занятиях будут собачки?"
  },
  AvgCommunicate_67026_Option_9 = {
    Text = "С пушистыми собачками рядом — это же настоящее счастье!"
  },
  AvgCommunicate_67027_Content_1 = {
    Text = "Страж, почему Граждане Мицагара больше не приходят ко мне загадывать желания?"
  },
  AvgCommunicate_67027_Content_10 = {
    Text = "Это скорее не загадывание желаний, а надежда получить частичку удачи и благословения."
  },
  AvgCommunicate_67027_Content_11 = {
    Text = "Желание — это такая вещь, которая, даже если не может исполниться сразу, остаётся в сердце как утешение и надежда."
  },
  AvgCommunicate_67027_Content_12 = {
    Text = "Желания, которые не могут исполниться сразу… тоже настолько ценны?"
  },
  AvgCommunicate_67027_Content_13 = {
    Text = "Кажется, я поняла. С завтрашнего дня я буду дарить всем благословения у школьного фонтана."
  },
  AvgCommunicate_67027_Content_14 = {
    Text = "Подожди, почему именно у школьного фонтана?"
  },
  AvgCommunicate_67027_Content_15 = {
    Text = "Я слышала, что во многих местах популярны фонтаны желаний. Так что если я превращу школьный фонтан в фонтан желаний, все смогут приходить за благословениями."
  },
  AvgCommunicate_67027_Content_16 = {
    Text = "Вроде бы логично, но всё равно как-то странно!"
  },
  AvgCommunicate_67027_Content_2 = {
    Text = "Хм… Наверное, потому что Граждане Мицагара — люди практичные."
  },
  AvgCommunicate_67027_Content_3 = {
    Text = "Ежедневно сталкиваясь с бесчисленными опасностями, они закалили свой дух и больше не полагаются на загадывание желаний для решения проблем."
  },
  AvgCommunicate_67027_Content_4 = {
    Text = "…Похоже, я всё-таки слишком бесполезна."
  },
  AvgCommunicate_67027_Content_5 = {
    Text = "Нет-нет! На самом деле, все не то чтобы совсем в это не верят."
  },
  AvgCommunicate_67027_Content_6 = {
    Text = "Если речь идёт о чём-то абстрактном, о долгосрочных мечтах — люди всё ещё с удовольствием загадывают желания за компанию."
  },
  AvgCommunicate_67027_Content_7 = {
    Text = "Правда?"
  },
  AvgCommunicate_67027_Content_8 = {
    Text = "Я не совсем понимаю, что такое абстрактные, долгосрочные желания?"
  },
  AvgCommunicate_67027_Content_9 = {
    Text = "Ну, например, «сдать все экзамены», «привлечь удачу в деньгах», «найти сладкую любовь» и тому подобное."
  },
  AvgCommunicate_67027_Option_14 = {
