  },
  AvgCommunicate_67028_Content_1 = {
    Text = "Страж {Male=господин,Female=госпожа}, давно не виделись, простите за Беспокойство."
  },
  AvgCommunicate_67028_Content_10 = {
    Text = "Замечательно, я выберу удобное для вас время и нанесу визит."
