  AvgCommunicate_67028_Content_2 = {
    Text = "Недавно мне случайно достались две красивые красные золотые рыбки."
  },
  AvgCommunicate_67028_Content_3 = {
    Text = "К счастью, благодаря моему уходу они успешно отложили немало икринок, и теперь из них уже вылупилось множество мальков."
  },
  AvgCommunicate_67028_Content_4 = {
