  AvgCommunicate_67028_Content_6 = {
    Text = "Рыбы в воде, водоросли и кораллы — в моих воспоминаниях это очень тёплое, родное место, словно дом."
  },
  AvgCommunicate_67028_Content_7 = {
    Text = "Простите, я отвлеклась от темы. Я хотела спросить — не хотите ли вы завести несколько маленьких золотых рыбок?"
