  AvgCommunicate_67029_Content_1 = {
    Text = "Ой, Страж Тайн, ты меня искал?"
  },
  AvgCommunicate_67029_Content_10 = {
    Text = "Поэтому Кассия придумала отличный способ — начать исследования с животных! Так гораздо проще!"
  },
  AvgCommunicate_67029_Content_11 = {
    Text = "…И где сейчас те куры?"
  },
  AvgCommunicate_67029_Content_12 = {
    Text = "В комнате Кассии! Уже вылупилось много цыплят! Каждый день там так весело и шумно!"
  },
  AvgCommunicate_67029_Content_13 = {
    Text = "Немедленно верни их в столовую!!"
  },
  AvgCommunicate_67029_Content_14 = {
    Text = "Ой, ты что, хочешь жестоко разлучить Матушка с детьми? Как бессердечно! У тебя совсем нет материнских чувств!"
  },
  AvgCommunicate_67029_Content_15 = {
    Text = "С чего бы мне испытывать материнские чувства к курам?!"
  },
  AvgCommunicate_67029_Content_16 = {
    Text = "И уж от кого-кого, но от тебя слышать слово «бессердечно» — это последнее, чего я хочу!"
  },
  AvgCommunicate_67029_Content_2 = {
    Text = "Именно, Кассия. Мне сообщили, что после твоего импровизированного магического представления вчера в школьной столовой из кладовой пропали три курицы и двадцать яиц."
  },
  AvgCommunicate_67029_Content_3 = {
    Text = "Что? Разве такое было? Кассия ничего об этом не знает!"
  },
  AvgCommunicate_67029_Content_4 = {
    Text = "Хватит прикидываться! Все видели, как ты наколдовала несколько куриц!"
  },
  AvgCommunicate_67029_Content_5 = {
    Text = "Ой, кажется, и Правда! Может, те курицы сами улетели?"
  },
  AvgCommunicate_67029_Content_6 = {
    Text = "Возможно, они заблудились в бесконечном мире шляп — как же их жалко!"
  },
  AvgCommunicate_67029_Content_7 = {
    Text = "Если ты не начнёшь говорить правду, мне придётся связаться с госпожой Дафдель, чтобы она разобралась со своей сотрудницей."
  },
  AvgCommunicate_67029_Content_8 = {
    Text = "Ладно-ладно, совсем нет чувства юмора!"
  },
  AvgCommunicate_67029_Content_9 = {
    Text = "Просто Кассия в последнее время изучает чувство «материнской любви», но среди пробуждённых в школе слишком мало подходящих примеров!"
  },
