  },
  AvgCommunicate_67030_Content_12 = {
    Text = "Стой, хватит мучить людей!!!"
  },
  AvgCommunicate_67030_Content_2 = {
    Text = "Когда я в прошлый раз торговала ими в кампусе, Мёрфи даже выплюнула их на землю! Если бы я не убежала вовремя, она бы меня ещё и побила!"
