  AvgCommunicate_67032_Content_1 = {
    Text = "Пёсик, в Чёрном Омуте так холодно, я каждый день чувствую, как утекают жизненные силы."
  },
  AvgCommunicate_67032_Content_10 = {
    Text = "А что, если я скажу, что уже немного расшатала устройство, которое меня удерживает?"
  },
  AvgCommunicate_67032_Content_11 = {
    Text = "?! Я сейчас же иду к тебе."
  },
  AvgCommunicate_67032_Content_2 = {
    Text = "Если ты так и не придёшь меня навестить, в один прекрасный день я, может, растворюсь в коррозийной жиже и исчезну."
