  AvgCommunicate_67032_Content_3 = {
    Text = "…Я больше не поведусь на твои уловки."
  },
  AvgCommunicate_67032_Content_4 = {
    Text = "Разве забота о наставнике — это не само собой разумеющееся? Как это можно назвать уловкой?"
  },
  AvgCommunicate_67032_Content_5 = {
    Text = "Я всё ещё скучаю по тому, как ты раньше ленился на занятиях и боялся, что я это замечу."
  },
  AvgCommunicate_67032_Content_6 = {
    Text = "И когда ты пришёл меня арестовывать — это праведное и наивное личико тоже было очень милым."
  },
  AvgCommunicate_67032_Content_7 = {
    Text = "Если ты закончил(а), я выключаю коммуникатор."
  },
  AvgCommunicate_67032_Content_8 = {
    Text = "Эх, какая холодность… Неужели ты ни за что не согласишься со мной встретиться?"
  },
  AvgCommunicate_67032_Content_9 = {
    Text = "Как думаешь?"
  },
  AvgCommunicate_67032_Option_11 = {
    Text = "?! Я сейчас же иду к тебе."
  },
  AvgCommunicate_67032_Option_3 = {
    Text = "…Я больше не поведусь на твои уловки."
  },
  AvgCommunicate_67032_Option_7 = {
    Text = "Если ты закончил(а), я выключаю коммуникатор."
  },
  AvgCommunicate_67032_Option_9 = {
    Text = "Как думаешь?"
  },
  AvgCommunicate_67033_Content_1 = {
    Text = "Ватсон, жизнь — такая скука."
  },
  AvgCommunicate_67033_Content_10 = {
    Text = "Только не говори, что ты ему проиграла?"
  },
  AvgCommunicate_67033_Content_11 = {
    Text = "Нет, этого не было. Никто из нас не хотел уступать, ставки росли всё больше и больше, мы оба уже были на взводе."
  },
  AvgCommunicate_67033_Content_12 = {
    Text = "В итоге тот старик от волнения допустил промах, и я обнаружила, что он всё это время жульничал."
  },
  AvgCommunicate_67033_Content_13 = {
    Text = "То есть ты всё это время играла вничью с шулером?"
  },
  AvgCommunicate_67033_Content_14 = {
    Text = "Ага, я была так разочарована. А ещё хуже то, что старик пришёл в ярость от стыда и набросился на меня с кулаками."
  },
  AvgCommunicate_67033_Content_15 = {
    Text = "Он заподозрил, что я, как и он, тоже шулер! Какое оскорбление!"
  },
  AvgCommunicate_67033_Content_16 = {
    Text = "В итоге нас обоих вышвырнули из игорного дома. Я так ударилась, что до сих пор больно сидеть. Вот невезение…"
  },
  AvgCommunicate_67033_Content_17 = {
    Text = "Не знаю почему, но сочувствия как-то не возникает…"
  },
  AvgCommunicate_67033_Content_2 = {
    Text = "? Ты опять ходил играть в азартные игры? Снова всех обчистил до нитки?"
  },
  AvgCommunicate_67033_Content_3 = {
    Text = "На этот раз Правда нет! Я просто, как обычно, пошёл в игорный дом развлечься… кхм."
  },
  AvgCommunicate_67033_Content_4 = {
    Text = "Ничего, продолжай."
  },
  AvgCommunicate_67033_Content_5 = {
    Text = "Послушаю, как ты будешь оправдываться дальше."
  },
  AvgCommunicate_67033_Content_6 = {
    Text = "Эх, а потом сегодня я вдруг встретил противника, равного мне по силам."
  },
  AvgCommunicate_67033_Content_7 = {
