  AvgCommunicate_67035_Content_3 = {
    Text = "Ой, на этот раз я Правда не стою у вашей двери!"
  },
  AvgCommunicate_67035_Content_4 = {
    Text = "В прошлый раз благодаря вашей помощи я долго наслаждалась жизнью внутри боксёрской груши в тренировочном зале. Было как дома — я никогда ещё не была так счастлива."
