  AvgCommunicate_67038_Content_8 = {
    Text = "Единственная плохая новость — похоже, родился лишь тот мир, в котором Мириам получила ранение..."
  },
  AvgCommunicate_67038_Content_9 = {
    Text = "Это лишь доказывает, что она — слепая жрица, не понимающая божество, которому поклоняется."
  },
  AvgCommunicate_67038_Option_11 = {
