  AvgCommunicate_67039_Content_10 = {
    Text = "От такой неожиданной похвалы мне даже неловко стало…"
  },
  AvgCommunicate_67039_Content_11 = {
    Text = "Не стесняйся, ты всегда был моей музой. Когда у тебя будет свободное время, не заглянешь ко мне в мастерскую?"
  },
  AvgCommunicate_67039_Content_12 = {
