  AvgCommunicate_67039_Content_3 = {
    Text = "В моём вдохновении — это ты, погружённый в прекрасный сон."
  },
  AvgCommunicate_67039_Content_4 = {
    Text = "Обрести слепое, иллюзорное счастье или осознанное, мучительное забвение?"
