  AvgCommunicate_67040_Content_4 = {
    Text = "Какой же ты бессердечный! А ведь в прошлый раз я была такой нежной～"
  },
  AvgCommunicate_67040_Content_5 = {
    Text = "Советую тебе следить за своими словами…"
  },
  AvgCommunicate_67040_Content_6 = {
    Text = "Хмф, притворяться глупенькой бесполезно, ведь я уже запечатлела в воске все твои контуры, все твои изгибы, все твои формы!"
  },
  AvgCommunicate_67040_Content_7 = {
    Text = "Так и хочется похвастаться этим перед всеми～"
  },
  AvgCommunicate_67040_Content_8 = {
    Text = "?! Ты не посмеешь?"
  },
  AvgCommunicate_67040_Content_9 = {
    Text = "Ой, это зависит от того, как мой сладкий будет ко мне относиться, я ведь такая ранимая～"
  },
  AvgCommunicate_67040_Option_10 = {
    Text = "Говори уже, что ты опять задумала…"
  },
  AvgCommunicate_67040_Option_2 = {
    Text = "Какое времяпрепровождение?"
  },
  AvgCommunicate_67040_Option_3 = {
    Text = "Не помню такого."
  },
  AvgCommunicate_67040_Option_5 = {
    Text = "Советую тебе следить за своими словами…"
  },
  AvgCommunicate_67040_Option_8 = {
    Text = "?! Ты не посмеешь?"
  },
  AvgCommunicate_67041_Content_1 = {
    Text = "Повелитель, ты только что махал мне — это значит, что хотел со мной связаться?"
  },
  AvgCommunicate_67041_Content_10 = {
    Text = "Эх, нужно срочно научить тебя распознавать коварных женщин в школе и объяснить тебе меры предосторожности."
  },
  AvgCommunicate_67041_Content_11 = {
    Text = "Послушай меня, немедленно уходи от её двери, чем дальше, тем лучше, а потом скажешь, что я тебя позвал(а)!"
  },
  AvgCommunicate_67041_Content_12 = {
    Text = "Но... но я уже дал слово госпоже Пандии, я не могу нарушить обещание."
  },
  AvgCommunicate_67041_Content_13 = {
    Text = "Не беспокойтесь, Повелитель, у меня достаточно сил, чтобы защитить себя!"
  },
  AvgCommunicate_67041_Content_14 = {
    Text = "Ты, я... Ладно, если уж ты настаиваешь на том, чтобы стоять там, ни в коем случае не заходи к ней в комнату."
  },
  AvgCommunicate_67041_Content_15 = {
    Text = "Хорошо, я, конечно же, не стану входить в комнату дамы!"
  },
  AvgCommunicate_67041_Content_16 = {
    Text = "Что бы она ни говорила, не заходи, а если что — зови меня. И ещё — ни в коем случае не нюхай её свечи!"
  },
  AvgCommunicate_67041_Content_17 = {
    Text = "Я запомнил, Повелитель. Но почему нельзя нюхать свечи?"
  },
  AvgCommunicate_67041_Content_18 = {
    Text = "Не спрашивай... Это горький урок, оплаченный моей кровью и слезами..."
  },
  AvgCommunicate_67041_Content_2 = {
    Text = "Именно! Почему ты всё время стоишь у двери Пандии??"
  },
  AvgCommunicate_67041_Content_3 = {
    Text = "А, это госпожа Пандия попросила меня. Она сказала, что ей нужно заняться чем-то очень важным, и попросила меня охранять её Ворота."
  },
  AvgCommunicate_67041_Content_4 = {
    Text = "Очень важным делом? Не верь её выдумкам! Её дела... а, ладно, тебя точно обманули!"
  },
  AvgCommunicate_67041_Content_5 = {
    Text = "А? Но у неё только что было такое серьёзное выражение лица, и она так искренне держала меня за руку..."
  },
  AvgCommunicate_67041_Content_6 = {
    Text = "Дай угадаю — она ещё держала тебя за руку и говорила, что ты самый надёжный и добрый рыцарь?"
  },
  AvgCommunicate_67041_Content_7 = {
    Text = "Хо Фэн повелитель знает?!"
  },
  AvgCommunicate_67041_Content_8 = {
