  AvgCommunicate_67042_Content_1 = {
    Text = "Дин-дон, у тебя Подарок от чистого сердца, не забудь забрать～"
  },
  AvgCommunicate_67042_Content_10 = {
    Text = "Да, пахнет приятно, аромат очень необычный, только вот почему-то голова немного кружится…"
  },
  AvgCommunicate_67042_Content_11 = {
    Text = "Может, ты уже влюбилась в кое-кого? Ну как, я уже по твоей просьбе спустился вниз～"
  },
  AvgCommunicate_67042_Content_12 = {
    Text = "Не хочешь ли выйти со свечой любви и провести со мной немного приятного времени～"
  },
  AvgCommunicate_67042_Content_13 = {
    Text = "Ты обманом…"
  },
  AvgCommunicate_67042_Content_14 = {
    Text = "Ну что ты, это же сладкий договор по обоюдному согласию."
  },
  AvgCommunicate_67042_Content_2 = {
    Text = "Ты про эту странную коробку у двери, на которой указан только получатель?"
  },
  AvgCommunicate_67042_Content_3 = {
    Text = "Тогда можешь прийти к мусорке у общежития и забрать её обратно."
