  AvgCommunicate_67042_Content_8 = {
    Text = "Это специально сделанная свеча любви! Когда она плавится, температура как～раз～идеальная～"
  },
  AvgCommunicate_67042_Content_9 = {
    Text = "Ну как, понюхай — Правда ведь ароматная? Хочется понюхать ещё разок, и ещё разок…"
