  AvgCommunicate_67042_Option_6 = {
    Text = "Ладно, гляну одним глазком, а потом приходи забирать к мусорке."
  },
  AvgCommunicate_67043_Content_1 = {
    Text = "Я уже давно живу в Мисагре, и вдруг мне захотелось увидеть луну над пустыней."
  },
  AvgCommunicate_67043_Content_10 = {
    Text = "Давай вместе создавать новые воспоминания — среди цветов, на просторах полей, у моря и в горных долинах, в городах и деревнях."
  },
  AvgCommunicate_67043_Content_11 = {
    Text = "Я хочу оставить общие воспоминания с тобой в каждом прекрасном месте. Ты ведь будешь рядом, Правда?"
  },
  AvgCommunicate_67043_Content_2 = {
    Text = "Так ты тоже скучаешь по дому?"
  },
  AvgCommunicate_67043_Content_3 = {
    Text = "Скорее, чем по дому, я скучаю по воспоминаниям, которые разделяла с людьми, по тем ярким чувствам."
  },
  AvgCommunicate_67043_Content_4 = {
    Text = "Не думал(а), что ты так дорожишь прошлым."
  },
  AvgCommunicate_67043_Content_5 = {
    Text = "Что? Думаешь, я беспечная и бессердечная? Нет, я помню каждого человека, каждое тёплое и сладкое воспоминание."
  },
  AvgCommunicate_67043_Content_6 = {
    Text = "В том числе и о тебе."
  },
  AvgCommunicate_67043_Content_7 = {
    Text = "Мне польщённым быть или ревновать?"
  },
  AvgCommunicate_67043_Content_8 = {
    Text = "Мне нравится, когда ты вот так смущаешься. Это так мило."
  },
  AvgCommunicate_67043_Content_9 = {
    Text = "Хоть прошлое и приятно вспоминать, но радость настоящего момента — самое ценное."
  },
  AvgCommunicate_67043_Option_2 = {
    Text = "Так ты тоже скучаешь по дому?"
  },
  AvgCommunicate_67043_Option_4 = {
    Text = "Не думал(а), что ты так дорожишь прошлым."
  },
  AvgCommunicate_67043_Option_7 = {
    Text = "Мне польщённым быть или ревновать?"
  },
  AvgCommunicate_67044_Content_1 = {
    Text = "В последнее время я обдумываю серию украшений для своей коллекции."
  },
  AvgCommunicate_67044_Content_10 = {
    Text = "Если не возражаешь, прими мои тщательно подобранные ожерелья — на этот раз это бесплатный Подарок."
  },
  AvgCommunicate_67044_Content_11 = {
    Text = "Если после примерки тебе какое-нибудь понравится, обязательно скажи мне."
  },
  AvgCommunicate_67044_Content_12 = {
    Text = "Даже если твоя голова пока ещё не принадлежит мне, одного вида того, как ты носишь это украшение, уже достаточно, чтобы доставить мне удовольствие."
  },
  AvgCommunicate_67044_Content_2 = {
    Text = "Вариантов дизайна слишком много, и я никак не могу определиться. Хотелось бы узнать твоё мнение."
