  },
  AvgCommunicate_67045_Content_1 = {
    Text = "Эх, в последнее время дела в моей лавке идут неважно. Давно не удавалось найти голову, которая бы меня устроила."
  },
  AvgCommunicate_67045_Content_10 = {
    Text = "Если бы вы вместе охотились на особо опасных преступников, возможно, это стало бы легендой о городских рейнджерах, карающих злодеев."
