  AvgCommunicate_67045_Content_2 = {
    Text = "Хм... Головы — это и Правда такая вещь, которую не так просто раздобыть."
  },
  AvgCommunicate_67045_Content_3 = {
    Text = "Поэтому недавно я заключила сделку с Ревизионной комиссией. Я помогаю им выслеживать беглецов, а они тайно предоставляют мне головы казнённых преступников."
  },
  AvgCommunicate_67045_Content_4 = {
