  AvgCommunicate_67045_Content_6 = {
    Text = "Разумеется, это не официальное сотрудничество. Но везде найдутся люди с гибким умом."
  },
  AvgCommunicate_67045_Content_7 = {
    Text = "Я также пыталась связаться с полицией Лондиниума, но они, похоже, больше доверяют тому господину детективу с собачьей головой."
  },
  AvgCommunicate_67045_Content_8 = {
    Text = "Раз кто-то уже опередил меня и занял эту нишу, мне пришлось искать другие пути."
