    Text = "Ты всё ещё не можешь их забыть. Ты всё ещё глубоко любишь их."
  },
  AvgCommunicate_70492_Content_8 = {
    Text = "Так... ты жалеешь, Мириам?"
  },
  AvgCommunicate_70492_Option_3 = {
    Text = "Без проблем."
  },
  AvgCommunicate_70492_Option_4 = {
    Text = "Это для твоей семьи или для Деборы?"
  },
  AvgCommunicate_70492_Option_8 = {
    Text = "Ты жалеешь?"
  },
  AvgCommunicate_70493_Content_1 = {
    Text = "Твоё предсмертное письмо… Я дочитала его до конца."
  },
  AvgCommunicate_70493_Content_10 = {
    Text = "И я непременно буду с гордостью рассказывать людям о твоих подвигах, до тех пор… пока Разложение не поглотит мою память."
  },
  AvgCommunicate_70493_Content_11 = {
    Text = "Но когда я читала твоё письмо… в этот самый миг сожаление — единственное, что заполняло мои мысли."
  },
  AvgCommunicate_70493_Content_12 = {
    Text = "Ты говорила, что ты трусиха. Говорила, что ни за что не сможешь нас бросить."
  },
  AvgCommunicate_70493_Content_13 = {
    Text = "Но в конце концов ты всё же ступила на этот путь."
  },
  AvgCommunicate_70493_Content_14 = {
    Text = "Отца больше нет. И тебя больше нет."
  },
  AvgCommunicate_70493_Content_15 = {
    Text = "Мне всё равно, что ты лгала. Как бы я хотела, чтобы ты обманывала меня ещё немного. Год, месяц…"
  },
  AvgCommunicate_70493_Content_16 = {
    Text = "Хотя бы один день — чтобы слова, которые я не успела сказать, хотя бы получили шанс быть произнесёнными…"
  },
  AvgCommunicate_70493_Content_17 = {
    Text = "Мне страшно, %player%."
  },
  AvgCommunicate_70493_Content_18 = {
    Text = "Я боюсь, что однажды забуду, как ты выглядела, забуду твоё имя."
  },
  AvgCommunicate_70493_Content_19 = {
    Text = "Я боюсь, что однажды ты навсегда исчезнешь из моей памяти…"
  },
  AvgCommunicate_70493_Content_2 = {
    Text = "Я старалась, как ты и просила, произносить эти слова с радостью в голосе."
  },
  AvgCommunicate_70493_Content_20 = {
    Text = "Но ты знаешь — я не из тех, кто сдаётся."
  },
  AvgCommunicate_70493_Content_21 = {
    Text = "Я не верю, что ты вот так просто исчезнешь."
  },
  AvgCommunicate_70493_Content_22 = {
    Text = "Сколько бы ни пришлось ждать, я буду ждать и помнить. До того дня, когда ты очнёшься из Чёрного Омута, откроешь ту Ворота и вернёшься в этот кампус."
  },
  AvgCommunicate_70493_Content_23 = {
    Text = "И тогда всё, что произошло в твоё отсутствие, все слова, что так и не были сказаны, — я расскажу тебе обо всём, слово за словом…"
  },
  AvgCommunicate_70493_Content_24 = {
    Text = "Я знаю, сейчас ты очень устал(а), настолько, что не можешь ответить… Ничего, спи спокойно."
  },
  AvgCommunicate_70493_Content_25 = {
    Text = "Я буду ждать тебя… %player%."
  },
  AvgCommunicate_70493_Content_3 = {
    Text = "Я пыталась. Но у меня не получилось, %player%…"
  },
  AvgCommunicate_70493_Content_4 = {
    Text = "Склеп Ключей был полон людей, но я никого не видела."
  },
  AvgCommunicate_70493_Content_5 = {
    Text = "Весь мир затих. Лишь шум дождя, лишь ты и я."
  },
  AvgCommunicate_70493_Content_6 = {
    Text = "Когда та Ворота закрылась передо мной, когда строка за строкой проплывали перед глазами… всё, что я чувствовала, — лишь сожаление."
  },
  AvgCommunicate_70493_Content_7 = {
    Text = "Я жалею, что внушала тебе идеалы следователей, жалею, что учила тебя методам расследования, жалею, что забрала тебя из Акута…"
  },
  AvgCommunicate_70493_Content_8 = {
    Text = "Я знаю, мне не следует так думать."
  },
  AvgCommunicate_70493_Content_9 = {
    Text = "Я — следователь. Ты спасла наш мир от Разложения, и я должна радоваться за тебя."
  },
  AvgCommunicate_70494_Content_1 = {
    Text = "Добрый день, Страж Мессага."
  },
  AvgCommunicate_70494_Content_10 = {
    Text = "Я слышал, что в Мессаге появился выдающийся Страж."
  },
  AvgCommunicate_70494_Content_11 = {
    Text = "Не стоило бы беспокоить без повода, но я не смог сдержать своё любопытство и решил лично взглянуть."
  },
  AvgCommunicate_70494_Content_12 = {
    Text = "Ты не разочаровал меня, %player%."
  },
  AvgCommunicate_70494_Content_13 = {
    Text = "Чего ты добиваешься?"
  },
  AvgCommunicate_70494_Content_14 = {
    Text = "Если представится возможность, я хотел бы пригласить тебя в мою лабораторию."
  },
  AvgCommunicate_70494_Content_15 = {
    Text = "Страж, способный связываться с бесчисленными Пробуждёнными… Тайна, скрытая в тебе, очень меня интересует."
  },
  AvgCommunicate_70494_Content_16 = {
    Text = "Если ты приведёшь людей из Общества скульпторов и сдашься Мессагу, то сотрудничество можно обсудить."
  },
  AvgCommunicate_70494_Content_17 = {
    Text = "Хм... Я думала, что получу в Лечение поток брани."
  },
  AvgCommunicate_70494_Content_18 = {
    Text = "Ты интереснее, чем я предполагала."
  },
  AvgCommunicate_70494_Content_19 = {
    Text = "Впереди у нас много времени, и в будущем у нас будет немало возможностей пообщаться."
  },
  AvgCommunicate_70494_Content_2 = {
    Text = "Это ты… Герберт Розенталь…"
  },
  AvgCommunicate_70494_Content_20 = {
    Text = "Жди с нетерпением, %player%."
  },
  AvgCommunicate_70494_Content_3 = {
    Text = "Ой, похоже, кто-то уже представил меня вместо меня."
  },
  AvgCommunicate_70494_Content_4 = {
    Text = "Что ж, это избавило меня от лишних хлопот."
  },
  AvgCommunicate_70494_Content_5 = {
    Text = "Связать через Серебряное ядро требует двустороннего соединения. Как ты связался со мной?"
  },
  AvgCommunicate_70494_Content_6 = {
    Text = "Ну, это…"
  },
  AvgCommunicate_70494_Content_7 = {
    Text = "Для тех, кому посчастливилось участвовать в разработке, технология связи Серебряного ядра не хранит секретов."
  },
  AvgCommunicate_70494_Content_8 = {
    Text = "Ты — разработчик связи Серебряного ядра?"
  },
  AvgCommunicate_70494_Content_9 = {
    Text = "Дела давно минувших дней. Поговорим об этом на досуге."
  },
  AvgCommunicate_70494_Option_13 = {
    Text = "Чего ты добиваешься?"
  },
  AvgCommunicate_70494_Option_16 = {
    Text = "Только если ты сдашься Мессагу"
  },
  AvgCommunicate_70494_Option_2 = {
    Text = "Герберт Розенталь…"
  },
  AvgCommunicate_70494_Option_5 = {
    Text = "Как ты связался со мной?"
  },
  AvgCommunicate_70495_Content_1 = {
    Text = "Останки Андерсона были уничтожены людьми из Общества скульпторов — собрать их в целую человеческую фигуру невозможно."
  },
  AvgCommunicate_70495_Content_10 = {
    Text = "Возможно, однажды мы тоже…"
  },
  AvgCommunicate_70495_Content_11 = {
    Text = "Тебе бывает страшно, старший Уильям?"
  },
  AvgCommunicate_70495_Content_13 = {
    Text = "Возможно, кто-то и способен быть выше жизни и смерти, но не я."
  },
  AvgCommunicate_70495_Content_14 = {
    Text = "Я испытываю Страх каждое мгновение, %player%."
  },
  AvgCommunicate_70495_Content_15 = {
    Text = "Но я никогда не замечал в тебе ни капли страха."
  },
  AvgCommunicate_70495_Content_16 = {
    Text = "Потому что у меня нет на это времени. Потому что Эрозия прямо передо мной."
  },
  AvgCommunicate_70495_Content_17 = {
    Text = "Многие погибли, но я всё ещё жив."
  },
  AvgCommunicate_70495_Content_18 = {
    Text = "Страх ли это, скорбь ли — следователь Мифсага не имеет права останавливаться из-за этого."
  },
  AvgCommunicate_70495_Content_2 = {
    Text = "Насильно извлечённые серебряные ядра тоже полностью разрушены."
  },
  AvgCommunicate_70495_Content_20 = {
    Text = "Поступило новое задание."
  },
  AvgCommunicate_70495_Content_21 = {
    Text = "Мы выживем, %player%. Доживём до того дня, когда Эрозия будет побеждена."
  },
  AvgCommunicate_70495_Content_3 = {
    Text = "Мы обыскали всю лабораторию в богадельне и нашли только это."
  },
  AvgCommunicate_70495_Content_4 = {
    Text = "Серебряный ключ, номер L-1463, принадлежавший следователю Андерсону — когда-то принадлежавший."
  },
  AvgCommunicate_70495_Content_5 = {
    Text = "Этот Cеребряный ключ… Что школа с ним сделает?"
  },
  AvgCommunicate_70495_Content_6 = {
    Text = "Изымет, поместит в Чёрный пруд для переплавки, а затем на следующей церемонии Ключевого кургана передаст новому следователю."
  },
  AvgCommunicate_70495_Content_7 = {
    Text = "Он будет сопровождать нового следователя, вновь и вновь отправляясь в самые опасные места."
  },
  AvgCommunicate_70495_Content_8 = {
    Text = "Пока тот следователь не уйдёт в отставку или не погибнет."
  },
  AvgCommunicate_70495_Content_9 = {
    Text = "Возможно, однажды мы тоже…"
  },
  AvgCommunicate_70495_Option_10 = {
    Text = "Тебе бывает страшно?"
  },
  AvgCommunicate_70495_Option_15 = {
    Text = "Я никогда не чувствовал твоего страха."
  },
  AvgCommunicate_70495_Option_5 = {
    Text = "Этот Cеребряный ключ… Что школа с ним сделает?"
  },
  AvgCommunicate_70495_Option_9 = {
    Text = "Мы закончим так же, как Андерсон?"
  },
  AvgCommunicate_70496_Content_1 = {
    Text = "Ритуалы этих аланцев... просто жуть берёт."
  },
  AvgCommunicate_70496_Content_10 = {
    Text = "Разве я похож на такого человека?"
  },
  AvgCommunicate_70496_Content_11 = {
    Text = "Я просто спросил, чего так нервничать?"
  },
  AvgCommunicate_70496_Content_12 = {
    Text = "С такой реакцией тебя за карточным столом раскусят в два счёта. Над психологической устойчивостью ещё работать и работать, Страж."
  },
  AvgCommunicate_70496_Content_13 = {
    Text = "В общем, тайны этой пустыни, похоже, куда сложнее, чем мы предполагали."
  },
  AvgCommunicate_70496_Content_14 = {
    Text = "В дальнейшем расследовании нужно быть осторожнее."
  },
  AvgCommunicate_70496_Content_2 = {
    Text = "А я думал, ты примешь Приглашение той аланской женщины."
  },
  AvgCommunicate_70496_Content_4 = {
    Text = "Интересно, за кого ты меня вообще принимаешь..."
  },
  AvgCommunicate_70496_Content_5 = {
    Text = "Не думал, что даже у такого обаятельного повесы, как Лейк, есть вещи, которые он не может принять."
  },
  AvgCommunicate_70496_Content_6 = {
    Text = "Ни цветов, ни историй под бокал вина — лишь самые первобытные и безумные желания."
  },
  AvgCommunicate_70496_Content_7 = {
    Text = "Такие ритуалы и впрямь не в моём вкусе."
  },
  AvgCommunicate_70496_Content_8 = {
    Text = "Кстати, ты ведь не принял никаких странных приглашений?"
  },
  AvgCommunicate_70496_Content_9 = {
    Text = "К-конечно нет... Как такое вообще возможно!"
  },
  AvgCommunicate_70496_Option_2 = {
    Text = "А я думал, ты примешь Приглашение той аланской женщины"
  },
  AvgCommunicate_70496_Option_5 = {
    Text = "Не думал, что и тебе что-то может быть не по нраву"
  },
  AvgCommunicate_70496_Option_9 = {
    Text = "К-конечно нет... Как такое вообще возможно!"
  },
  AvgCommunicate_70497_Content_1 = {
    Text = "Здравствуй, хранитель тайн {Male=господин,Female=госпожа}."
  },
  AvgCommunicate_70497_Content_2 = {
    Text = "Весело было играть с игрушками Юриэтт?"
  },
  AvgCommunicate_70497_Content_3 = {
    Text = "Ты... тот самый предатель?!"
  },
  AvgCommunicate_70497_Content_4 = {
    Text = "А я-то думал, ты догадаешься раньше, кто я. Как жаль."
  },
  AvgCommunicate_70497_Content_5 = {
    Text = "Но ничего страшного, это была лишь последняя игра."
  },
  AvgCommunicate_70497_Content_6 = {
    Text = "И теперь игра подходит к концу."
  },
  AvgCommunicate_70497_Content_7 = {
    Text = "Перед неизбежной гибелью меня интересует лишь одно."
  },
  AvgCommunicate_70497_Content_8 = {
    Text = "Истина вечного хаоса — хватит ли смелости взглянуть ей в лицо нам, самонадеянным хранителям тайн, доблестным спасителям Мисагарда?"
  },
  AvgCommunicate_70497_Option_3 = {
    Text = "Ты... тот самый предатель?!"
  },
  AvgCommunicate_70498_Content_1 = {
    Text = "Я отнюдь не глупый торговец, но, если подумать, кажется, я заключила невыгодную сделку..."
  },
  AvgCommunicate_70498_Content_10 = {
    Text = "Всегда остерегаться лжи — основное качество достойного торговца."
  },
  AvgCommunicate_70498_Content_11 = {
    Text = "Так... это действительно было истинное лицо госпожи Дафдель?"
  },
  AvgCommunicate_70498_Content_12 = {
    Text = "Нет ничего дороже правды, маленький хранитель тайн."
  },
  AvgCommunicate_70498_Content_13 = {
    Text = "Спасибо, госпожа Дафдель."
  },
  AvgCommunicate_70498_Content_14 = {
    Text = "То, что я сказала раньше, было шуткой. Я знаю, что для таких, как вы, показать свою истинную сторону — это многого стоит."
  },
  AvgCommunicate_70498_Content_15 = {
    Text = "Это драгоценный дар, и я буду бережно его хранить."
  },
  AvgCommunicate_70498_Content_16 = {
    Text = "Не думай, что отделаешься парой красивых фраз, малыш."
  },
  AvgCommunicate_70498_Content_17 = {
    Text = "В Лечение тебе тоже следует преподнести мне Подарок, не так ли?"
  },
  AvgCommunicate_70498_Content_18 = {
    Text = "Меня раскусили..."
  },
  AvgCommunicate_70498_Content_19 = {
    Text = "Госпожа Даффодил, чего вы хотите?"
  },
  AvgCommunicate_70498_Content_2 = {Text = "?"},
  AvgCommunicate_70498_Content_20 = {
    Text = "Раз уж ты видел мой истинный облик, то когда ты покажешь мне свой?"
  },
  AvgCommunicate_70498_Content_21 = {
    Text = "Мой истинный облик? Что вы имеете в виду... Я не совсем понимаю, госпожа Даффодил."
  },
  AvgCommunicate_70498_Content_22 = {
    Text = "Похоже, Мисагер тебе ещё ничего не рассказал..."
  },
  AvgCommunicate_70498_Content_23 = {
    Text = "Время ещё не пришло, ничего страшного."
  },
  AvgCommunicate_70498_Content_24 = {
    Text = "Запомни нашу сегодняшнюю сделку, малыш."
  },
  AvgCommunicate_70498_Content_25 = {
    Text = "Я с нетерпением жду того дня, когда ты покажешь своё истинное лицо."
  },
  AvgCommunicate_70498_Content_3 = {
    Text = "Разве вы не получили ту голову, которую хотели?"
  },
  AvgCommunicate_70498_Content_4 = {
    Text = "В том переливающемся всеми красками Сером море появился ещё один экспонат, который вам по душе."
  },
  AvgCommunicate_70498_Content_5 = {
    Text = "Действительно, это прекрасная голова, и нельзя сказать, что сделка была совсем бесплодной."
  },
  AvgCommunicate_70498_Content_6 = {
    Text = "Однако цена, которую я заплатила, всё же слишком высока."
  },
  AvgCommunicate_70498_Content_7 = {
    Text = "Вы лишь позволили мне мельком увидеть ваш истинный облик..."
  },
  AvgCommunicate_70498_Content_8 = {
    Text = "К тому же, был ли это действительно ваш истинный облик — ещё вопрос."
  },
  AvgCommunicate_70498_Content_9 = {
    Text = "Хе-хе... Неплохо, малыш."
  },
  AvgCommunicate_70498_Option_11 = {
    Text = "Так... это действительно было истинное лицо госпожи Дафдель?"
  },
  AvgCommunicate_70498_Option_13 = {
    Text = "Спасибо, госпожа Дафдель."
  },
  AvgCommunicate_70498_Option_18 = {
    Text = "Меня раскусили..."
  },
  AvgCommunicate_70498_Option_2 = {
    Text = "Разве вы не получили голову?"
  },
  AvgCommunicate_70498_Option_21 = {
    Text = "Мой истинный облик? Что вы имеете в виду..."
  },
  AvgCommunicate_70498_Option_7 = {
    Text = "Я лишь взглянул на ваш истинный облик..."
  },
  AvgCommunicate_70499_Content_1 = {
    Text = "Устранив неугодных, она избавилась от оков Ламбера и контрактов. Без этих помех всего за несколько недель она стала самым свирепым хищником в деловых кругах Лондиниума."
  },
  AvgCommunicate_70499_Content_10 = {
    Text = "Не волнуйтесь, профессор Декстер, мы больше не будем подвергать вас подобной опасности… По крайней мере, постараемся."
  },
  AvgCommunicate_70499_Content_11 = {
    Text = "Сущность, скрывающаяся в сознании Сорейль, похоже, зовётся «N». Вам что-нибудь известно о нём?"
  },
  AvgCommunicate_70499_Content_12 = {
    Text = "Не особо. Судя по всему, он либо мошенник, либо безумец, а скорее всего — и то, и другое."
  },
  AvgCommunicate_70499_Content_13 = {
    Text = "Но каким бы злодеем он ни был, у него определённо есть вкус. Это слышно по его пению."
  },
  AvgCommunicate_70499_Content_14 = {
    Text = "При случае непременно нужно будет с ним познакомиться поближе. Глядишь, и пропустим вместе стаканчик-другой."
  },
  AvgCommunicate_70499_Content_15 = {
    Text = "…Разумеется, в безопасной обстановке. Старый джентльмен больше не вынесет никаких потрясений."
  },
  AvgCommunicate_70499_Content_2 = {
    Text = "Думаю, скоро вся земля в Лондиниуме будет записана на её имя."
  },
  AvgCommunicate_70499_Content_3 = {
    Text = "Леди Сорейль — поистине удивительная женщина. Хорошо, что Мисагэ на её стороне."
  },
  AvgCommunicate_70499_Content_4 = {
    Text = "На этот раз всё получилось благодаря вашей помощи, профессор Декстер."
  },
  AvgCommunicate_70499_Content_5 = {
    Text = "Спасибо, что помогли выманить подозреваемого, иначе неизвестно, сколько бы ещё пришлось разбираться с этим делом."
  },
  AvgCommunicate_70499_Content_6 = {
    Text = "Всего лишь исполнял долг джентльмена."
  },
  AvgCommunicate_70499_Content_7 = {
    Text = "У этого старого отца не было права отказать плану, предложенному Рамоной."
  },
  AvgCommunicate_70499_Content_8 = {
    Text = "Однако, если в следующий раз случится нечто подобное, надеюсь, вы будете действовать побыстрее."
  },
  AvgCommunicate_70499_Content_9 = {
    Text = "Не стоит ждать, пока нож окажется в пяти сантиметрах от моей шеи, прежде чем вмешаться. Это, знаете ли, пугает."
  },
  AvgCommunicate_70499_Option_10 = {
    Text = "Такого больше не повторится… постараемся"
  },
  AvgCommunicate_70499_Option_11 = {
    Text = "Вы что-нибудь знаете о «N»?"
  },
  AvgCommunicate_70499_Option_4 = {
    Text = "Спасибо, что помогли выманить подозреваемого"
  },
  AvgCommunicate_70500_Content_1 = {
    Text = "Беседа в кафе была очень приятной, Страж{Male=господин,Female=госпожа}."
  },
  AvgCommunicate_70500_Content_10 = {
    Text = "А если в следующий раз возникнет такая ситуация, и тебе придётся выстрелить в настоящего меня, чтобы спасти остальных, — ты тоже выстрелишь?"
  },
  AvgCommunicate_70500_Content_11 = {
    Text = "Хм… Конечно."
  },
  AvgCommunicate_70500_Content_12 = {
    Text = "Но не волнуйся, Страж {Male=господин,Female=госпожа}. Удача по-прежнему на моей стороне."
  },
  AvgCommunicate_70500_Content_13 = {
    Text = "В тот момент в моём пистолете точно не будет патронов."
