  },
  AvgCommunicate_70500_Content_2 = {
    Text = "Для меня честь — узнать прошлое одного игрока."
  },
  AvgCommunicate_70500_Content_3 = {
    Text = "Мне больше всего понравился момент, когда игрок проиграл всё и у него украли душу."
  },
  AvgCommunicate_70500_Content_4 = {
    Text = "Ха… Где-то проигрываешь, где-то выигрываешь — такова жизнь."
  },
  AvgCommunicate_70500_Content_5 = {
    Text = "Видишь, на этот раз удалось отыграться?"
  },
  AvgCommunicate_70500_Content_6 = {
    Text = "Значит, тот выстрел в меня — тоже был ставкой?"
