  AvgCommunicate_70500_Content_8 = {
    Text = "А остальные 30%?"
  },
  AvgCommunicate_70500_Content_9 = {
    Text = "Нет никаких остальных 30%. 70% — это и есть 100%."
  },
  AvgCommunicate_70500_Option_2 = {
    Text = "Для меня честь — узнать прошлое одного игрока"
  },
  AvgCommunicate_70500_Option_6 = {
    Text = "Так тот выстрел в меня — тоже был ставкой?"
