  AvgCommunicate_70500_Option_8 = {
    Text = "А остальные 30%?"
  },
  AvgCommunicate_70501_Content_1 = {
    Text = "Понравилось?"
  },
  AvgCommunicate_70501_Content_10 = {
    Text = "Но… история, которую рассказывает эта композиция, слишком жестока."
  },
  AvgCommunicate_70501_Content_11 = {
    Text = "Ты понял(а) её, Страж…"
  },
  AvgCommunicate_70501_Content_12 = {
    Text = "Всякое творчество жестоко."
  },
  AvgCommunicate_70501_Content_13 = {
    Text = "Именно в этой жестокости застывшее искусство обретает живую душу."
  },
  AvgCommunicate_70501_Content_14 = {
    Text = "Будь я на твоём месте, наверное, счёл(а) бы этот творческий процесс невыносимо тяжёлым…"
  },
  AvgCommunicate_70501_Content_15 = {
    Text = "Но ты другая, Шань. Я понимаю твой выбор."
  },
  AvgCommunicate_70501_Content_16 = {
    Text = "Такие произведения, как «Смерть коралловой девы», — это тот смысл, к которому ты стремишься."
  },
  AvgCommunicate_70501_Content_17 = {
    Text = "Я с нетерпением жду, когда эта «жестокость» вновь расцветёт в линиях, высеченных твоей рукой."
  },
  AvgCommunicate_70501_Content_19 = {
    Text = "Я думала, ты, как и все эти обыватели, посоветуешь мне сделать моё искусство «нормальнее»."
  },
  AvgCommunicate_70501_Content_2 = {
    Text = "Что?.. Моё лицо?"
  },
  AvgCommunicate_70501_Content_20 = {
    Text = "Эти слова очень важны для меня… Спасибо тебе, Страж{Male=господин,Female=госпожа}."
  },
  AvgCommunicate_70501_Content_21 = {
    Text = "В благодарность открою тебе маленький секрет: когда ты погружался(лась) в сон, я стояла прямо рядом с тобой."
  },
  AvgCommunicate_70501_Content_22 = {
    Text = "Все твои нелепые выражения лица я запечатлела в скульптурах. Как· жи·вы·е."
  },
  AvgCommunicate_70501_Content_23 = {
    Text = "Когда будет время, загляни в мой маленький выставочный зал～"
  },
  AvgCommunicate_70501_Content_24 = {
    Text = "Шань! Я дам тебе пятьдесят лиофаней, только, умоляю, выброси эти скульптуры…"
  },
  AvgCommunicate_70501_Content_25 = {
    Text = "Ты же сам(а) говорил(а) — живое и «жестокое» искусство. Разве нет, Страж?"
  },
  AvgCommunicate_70501_Content_3 = {
    Text = "Разумеется, я говорю о скульптуре, которую ты видел во сне."
  },
  AvgCommunicate_70501_Content_4 = {
    Text = "Линии живого тела естественны и гармоничны, но им недостаёт вечной красоты неподвижности, а также замысла и идеи — с произведением скульптуры их не сравнить."
  },
  AvgCommunicate_70501_Content_5 = {
    Text = "Ту группу скульптур сейчас мало кто видел. Мне хотелось бы узнать твоё мнение…"
  },
  AvgCommunicate_70501_Content_6 = {
    Text = "Что?.. Мои скульптуры?"
  },
  AvgCommunicate_70501_Content_7 = {
    Text = "Разумеется. Ту группу скульптур сейчас мало кто видел. Мне хотелось бы узнать твоё мнение…"
  },
  AvgCommunicate_70501_Content_8 = {
    Text = "Это была самая прекрасная скульптурная композиция, которую я когда-либо видел(а)."
  },
  AvgCommunicate_70501_Content_9 = {
    Text = "Застывшие линии, но в них запечатлены динамика и жизненная Огромная Огромная сила, которыми не обладают даже живые существа."
  },
  AvgCommunicate_70501_Option_14 = {
    Text = "Я понимаю твой выбор"
  },
  AvgCommunicate_70501_Option_2 = {
    Text = "Твоё лицо?"
  },
  AvgCommunicate_70501_Option_24 = {
    Text = "Не надо!!!"
  },
  AvgCommunicate_70501_Option_6 = {
    Text = "Твои скульптуры?"
  },
  AvgCommunicate_70501_Option_8 = {
    Text = "Прекрасно… и жестоко."
  },
  AvgCommunicate_70502_Content_1 = {
    Text = "Скучно. Скучно-скучно-скучно……"
  },
  AvgCommunicate_70502_Content_10 = {
    Text = "В Лондиниуме не разрешают держать рабов — варварское место."
  },
  AvgCommunicate_70502_Content_11 = {
    Text = "Пришлось послушаться тебя и командовать ими только в лабиринте."
  },
  AvgCommunicate_70502_Content_12 = {
    Text = "Когда они сражаются на арене — выглядит точь-в-точь как то, что я видела раньше!"
  },
  AvgCommunicate_70502_Content_13 = {
    Text = "Так вот для чего нужен лабиринт……"
  },
  AvgCommunicate_70502_Content_14 = {
    Text = "Именно-именно! Так интересно!"
  },
  AvgCommunicate_70502_Content_15 = {
    Text = "Пойдём скорее посмотрим! Это же высшая честь!"
  },
  AvgCommunicate_70502_Content_16 = {
    Text = "Ну, можно и так — побольше узнать об истории не помешает……"
  },
  AvgCommunicate_70502_Content_17 = {
    Text = "Юухаши наверняка понравится твоя арена. Может, позовём и его заодно?"
  },
  AvgCommunicate_70502_Content_18 = {
    Text = "Нет! Держите этого дьявола подальше!!!"
  },
  AvgCommunicate_70502_Content_2 = {
    Text = "Каждый день торчать в этой дыре — с ума сойти можно!"
  },
  AvgCommunicate_70502_Content_3 = {
    Text = "Мой лабиринт уже перестроен заново — я по памяти воссоздала там целую арену!"
  },
  AvgCommunicate_70502_Content_4 = {
    Text = "Пойдём вместе поиграем! Прямо сейчас!"
  },
  AvgCommunicate_70502_Content_5 = {
    Text = "Этот твой тон, которым ты командуешь рабами, — когда ты уже его исправишь……"
  },
  AvgCommunicate_70502_Content_6 = {
    Text = "Хмф, а что тут исправлять."
  },
  AvgCommunicate_70502_Content_7 = {
    Text = "Я и так уже пошла на огромные уступки! Теперь я командую рабами только в лабиринте."
  },
  AvgCommunicate_70502_Content_8 = {
    Text = "Ты теперь не боишься вспоминать те времена?"
  },
  AvgCommunicate_70502_Content_9 = {
    Text = "Ещё бы. Чего тут бояться!"
  },
  AvgCommunicate_70502_Option_16 = {
    Text = "Тогда давай и Юухаши позовём с нами"
  },
  AvgCommunicate_70502_Option_5 = {
    Text = "Когда ты уже исправишь свой тон……"
  },
  AvgCommunicate_70502_Option_8 = {
    Text = "Ты теперь не боишься вспоминать те времена?"
  },
  AvgCommunicate_70503_Content_1 = {
    Text = "То, что произошло в церкви... Если бы тебя там не было, пострадало бы ещё больше невинных людей..."
  },
  AvgCommunicate_70503_Content_10 = {
    Text = "Однако теперь она — нынешний глава Церкви Фонаря."
  },
  AvgCommunicate_70503_Content_11 = {
    Text = "Что?! Глава Церкви Фонаря?!!"
  },
  AvgCommunicate_70503_Content_12 = {
    Text = "В религиозном мире Церковь света — злейший враг вашей церкви... Как ваша ученица могла..."
  },
  AvgCommunicate_70503_Content_13 = {
    Text = "Это долгая история, Посланник."
  },
  AvgCommunicate_70503_Content_14 = {
    Text = "Когда-то она вместе со мной вершила дела Всеотца, отдавая всё, что у нас было, ради его паствы."
  },
  AvgCommunicate_70503_Content_15 = {
    Text = "Но, как ты видишь, заблудших, отвергающих Всеотца, не так просто обратить. Те жестокости и предрассудки не исчезнут от одних лишь благословений."
  },
  AvgCommunicate_70503_Content_16 = {
    Text = "Из-за бедствий, что обрушились на меня, она встала на путь, с которого трудно вернуться."
  },
  AvgCommunicate_70503_Content_17 = {
    Text = "Вот оно что..."
  },
  AvgCommunicate_70503_Content_18 = {
    Text = "Я понимаю. Как и в случае с тем, что произошло в церкви, — те, кого ваши добрые дела не смогли изменить, стали причиной её перемен…"
  },
  AvgCommunicate_70503_Content_19 = {
    Text = "Бог-Отец учил нас, что дела мирские не делятся на чёрное и белое. Благое деяние порой тоже может оказаться ошибкой."
  },
  AvgCommunicate_70503_Content_2 = {
    Text = "От лица церкви и всех невинных выживших я выражаю тебе искреннюю благодарность, Бледный Посланник."
  },
  AvgCommunicate_70503_Content_20 = {
    Text = "Я отдал всё страждущим, но забыл, что моя ученица тоже была одной из них."
  },
  AvgCommunicate_70503_Content_21 = {
    Text = "Церковь и моя Твёрдая Твёрдая вера, возможно, спасли многих, но не смогли спасти её."
  },
  AvgCommunicate_70503_Content_22 = {
    Text = "Я не был достойным учителем, посланник."
  },
  AvgCommunicate_70503_Content_23 = {
    Text = "Я по-прежнему буду следовать путём Бога-Отца. Но не знаю, представится ли мне ещё возможность загладить вину перед этой ученицей…"
  },
  AvgCommunicate_70503_Content_3 = {
    Text = "Не стоит благодарности, епископ Сальвадор. Это мой долг."
  },
  AvgCommunicate_70503_Content_4 = {
    Text = "Епископ, о вашем прошлом... Я хотел бы задать вам один вопрос..."
  },
  AvgCommunicate_70503_Content_5 = {
    Text = "Спрашивай, Посланник. Я отвечу на всё, что знаю."
  },
  AvgCommunicate_70503_Content_6 = {
    Text = "Моё прошлое открыто для каждого, кто находится под покровительством Всеотца."
  },
  AvgCommunicate_70503_Content_7 = {
    Text = "Когда я установил с вами связь, помимо Софии, я увидел некую женщину, которая вела с вами беседу."
  },
  AvgCommunicate_70503_Content_8 = {
    Text = "Это воспоминание занимает значительное место в вашем сознании... Вы, похоже, хорошо знакомы?"
  },
  AvgCommunicate_70503_Content_9 = {
    Text = "Действительно, хорошо знакомы. Когда-то она была моей лучшей ученицей."
  },
  AvgCommunicate_70503_Option_11 = {
    Text = "Глава Церкви Фонаря?!"
  },
  AvgCommunicate_70503_Option_17 = {
    Text = "Вот оно что..."
  },
  AvgCommunicate_70503_Option_3 = {
    Text = "Это мой долг"
  },
  AvgCommunicate_70503_Option_7 = {
    Text = "Кто та женщина, которая появилась в ваших воспоминаниях последней?"
  },
  AvgCommunicate_70504_Content_1 = {
    Text = "Хорошо ли вам спалось прошлой ночью, дорогой Гость?"
  },
  AvgCommunicate_70504_Content_10 = {
    Text = "Будьте спокойны, я заключила соглашение с одним господином и не стану делать ничего предосудительного."
  },
  AvgCommunicate_70504_Content_11 = {
    Text = "Для торговца честность — превыше всего."
  },
  AvgCommunicate_70504_Content_12 = {
    Text = "Тем более что секретов у вас не меньше, чем у меня. Не так ли?"
  },
  AvgCommunicate_70504_Content_13 = {
    Text = "Мои секреты? О чём вы?"
  },
  AvgCommunicate_70504_Content_14 = {
    Text = "Сейчас ещё не время. Но не волнуйтесь, сделка по обмену новыми секретами скоро начнётся."
  },
  AvgCommunicate_70504_Content_15 = {
    Text = "Метель на пути куда свирепее, чем ты думаешь."
  },
  AvgCommunicate_70504_Content_16 = {
    Text = "Пока есть время, наслаждайся теплом очага, малыш."
  },
  AvgCommunicate_70504_Content_2 = {
    Text = "Такая тёплая лавка в снежную бурю — большая редкость. Благодарю вас за приют, мадам Дафодель."
  },
  AvgCommunicate_70504_Content_3 = {
    Text = "Однако, похоже, ваш магазин скрывает немало секретов."
  },
  AvgCommunicate_70504_Content_4 = {
    Text = "Эти экспонаты, боюсь, не так просты, как кажутся на первый взгляд."
  },
  AvgCommunicate_70504_Content_5 = {
    Text = "Весьма наблюдательно. Однако выведывать чужие секреты — не самое джентльменское поведение."
  },
  AvgCommunicate_70504_Content_6 = {
    Text = "Простите, мадам Дафодель."
  },
  AvgCommunicate_70504_Content_7 = {
    Text = "Мы прибыли в это незнакомое место для расследования, и прежде всего нам необходимо обеспечить собственную безопасность."
  },
  AvgCommunicate_70504_Content_8 = {
    Text = "Надеюсь, вы понимаете."
  },
  AvgCommunicate_70504_Content_9 = {
    Text = "Разумеется. Если бы вы могли спокойно уснуть в доме незнакомца, то обучение Хранителей тайн в Мисагре явно оставляло бы желать лучшего."
  },
  AvgCommunicate_70504_Option_13 = {
    Text = "Мои секреты?"
  },
  AvgCommunicate_70504_Option_2 = {
    Text = "Похоже, здесь немало секретов"
  },
  AvgCommunicate_70504_Option_6 = {
    Text = "Простите, но мне нужно обеспечить безопасность операции"
  },
  AvgCommunicate_70505_Content_1 = {
    Text = "Мириам была главной жрицей, которой я доверял больше всех."
  },
  AvgCommunicate_70505_Content_10 = {
    Text = "В деле Ступивших в Море есть и моя вина."
  },
  AvgCommunicate_70505_Content_11 = {
    Text = "Никто не мог предвидеть, как всё обернётся. Это нельзя назвать грехом."
  },
  AvgCommunicate_70505_Content_12 = {
    Text = "То, что ты сделал, было единственно верным решением в тот момент."
  },
  AvgCommunicate_70505_Content_13 = {
    Text = "Вины на тебе нет, Тулу."
  },
  AvgCommunicate_70505_Content_14 = {
    Text = "Возможно. Но ты сам разрешил это дело."
  },
  AvgCommunicate_70505_Content_15 = {
    Text = "Никто не мог предвидеть, как всё обернётся."
  },
  AvgCommunicate_70505_Content_16 = {
    Text = "Даже если ошибка и была, ты её исправил."
  },
  AvgCommunicate_70505_Content_17 = {
    Text = "Ты исполнил свой долг как король Лемурии, Тулу."
  },
  AvgCommunicate_70505_Content_19 = {
    Text = "Слова утешения немного неуклюжи, но я их принимаю."
  },
  AvgCommunicate_70505_Content_2 = {
    Text = "Вместе с ней мы принесли Лемурии краткий период процветания."
  },
  AvgCommunicate_70505_Content_20 = {
    Text = "Я отправляюсь на покой."
  },
  AvgCommunicate_70505_Content_21 = {
    Text = "Когда возникнет нужда, я пробужусь."
  },
  AvgCommunicate_70505_Content_22 = {
    Text = "Мой долг — не только перед Лемурией, но и перед Мисагом."
  },
  AvgCommunicate_70505_Content_3 = {
    Text = "И она, и народ Лемурии верили, что я верну Лемурии славу божественного царства."
  },
  AvgCommunicate_70505_Content_4 = {
    Text = "Но… это была ложь, верно?"
  },
  AvgCommunicate_70505_Content_5 = {
    Text = "Во сне я получил Откровение."
  },
  AvgCommunicate_70505_Content_6 = {
    Text = "Конец Лемурии был неизбежен."
  },
  AvgCommunicate_70505_Content_7 = {
    Text = "С самого начала Лемурия жила во лжи."
