  },
  AvgCommunicate_70520_Content_13 = {
    Text = "Нравятся клоуны — сходи лучше в цирк. Или просто посмотри в Зеркало."
  },
  AvgCommunicate_70520_Content_14 = {
    Text = "Котик 24 такой милый!"
  },
  AvgCommunicate_70520_Content_15 = {
    Text = "Хм, существо, которое даже говорить по-человечески не умеет. Что в нём хорошего?"
  },
  AvgCommunicate_70520_Content_16 = {
    Text = "Тебе нужен питомец, чтобы заполнить пустоту своей скучной жизни?"
