  AvgCommunicate_70520_Content_2 = {
    Text = "24, у тебя опять личность переключилась…"
  },
  AvgCommunicate_70520_Content_20 = {
    Text = "Про... простите, Страж!"
  },
  AvgCommunicate_70520_Content_21 = {
    Text = "В последнее время я ходила с Дженкин по улицам и наслушалась ссор... Вот и новая личность получилась такой невоспитанной..."
  },
  AvgCommunicate_70520_Content_22 = {
