  },
  AvgCommunicate_70521_Option_5 = {
    Text = "И... Лили понравилось?"
  },
  AvgCommunicate_70521_Option_9 = {
    Text = "Фильм готов. Хочешь сходить посмотреть вместе?"
  },
  AvgCommunicate_70522_Content_1 = {
    Text = "Несколько земельных сделок в Лондиниуме прошли весьма успешно, и те проблемные контракты тоже удалось уладить."
  },
  AvgCommunicate_70522_Content_10 = {
    Text = "Что такое, неужели Страж Мисагера не держит своё слово?"
  },
  AvgCommunicate_70522_Content_11 = {
    Text = "Конечно нет! Просто..."
  },
  AvgCommunicate_70522_Content_12 = {
    Text = "Хм... Какой же ты ребёнок. Хоть я и не вижу, но думаю, что пока ты придумывал, как бы соврать, твоё лицо покраснело до самой шеи, верно?"
  },
  AvgCommunicate_70522_Content_13 = {
    Text = "Давай так. Мне нужно, чтобы ты передал Мисагэ кое-что, что я обещала ей подарить. Этой причины достаточно?"
  },
  AvgCommunicate_70522_Content_14 = {Text = "Но..."},
  AvgCommunicate_70522_Content_15 = {
    Text = "Ну всё, хватит «но», решено."
  },
  AvgCommunicate_70522_Content_16 = {
    Text = "Хорошо, я согласен... Для меня это честь, леди Сорейль."
  },
  AvgCommunicate_70522_Content_17 = {
    Text = "Вот так-то лучше."
  },
  AvgCommunicate_70522_Content_18 = {
    Text = "Между нами больше не нужны все эти формальности и взаимные проверки."
  },
  AvgCommunicate_70522_Content_19 = {
    Text = "Сегодня в восемь вечера, в винном погребе моего поместья. Никто тебя не остановит."
  },
  AvgCommunicate_70522_Content_2 = {
    Text = "Всё это благодаря твоей помощи, Страж."
  },
  AvgCommunicate_70522_Content_20 = {
    Text = "Я буду ждать тебя, мой маленький рыцарь."
  },
  AvgCommunicate_70522_Content_3 = {
    Text = "Эти утомительные деловые салоны наконец-то подходят к концу."
  },
  AvgCommunicate_70522_Content_4 = {
    Text = "Раз уж выдалось свободное время, не хочешь выпить со мной бокал вина?"
  },
  AvgCommunicate_70522_Content_5 = {
    Text = "Студентам Мисагера запрещено употреблять алкоголь..."
  },
  AvgCommunicate_70522_Content_6 = {
    Text = "Правда? Профессор Декстер говорил мне совсем другое."
  },
  AvgCommunicate_70522_Content_7 = {
    Text = "Кто бы ни установил это правило, его давно пора пересмотреть."
  },
  AvgCommunicate_70522_Content_8 = {
    Text = "А, ну это..."
  },
  AvgCommunicate_70522_Content_9 = {
    Text = "Ты ведь должен мне бокал вина. Помнишь?"
  },
  AvgCommunicate_70522_Option_11 = {
    Text = "Конечно нет! Просто..."
  },
  AvgCommunicate_70522_Option_16 = {
    Text = "Для меня это честь, леди Сорейль."
  },
  AvgCommunicate_70522_Option_5 = {
    Text = "Студентам Мисагера запрещено употреблять алкоголь..."
  },
  AvgCommunicate_70523_Content_1 = {
    Text = "Мы так спешили в дороге, что я не успел рассказать вам о местных обычаях и нравах."
  },
  AvgCommunicate_70523_Content_10 = {
    Text = "Как я уже говорила, я лишь посланница, несущая учение нашего Владыки."
  },
  AvgCommunicate_70523_Content_11 = {
    Text = "Наше божество создаст для мира лучшее будущее."
  },
  AvgCommunicate_70523_Content_12 = {
    Text = "Такие примитивные племена, как Алан, тоже являются частью этого будущего — они наши самые верные друзья."
  },
  AvgCommunicate_70523_Content_13 = {
    Text = "Разумеется, я понимаю сомнения Хранителя тайн {Male=господин,Female=госпожа}."
  },
  AvgCommunicate_70523_Content_14 = {
    Text = "Уверена, стоит нам провести вместе ещё немного времени, и эти сомнения рассеются сами собой."
  },
  AvgCommunicate_70523_Content_15 = {
    Text = "Вы проделали долгий путь — прошу, отдохните как следует."
  },
  AvgCommunicate_70523_Content_16 = {
    Text = "От имени Лемвахи я искренне приветствую тебя, Страж {Male=господин,Female=госпожа}."
  },
  AvgCommunicate_70523_Content_2 = {
    Text = "Может быть, у Хранителя тайн {Male=господин,Female=госпожа} есть какие-нибудь вопросы, на которые я мог бы ответить?"
  },
  AvgCommunicate_70523_Content_3 = {
    Text = "Мне любопытно узнать о здешних обычаях."
  },
  AvgCommunicate_70523_Content_4 = {
    Text = "Хотя народ Ялань из поколения в поколение живёт скотоводством, вдали от индустриального общества, прошу вас не считать их нецивилизованными дикарями."
  },
  AvgCommunicate_70523_Content_5 = {
    Text = "Здесь нет каких-то строгих правил, просто общайтесь с ними свободно."
  },
  AvgCommunicate_70523_Content_6 = {
    Text = "Гостеприимство народа Ялань, уверен, вы очень скоро почувствуете на себе."
  },
  AvgCommunicate_70523_Content_7 = {
    Text = "Не кажется ли вам странным, что в таком примитивном племени находится кто-то вроде посланницы Юлиэт?"
  },
  AvgCommunicate_70523_Content_8 = {
    Text = "Причина «явиться по зову сна, чтобы вести Алан» звучит несколько натянуто."
  },
  AvgCommunicate_70523_Content_9 = {
    Text = "Страж {Male=господин,Female=госпожа} слишком подозрителен."
  },
  AvgCommunicate_70523_Option_3 = {
    Text = "Мне любопытно узнать о здешних обычаях"
  },
  AvgCommunicate_70523_Option_7 = {
    Text = "Мне любопытно узнать о посланнице Лиэт"
  },
  AvgCommunicate_70524_Content_1 = {
    Text = "Кстати говоря, после музея восковых фигур мы уже давно не работали вместе."
  },
  AvgCommunicate_70524_Content_10 = {
    Text = "Надеюсь, наше сотрудничество пройдёт гладко."
  },
  AvgCommunicate_70524_Content_11 = {
    Text = "С помощью старшекурсника Уильяма всё обязательно пройдёт гладко!"
  },
  AvgCommunicate_70524_Content_2 = {
    Text = "В прошлый раз с Пучиноходцами старшекурсник Уильям тоже очень помог!"
