  AvgCommunicate_70524_Content_3 = {
    Text = "…Я всего лишь за рулём был, это не считается помощью."
  },
  AvgCommunicate_70524_Content_4 = {
    Text = "Всё-таки ставить два козыря на одно задание — расточительство."
