  AvgCommunicate_70524_Content_6 = {
    Text = "Тебя, похоже, совсем не смущает говорить такие вещи."
  },
  AvgCommunicate_70524_Content_7 = {
    Text = "В музее восковых фигур ты однажды спас мне жизнь. Я верну этот долг."
  },
  AvgCommunicate_70524_Content_8 = {
    Text = "В этом задании вы с Рамоной действуете на виду, и некоторые вещи вам будет неудобно делать."
  },
  AvgCommunicate_70524_Content_9 = {
    Text = "Расследование из тени я возьму на себя."
  },
  AvgCommunicate_70524_Option_11 = {
    Text = "Обязательно!"
  },
  AvgCommunicate_70524_Option_2 = {
    Text = "В прошлый раз с Пучиноходцами старшекурсник Уильям тоже очень помог"
  },
  AvgCommunicate_70524_Option_4 = {
    Text = "Всё-таки ставить два козыря на одно задание — расточительство"
  },
  AvgCommunicate_70525_Content_1 = {
    Text = "Та-да-дам!"
  },
  AvgCommunicate_70525_Content_10 = {
    Text = "Вот оно что. Ну ладно, пусть так."
  },
  AvgCommunicate_70525_Content_11 = {
    Text = "Надеюсь, на этот раз вы отнесётесь к выступлению с должным уважением и не выдадите снова что-нибудь вроде «и с тех пор девочка жила счастливо с мамой»!"
  },
  AvgCommunicate_70525_Content_2 = {
    Text = "Ну как, Страж Тайн, впечатлён сценическим оформлением Энди Джонсона?!"
