  AvgCommunicate_70525_Content_6 = {
    Text = "Мы готовим следующую работу."
  },
  AvgCommunicate_70525_Content_7 = {
    Text = "Так вот, декорации и Режиссура следующей постановки — решено, это будешь ты!"
