  },
  AvgCommunicate_70525_Option_9 = {
    Text = "У Дженкина есть кое-какие идеи насчёт истории Ночного Рейнджера…"
  },
  AvgCommunicate_70526_Content_1 = {
    Text = "Моё сотрудничество с Гербертом завершено."
  },
  AvgCommunicate_70526_Content_10 = {
    Text = "В любом случае, я хочу увидеть мир, который шире того, что я знаю."
  },
  AvgCommunicate_70526_Content_11 = {
    Text = "Ротан победила меня трижды. Я хочу узнать, что, помимо ненависти, способно дать человеку такую невероятную силу."
  },
  AvgCommunicate_70526_Content_12 = {
    Text = "Когда я найду Лечение, я вернусь."
  },
  AvgCommunicate_70526_Content_13 = {
    Text = "И тогда я надеюсь, что ты и Ротан согласитесь снова стать моими соперниками."
  },
  AvgCommunicate_70526_Content_14 = {
    Text = "Пока мы больше не враги — будь то как соперник или как союзник, — я буду только рад."
  },
  AvgCommunicate_70526_Content_15 = {
    Text = "Я передам Ротан. Думаю, она тоже будет с нетерпением ждать встречи с обновлённым тобой."
  },
  AvgCommunicate_70526_Content_16 = {
    Text = "Корабль отправляется."
  },
  AvgCommunicate_70526_Content_17 = {
    Text = "Настанет день, когда мы снова увидимся. До встречи, Шило."
  },
  AvgCommunicate_70526_Content_2 = {
    Text = "Я больше не буду вашим врагом. Это моё обещание."
  },
  AvgCommunicate_70526_Content_3 = {
    Text = "После той битвы ты бесследно исчез..."
  },
  AvgCommunicate_70526_Content_4 = {
    Text = "Герберт — наш Общий враг, и мы с радостью превратим вражду в дружбу."
  },
  AvgCommunicate_70526_Content_5 = {
    Text = "Если захочешь прийти, в Мисагаре тебе всегда будут рады."
  },
  AvgCommunicate_70526_Content_6 = {
    Text = "Благодарю. Но я собираюсь уйти."
  },
  AvgCommunicate_70526_Content_7 = {
    Text = "Уйти? Куда ты направишься?"
  },
  AvgCommunicate_70526_Content_8 = {
    Text = "Не знаю. Может, к какому-нибудь морю."
  },
  AvgCommunicate_70526_Content_9 = {
    Text = "А может, к какой-нибудь горе — я всё время слышу её зов."
  },
  AvgCommunicate_70526_Option_14 = {
    Text = "Я передам ей"
  },
  AvgCommunicate_70526_Option_17 = {
    Text = "До встречи, Шило."
  },
  AvgCommunicate_70526_Option_3 = {
    Text = "Ты можешь подумать о переезде в Мисагар"
  },
  AvgCommunicate_70526_Option_7 = {
    Text = "Куда ты направишься?"
  },
  AvgCommunicate_70527_Content_1 = {
    Text = "Орета показала Лили своих медуз."
  },
  AvgCommunicate_70527_Content_10 = {
    Text = "Потому что она исполнила своё самое заветное желание — чтобы ты жила счастливо."
  },
  AvgCommunicate_70527_Content_11 = {
    Text = "Лили хочет видеть, как мама так улыбается."
