  },
  AvgCommunicate_70527_Content_3 = {
    Text = "Сестрица Рамона принесла Лили очень-очень много вкусностей..."
  },
  AvgCommunicate_70527_Content_4 = {
    Text = "Лили, как ты себя сейчас чувствуешь, лучше?"
  },
  AvgCommunicate_70527_Content_5 = {Text = "Ага!"},
  AvgCommunicate_70527_Content_6 = {
    Text = "Лили вчера видела сон, ей приснилась мама…"
