  },
  AvgCommunicate_70527_Option_10 = {
    Text = "Потому что она исполнила своё желание"
  },
  AvgCommunicate_70527_Option_14 = {
    Text = "Хочешь ещё покататься на метро?"
  },
  AvgCommunicate_70527_Option_4 = {
    Text = "Лили, как ты сейчас себя чувствуешь?"
  },
  AvgCommunicate_70528_Content_1 = {
    Text = "После возвращения я попробовала ещё несколько новых вариантов."
  },
  AvgCommunicate_70528_Content_10 = {
    Text = "Живите, Страж… Вместе с той Рамоной найдите способ противостоять Эрозии."
  },
  AvgCommunicate_70528_Content_11 = {
    Text = "Если вам что-то от меня понадобится — не стесняйтесь обращаться."
