  AvgCommunicate_70529_Content_10 = {
    Text = "Конечно. Кстати, у одного из пациентов внезапно ухудшилось состояние, мне нужно немедленно этим заняться."
  },
  AvgCommunicate_70529_Content_11 = {
    Text = "Благодарю вас за то, что проводили Лили домой. Комната отдыха и угощения уже подготовлены для вас."
  },
  AvgCommunicate_70529_Content_12 = {
