  },
  AvgCommunicate_70533_Content_1 = {
    Text = "Страж Тайн, Страж Тайн!"
  },
  AvgCommunicate_70533_Content_10 = {
    Text = "Но... почему Аурита их не помнит?"
  },
  AvgCommunicate_70533_Content_11 = {
    Text = "Щенок, лошадка, медузка... Все они когда-то были друзьями Ауриты."
  },
  AvgCommunicate_70533_Content_12 = {
    Text = "Потом им нужно было уйти в очень далёкое место."
  },
  AvgCommunicate_70533_Content_13 = {
    Text = "Они боялись, что Аурита будет грустить, поэтому забрали с собой воспоминания Ауриты о них."
  },
  AvgCommunicate_70533_Content_14 = {
    Text = "Но они всё равно хотели быть рядом с Ауритой, поэтому оставили свои тела."
  },
  AvgCommunicate_70533_Content_15 = {
    Text = "Эти тела превратились в маленькие глиняные фигурки и остались в Водном дворце Ауриты."
  },
  AvgCommunicate_70533_Content_16 = {
    Text = "...Они всегда заботились об Аурите и были рядом с ней, и это никогда не менялось."
  },
  AvgCommunicate_70533_Content_17 = {
    Text = "Вроде бы понятно, а вроде бы и нет..."
  },
  AvgCommunicate_70533_Content_18 = {
    Text = "Но теперь Аурита знает! Все те, кто в Водном дворце, — это лучшие друзья Ауриты."
  },
  AvgCommunicate_70533_Content_19 = {
    Text = "Аурита будет хорошо о них заботиться и каждый день играть с ними вместе!"
  },
  AvgCommunicate_70533_Content_2 = {
    Text = "Ты знаешь, что находится внутри Водного дворца Орретты?"
  },
  AvgCommunicate_70533_Content_3 = {
    Text = "Как Аурита думает, что это такое?"
  },
  AvgCommunicate_70533_Content_4 = {
    Text = "Хм... Аурита не может вспомнить..."
  },
  AvgCommunicate_70533_Content_5 = {
    Text = "Кажется таким знакомым, как будто... как будто..."
  },
  AvgCommunicate_70533_Content_6 = {
    Text = "Друзья..."
  },
  AvgCommunicate_70533_Content_7 = {
    Text = "Аурита больше всего любит друзей, но... почему Аурита их не помнит?"
  },
  AvgCommunicate_70533_Content_8 = {
    Text = "Это всё — друзья Ауриты."
  },
  AvgCommunicate_70533_Content_9 = {
    Text = "Друзья? Аурита больше всего любит друзей!"
  },
  AvgCommunicate_70533_Option_11 = {
    Text = "Рассказать Аурите её историю"
  },
  AvgCommunicate_70533_Option_3 = {
    Text = "А что думает Аурита?"
  },
  AvgCommunicate_70533_Option_8 = {
    Text = "Это всё друзья Ауриты."
  },
  AvgCommunicate_72037_Content_1 = {
    Text = "Вчера мне приснилось Детство и множество людей из прошлого Лемурии."
  },
  AvgCommunicate_72037_Content_10 = {
    Text = "От тебя ничего не скроешь."
  },
  AvgCommunicate_72037_Content_11 = {
    Text = "Во сне нас окутывало необычайно тёплое и знакомое чувство. Поначалу мы думали, что его принесла Ноа."
  },
  AvgCommunicate_72037_Content_12 = {
    Text = "Лишь потом мы осознали, что за долгие века самым близким для нас стал не кто-то из людей, а холодный, безжизненный предмет."
  },
  AvgCommunicate_72037_Content_13 = {
    Text = "Тулу…"
  },
  AvgCommunicate_72037_Content_14 = {
    Text = "Убери своё сочувствие. С того момента, как мы возложили на себя корону, мы были готовы ко всему."
  },
  AvgCommunicate_72037_Content_15 = {
    Text = "Владыке Лемурии не нужно, чтобы кто-то проливал за нас слёзы."
  },
  AvgCommunicate_72037_Content_16 = {
    Text = "Тогда… не желает ли владыка Лемурии снова отведать тот рисовый сахарный десерт? Думаю, повара Мисагарда смогут воссоздать его вкус."
  },
  AvgCommunicate_72037_Content_18 = {
    Text = "Хм-хм, а ты заботлив."
  },
  AvgCommunicate_72037_Content_19 = {
    Text = "Что ж, пусть это будет твоим подношением."
  },
  AvgCommunicate_72037_Content_2 = {
    Text = "Эти воспоминания я никогда не любила обсуждать с другими. Однако... во вчерашнем сне присутствовал ты, не так ли?"
  },
  AvgCommunicate_72037_Content_3 = {
    Text = "?! Хо Фэн ты знаешь?"
  },
  AvgCommunicate_72037_Content_4 = {
    Text = "Я провожу во снах куда больше времени, чем в мире яви. Ты сомневаешься в восприятии того, кто живёт в сновидениях?"
  },
  AvgCommunicate_72037_Content_5 = {
    Text = "Помимо пророческих, мне порой снятся и обычные сны, но ни один из них не был таким реальным, таким последовательным, как вчерашний..."
  },
  AvgCommunicate_72037_Content_6 = {
    Text = "Словно кто-то сидел рядом со мной и заново переживал прошлое вместе."
  },
  AvgCommunicate_72037_Content_7 = {
    Text = "Это чувство... что ты не одинока... Оно было приятным."
  },
  AvgCommunicate_72037_Content_8 = {
    Text = "Я действительно всё время был рядом с тобой."
  },
  AvgCommunicate_72037_Content_9 = {
    Text = "Дай-ка угадаю — ты вселился в корону, верно?"
