  AvgCommunicate_72037_Option_10 = {Text = "Да"},
  AvgCommunicate_72037_Option_13 = {
    Text = "Тулу…"
  },
  AvgCommunicate_72037_Option_16 = {
    Text = "Тогда…"
  },
  AvgCommunicate_72037_Option_3 = {Text = "?！"},
  AvgCommunicate_72037_Option_8 = {
    Text = "Я действительно всё время был рядом с тобой."
  },
  AvgCommunicate_80100_Content_1 = {
    Text = "%player%, если не затруднит, не мог(ла) бы ты пройти психологический тест?"
  },
  AvgCommunicate_80100_Content_10 = {
    Text = "Рамона, Лотан, Ожье… Когда я остаюсь в одиночестве, в моих мыслях всегда всплывают их образы."
  },
  AvgCommunicate_80100_Content_11 = {
