  AvgCommunicate_80100_Content_8 = {
    Text = "Это одиночество и тоска таятся глубоко в твоей душе и со временем лишь усиливаются, оказывая непредсказуемое влияние."
  },
  AvgCommunicate_80100_Content_9 = {
    Text = "Возможно, ты права, я действительно очень скучаю по ним…"
