  AvgCommunicate_81323_Content_1 = {
    Text = "Благодетель, когда вы передадите мне новые тетради с заданиями?"
  },
  AvgCommunicate_81323_Content_10 = {
    Text = "Понимаю. Тогда, может быть, вы могли бы порекомендовать другого преподавателя, который хорошо разбирается в этих двух предметах?"
  },
  AvgCommunicate_81323_Content_11 = {
    Text = "Если это невозможно, я могу почитать другие книги и попробовать разобраться самостоятельно."
  },
  AvgCommunicate_81323_Content_12 = {
    Text = "Есть… кое-кто есть, но у неё не самый лёгкий характер."
  },
  AvgCommunicate_81323_Content_13 = {
    Text = "Ничего страшного, я не боюсь."
  },
  AvgCommunicate_81323_Content_14 = {
    Text = "А я боюсь! Ладно, если обратиться к Винкёр… м-м, она, пожалуй, сама первая сойдёт с ума."
  },
  AvgCommunicate_81323_Content_15 = {
    Text = "Сойдёт с ума? Эта учительница Винкёр чем-то больна?"
  },
  AvgCommunicate_81323_Content_16 = {
    Text = "Нет… хотя нельзя сказать, что нет… А-а-а! В общем, для начала я научу тебя одной главной истине обучения!"
  },
  AvgCommunicate_81323_Content_17 = {
    Text = "Хорошо, я вся внимание."
  },
  AvgCommunicate_81323_Content_18 = {
    Text = "Не нужно докапываться до сути абсолютно во всём!!!"
  },
  AvgCommunicate_81323_Content_19 = {
    Text = "А почему? Я не совсем понимаю — если не выяснить всё до конца, как можно по-настоящему усвоить материал…"
  },
  AvgCommunicate_81323_Content_2 = {
    Text = "А ещё, те две книги, что вы давали в прошлый раз, я уже полностью прочитал и записал 107 вопросов. Прошу вас, когда будет время, разъяснить их мне."
  },
  AvgCommunicate_81323_Content_20 = {
    Text = "Ты не устаёшь?! С таким усердием погружаться в Океан знаний… Ты добьёшься успеха в чём угодно…"
  },
  AvgCommunicate_81323_Content_21 = {
    Text = "Спасибо вам. Возможность свободно изучать то, что тебе интересно, — это такая драгоценная и радостная вещь."
  },
  AvgCommunicate_81323_Content_22 = {
    Text = "Когда становится совсем тяжело, достаточно немного отдохнуть — и всё хорошо. Разве от этого можно устать?"
  },
  AvgCommunicate_81323_Content_23 = {
    Text = "Так когда же вы познакомите меня с новым учителем? Обещаю, я постараюсь не так сильно докапываться до сути."
  },
  AvgCommunicate_81323_Content_24 = {
    Text = "Хмм… А как насчёт всего 97 вопросов?"
  },
  AvgCommunicate_81323_Content_3 = {
    Text = "Я был неправ"
  },
  AvgCommunicate_81323_Content_4 = {
    Text = "Я действительно был неправ"
  },
  AvgCommunicate_81323_Content_6 = {
    Text = "Не надо было давать тебе свои задания… Свои дела нужно делать самому……"
  },
  AvgCommunicate_81323_Content_7 = {
    Text = "Умоляю, не спрашивай меня больше! Если так будет продолжаться, мне по ночам кошмары будут сниться!"
  },
  AvgCommunicate_81323_Content_8 = {
    Text = "Ах… Простите, я и не думала, что мои расспросы так вас утомляют. Какая же я бестолковая."
  },
  AvgCommunicate_81323_Content_9 = {
