  },
  AvgCommunicate_81323_Option_14 = {
    Text = "А я боюсь!"
  },
  AvgCommunicate_81323_Option_16 = {
    Text = "Нет… хотя нельзя сказать, что нет…"
  },
  AvgCommunicate_81323_Option_18 = {
    Text = "Не нужно докапываться до сути абсолютно во всём!!!"
  },
  AvgCommunicate_81323_Option_20 = {
    Text = "Ты не устаёшь?!"
  },
  AvgCommunicate_81323_Option_3 = {
    Text = "Я был неправ"
