  AvgCommunicate_81324_Content_1 = {
    Text = "Благодетель, у меня снова появились вопросы по прочитанному."
  },
  AvgCommunicate_81324_Content_10 = {
    Text = "Вы хотите сказать… нужно смотреть на намерения при совершении поступка?"
  },
  AvgCommunicate_81324_Content_11 = {
    Text = "Именно! Подумай сам: когда я попросил тебя сделать те два задания, я хотел эксплуатировать тебя как бесплатную рабочую силу или дать тебе возможность учиться?"
  },
  AvgCommunicate_81324_Content_12 = {
    Text = "Я не знаю."
  },
  AvgCommunicate_81324_Content_13 = {
