  },
  AvgCommunicate_81324_Content_14 = {
    Text = "Вот оно что, я неправильно понял. А я-то думал, что вы просто хотели, чтобы я сделал за вас задание."
  },
  AvgCommunicate_81324_Content_16 = {
    Text = "Кхм-кхм… Ладно, подумай ещё вот о чём: когда мы совершаем поступок и при этом рассматриваем человека как цель самого действия, искренне заботясь о нём — это можно назвать нравственным."
  },
  AvgCommunicate_81324_Content_17 = {
    Text = "А если использовать человека лишь как инструмент — это, разумеется, безнравственно."
  },
  AvgCommunicate_81324_Content_18 = {
    Text = "Кажется, я понял. Это как когда Лампадоносцы использовали меня и Поллукса как инструменты для жертвоприношения, не заботясь о наших чувствах — вот это и есть безнравственно."
  },
  AvgCommunicate_81324_Content_19 = {
    Text = "Верно-верно, ты очень сообразительный!"
  },
  AvgCommunicate_81324_Content_2 = {
    Text = "Вы раньше говорили, что домашние задания нужны для проверки и оттачивания знаний, и если знания уже усвоены, то не стоит зацикливаться на том, выполнено задание или нет."
  },
  AvgCommunicate_81324_Content_20 = {
    Text = "Я понял, благодетель — вы действительно очень нравственный человек! Тогда, пожалуйста, дайте мне ещё несколько заданий! Я старательно всё выполню и приду с вопросами!"
  },
  AvgCommunicate_81324_Content_21 = {
    Text = "Благодетель?"
  },
  AvgCommunicate_81324_Content_22 = {
    Text = "Эм, у меня тут внезапно появились дела, насчёт задания лучше обратись напрямую к Доэр!"
  },
  AvgCommunicate_81324_Content_3 = {
    Text = "Хмм… кажется, я действительно что-то такое говорил."
  },
  AvgCommunicate_81324_Content_4 = {
    Text = "Но в книгах, которые я недавно читал, говорится, что просить других выполнять за тебя задания — это, похоже, безнравственный поступок."
