  AvgCommunicate_81325_Content_1 = {
    Text = "Какая удивительная коробочка! Благодетель, она точно работает не на магии или ритуальном круге?"
  },
  AvgCommunicate_81325_Content_10 = {
    Text = "Ну, не совсем. Просто обе эти дисциплины сейчас активно развиваются, и множество учёных расширяют и углубляют исследования, создавая новые знания."
  },
  AvgCommunicate_81325_Content_11 = {
    Text = "Если ты выберешь такую бурно развивающуюся дисциплину в качестве цели обучения, то, конечно, учиться придётся всю жизнь!"
  },
  AvgCommunicate_81325_Content_12 = {
    Text = "Вот оно что, знания, которые постоянно развиваются… Это поистине великолепно!"
  },
  AvgCommunicate_81325_Content_13 = {
    Text = "Когда мы изучаем писания Светоносцев, нельзя изменить ни единого слова — всё содержание зафиксировано, повторяется и остаётся неизменным навеки."
  },
  AvgCommunicate_81325_Content_14 = {
    Text = "Но каждый раз при изучении писаний возникает гнетущее чувство, будто сидишь в коробке и видишь предел одним взглядом."
  },
  AvgCommunicate_81325_Content_15 = {
    Text = "Воистину, только постоянно растущие знания соответствуют истинной сути жизни!"
  },
  AvgCommunicate_81325_Content_16 = {
    Text = "Вдруг стало так возвышенно……"
  },
  AvgCommunicate_81325_Content_17 = {
    Text = "Кстати говоря, у меня есть для тебя отличная возможность для обучения, и я готов предоставить её совершенно бесплатно."
  },
  AvgCommunicate_81325_Content_18 = {
    Text = "Правда, благодетель?! Моя благодарность не знает границ!"
  },
  AvgCommunicate_81325_Content_19 = {
    Text = "Конечно, Правда. Вот этот сборник упражнений по эксплуатации и ремонту серебряных ядер и вот это обязательное пособие по психологическим стратегиям следователя — какой ты хочешь сначала напис……"
  },
  AvgCommunicate_81325_Content_2 = {
    Text = "Нет, это чистейшая технология Серебряного Ядра. И ещё кое-что: коммуникатор стоит очень дорого, так что не советую его разбирать."
  },
  AvgCommunicate_81325_Content_20 = {
