  },
  AvgCommunicate_81325_Content_3 = {
    Text = "Ах, как жаль... Хо Фэн вы узнали, что я как раз собиралась его разобрать? Это Чтение мыслей?"
  },
  AvgCommunicate_81325_Content_4 = {
    Text = "Тоже нет... Чтобы угадать твои мысли, даже психология не нужна!"
  },
  AvgCommunicate_81325_Content_5 = {
    Text = "Должно быть, психология — тоже глубокая наука. Как стыдно, мои познания столь скудны..."
  },
  AvgCommunicate_81325_Content_6 = {
    Text = "Благодетель, сколько времени нужно, чтобы освоить эту технологию Серебряного Ядра и психологию?"
