  AvgCommunicate_84107_Content_1 = {
    Text = "Когда заканчиваются эти каникулы?"
  },
  AvgCommunicate_84107_Content_10 = {
    Text = "Все эти факторы нужно учитывать в совокупности, взвесить все за и против, и только тогда можно спланировать наиболее эффективный и рациональный маршрут."
