  AvgCommunicate_84107_Content_12 = {
    Text = "Да, раз уж я сделала свой выбор, я должна нести ответственность за свои обязанности."
  },
  AvgCommunicate_84107_Content_13 = {
    Text = "Начиная с сегодняшнего дня, я также буду каждую ночь совершать обход, чтобы убедиться, что за время каникул в академии не произойдёт ничего непредвиденного."
  },
  AvgCommunicate_84107_Content_14 = {
    Text = "Страж, на этом пока остановимся. Мне нужно идти работать."
