  },
  AvgCommunicate_84107_Content_7 = {
    Text = "……Это всего лишь регулирование движения в академии во время обеда, и для этого нужно столько подготовки?"
  },
  AvgCommunicate_84107_Content_8 = {
    Text = "Конечно. Какая столовая самая популярная, в какой академии больше всего студентов, какие студенты хотят попасть в столовую первыми — всё это влияет на планирование маршрутов."
  },
  AvgCommunicate_84107_Content_9 = {
