  },
  AvgCommunicate_84107_Option_7 = {
    Text = "Это всего лишь регулирование движения в академии во время обеда…"
  },
  AvgCommunicate_84108_Content_1 = {
    Text = "Страж, я приношу глубочайшие извинения за тот инцидент."
  },
  AvgCommunicate_84108_Content_10 = {
    Text = "Но здесь всё-таки не море, поэтому я внесла коррективы с учётом обстоятельств."
  },
  AvgCommunicate_84108_Content_11 = {
    Text = "Эта так называемая корректировка — неужели это значит, что тебя прикуют наручниками ко мне…"
  },
  AvgCommunicate_84108_Content_12 = {
    Text = "Да. Таким образом, если со мной что-то случится, вы сможете немедленно это заметить и предотвратить."
  },
  AvgCommunicate_84108_Content_13 = {
    Text = "…Могу я отказаться?"
  },
  AvgCommunicate_84108_Content_14 = {
    Text = "Вы, разумеется, можете отказаться."
  },
  AvgCommunicate_84108_Content_15 = {
    Text = "Но я уже стою За дверью."
  },
  AvgCommunicate_84108_Content_2 = {
    Text = "…Ты имеешь в виду случай, когда из-за бессонницы огни святого Эльма вышли из-под контроля?"
  },
  AvgCommunicate_84108_Content_3 = {
    Text = "Хотя Расплав·Доль вовремя вырубила меня, я всё равно чувствую вину."
  },
  AvgCommunicate_84108_Content_4 = {
    Text = "Я долго размышляла и пришла к выводу, что должна понести наказание."
  },
  AvgCommunicate_84108_Content_5 = {
    Text = "В этом нет необходимости. Тот инцидент не привёл к каким-либо серьёзным последствиям."
  },
  AvgCommunicate_84108_Content_6 = {
    Text = "Нет, за проступок полагается наказание — таковы правила."
  },
  AvgCommunicate_84108_Content_7 = {
    Text = "Я уже пристегнула один Конец наручников к себе, а для другого конца мне нужно ваше содействие."
  },
  AvgCommunicate_84108_Content_8 = {
    Text = "Моё содействие?"
  },
  AvgCommunicate_84108_Content_9 = {
    Text = "Обычно на корабле провинившегося сковывают за ноги и оставляют на палубе под палящим солнцем на несколько часов."
  },
  AvgCommunicate_84108_Option_11 = {
    Text = "Эта так называемая корректировка, неужели…"
  },
  AvgCommunicate_84108_Option_13 = {
    Text = "…Могу я отказаться?"
  },
  AvgCommunicate_84108_Option_2 = {
    Text = "Ты имеешь в виду…"
  },
  AvgCommunicate_84108_Option_5 = {
    Text = "В этом нет необходимости."
  },
  AvgCommunicate_84108_Option_8 = {
    Text = "Моё содействие?"
  },
  AvgCommunicate_84109_Content_1 = {
    Text = "Страж, спасибо вам."
  },
  AvgCommunicate_84109_Content_11 = {
    Text = "Вообще-то…"
  },
  AvgCommunicate_84109_Content_12 = {
    Text = "На самом деле? Что это ты вдруг начала мямлить? На тебя не похоже."
  },
  AvgCommunicate_84109_Content_13 = {
    Text = "На самом деле необязательно посещать морской музей, можно просто «отдохнуть»."
  },
  AvgCommunicate_84109_Content_14 = {
    Text = "Я не совсем понимаю, что вы подразумеваете под обычным «отдыхом», но рядом с вами я действительно чувствую умиротворение."
  },
  AvgCommunicate_84109_Content_15 = {
    Text = "Словно находишься посреди спокойного океана — нет бури, и буря не надвигается. Нужно лишь следовать курсу, и ты благополучно доберёшься до цели."
  },
  AvgCommunicate_84109_Content_16 = {
    Text = "...Хоть эту метафору и сложно понять, но я, кажется, уловила твою мысль."
  },
  AvgCommunicate_84109_Content_17 = {
    Text = "В будущем мы можем побывать в самых разных местах. Мир огромен, и помимо океана, в нём множество прекрасных пейзажей."
  },
  AvgCommunicate_84109_Content_18 = {
    Text = "...Я поняла. Я попробую."
  },
  AvgCommunicate_84109_Content_19 = {
    Text = "Увидеть... прекрасные пейзажи, отличные от океана."
  },
  AvgCommunicate_84109_Content_2 = {
    Text = "Почему вдруг благодаришь?"
  },
  AvgCommunicate_84109_Content_3 = {
    Text = "Во время посещения Лондонского морского музея я многому научилась."
  },
  AvgCommunicate_84109_Content_4 = {
    Text = "Выставленные морские хронометры, рукописные навигационные карты и страницы судовых журналов — всё это поможет улучшить навыки навигации."
  },
  AvgCommunicate_84109_Content_5 = {
    Text = "Я применю всё это в следующем плавании и обязательно доставлю всех в порт в целости и сохранности."
  },
  AvgCommunicate_84109_Content_6 = {
    Text = "Помнится, мы ходили в Лондонский морской музей, чтобы «отдохнуть»…"
  },
  AvgCommunicate_84109_Content_7 = {
    Text = "Ладно, главное, что тебе понравилось."
  },
  AvgCommunicate_84109_Content_8 = {
    Text = "Да, мне очень понравилось, и я надеюсь, что мы будем чаще вместе выбираться на Дрёма."
  },
  AvgCommunicate_84109_Content_9 = {
    Text = "Без проблем, сейчас посмотрю, какие ещё морские музеи в Лондоне можно посетить."
  },
  AvgCommunicate_84109_Option_12 = {
    Text = "На самом деле?"
  },
  AvgCommunicate_84109_Option_16 = {
    Text = "...Какая сложная метафора"
  },
  AvgCommunicate_84109_Option_2 = {
    Text = "Почему вдруг благодаришь?"
  },
  AvgCommunicate_84109_Option_6 = {Text = "…?"},
  AvgCommunicate_84109_Option_9 = {
    Text = "Без проблем"
  },
  AvgCommunicate_84110_Content_1 = {
    Text = "Можно ли выдать мне следующую-следующую-следующую партию кофеиновых запасов заранее, Страж?"
  },
  AvgCommunicate_84110_Content_10 = {
    Text = "Подожди, это всё безумнее и безумнее!"
  },
  AvgCommunicate_84110_Content_11 = {
    Text = "Где сейчас Винкель?"
  },
  AvgCommunicate_84110_Content_12 = {
    Text = "Прямо здесь, у меня. Проводит эксперимент с проводящим устройством, проверяя, можно ли преобразовать энергию @2<AvgCommunicateConfuseColor.Light>  в световую энергию."
  },
  AvgCommunicate_84110_Content_13 = {
    Text = "Почему ты не отказываешься?"
  },
  AvgCommunicate_84110_Content_14 = {
    Text = "Зачем отказываться? Обслуживание пассажиров — часть моей работы."
  },
  AvgCommunicate_84110_Content_16 = {
    Text = "Я сейчас приду. Задержи Винкеля."
  },
  AvgCommunicate_84110_Content_17 = {
    Text = "Принято, выполню ваш приказ ценой жизни."
  },
  AvgCommunicate_84110_Content_2 = {
    Text = "Твои запасы снова забрала Винкель?"
  },
  AvgCommunicate_84110_Content_3 = {
    Text = "Если быть точной, она их не «забрала» — я сама отдала их этой пассажирке."
  },
  AvgCommunicate_84110_Content_4 = {
    Text = "…Опять из-за чего-то вроде «в следующий раз я поднимусь на борт и отправлюсь в плавание»?"
  },
  AvgCommunicate_84110_Content_5 = {
    Text = "Я лишь выполняю свою работу. Обслуживание пассажиров — тоже часть моих обязанностей."
  },
  AvgCommunicate_84110_Content_6 = {
    Text = "…Заявка на снабжение одобрена. Это в последний раз."
  },
  AvgCommunicate_84110_Content_7 = {
    Text = "Кстати, Винкель всё ещё пытается извлечь @2 из твоей груди?"
  },
  AvgCommunicate_84110_Content_8 = {
    Text = "Нет, этот пассажир изменил подход к исследованиям."
  },
  AvgCommunicate_84110_Content_9 = {
    Text = "Например, тестирует интенсивность @2<AvgCommunicateConfuseColor.Light>  баллистическим гальванометром, сканирует спектральные линии @2<AvgCommunicateConfuseColor.Light>  спектроскопом, проверяет на испытательном стенде способ соединения @2<AvgCommunicateConfuseColor.Light>  с нервными волокнами…"
  },
  AvgCommunicate_84110_Option_10 = {
    Text = "Подожди, это всё безумнее и безумнее!"
  },
  AvgCommunicate_84110_Option_13 = {
    Text = "Почему ты не отказываешься?"
  },
  AvgCommunicate_84110_Option_2 = {
    Text = "Твои запасы снова забрала Винкель?"
  },
  AvgCommunicate_84110_Option_4 = {
    Text = "Опять из-за…"
  },
  AvgCommunicate_84110_Option_6 = {
    Text = "Заявка на снабжение одобрена…"
  },
  AvgCommunicate_94500_Content_1 = {
    Text = "Благодаря вашему содействию мы познакомились с господином Огиром, а он, в свою очередь, представил нам ещё больше друзей."
  },
  AvgCommunicate_94500_Content_10 = {
    Text = "Господин Огир также сказал, что рыцарская подготовка ещё сложнее и требовательнее. Похоже, как и написано в книгах, каждый рыцарь — поистине достойный восхищения человек."
  },
  AvgCommunicate_94500_Content_11 = {
    Text = "Действительно, Ожье самый усердный в тренировках среди всех пробуждённых!"
  },
  AvgCommunicate_94500_Content_12 = {
    Text = "Мы также заметили, что госпожа Эльва, будучи инструктором, несмотря на свою инвалидность, тренируется наравне с нами."
  },
  AvgCommunicate_94500_Content_13 = {
    Text = "Мы думали, что инструктор Эльва тоже рыцарь, но она сказала, что была военнослужащей. Не знаю, что это за профессия, но, должно быть, она столь же почётна, как и рыцарство."
  },
  AvgCommunicate_94500_Content_14 = {
    Text = "Военнослужащие — это те, кто сражается за свою страну. Их тоже можно считать своего рода рыцарями, но в сравнении со строгим моральным кодексом рыцарей, поступки военных не всегда олицетворяют справедливость."
  },
  AvgCommunicate_94500_Content_15 = {
    Text = "Эльва осознала это лишь после того, как покинула армию. Возможно, нынешняя жизнь приносит ей больше душевного покоя."
  },
  AvgCommunicate_94500_Content_16 = {
    Text = "Я понимаю. Вы хотите сказать, что рыцарство — это не Огромная Огромная сила, а дух справедливости. Такие праведные люди, как инструктор Эльва и вы, тоже обладают рыцарской душой."
  },
  AvgCommunicate_94500_Content_18 = {
    Text = "Хоть ты и говоришь красиво, но как же неловко от таких слов..."
  },
  AvgCommunicate_94500_Content_2 = {
    Text = "Это замечательно, я очень рад за вас."
  },
  AvgCommunicate_94500_Content_3 = {
    Text = "Мы уже встретились со многими пробуждёнными, и, как вы и говорили, большинство из них оказались добрыми людьми."
  },
  AvgCommunicate_94500_Content_4 = {
    Text = "Вспоминая, как я поначалу относился к окружающим с настороженностью и подозрением, мне становится стыдно."
  },
  AvgCommunicate_94500_Content_5 = {
    Text = "На самом деле это нормально, ведь некоторых людей и Правда стоит остерегаться..."
  },
  AvgCommunicate_94500_Content_6 = {
    Text = "Сейчас мы с Кастором вместе с господином Огиром посещаем тренировочные занятия инструктора Эльвы."
  },
  AvgCommunicate_94500_Content_7 = {
    Text = "Господин Огир великолепен в бою, однако, похоже, он сам не привык к похвалам. Какой скромный человек!"
  },
  AvgCommunicate_94500_Content_8 = {
    Text = "Ха-ха-ха, Огир просто очень легко смущается, общайтесь с ним как обычно, и всё будет хорошо."
  },
  AvgCommunicate_94500_Content_9 = {
    Text = "Вот как... Мы с Кастором никогда не проходили боевой подготовки в церкви, и такие тяжёлые тренировки даются нам нелегко. А господин Огир говорит, что занимается так каждый день — какая невероятная Огромная Огромная сила воли!"
  },
  AvgCommunicate_94500_Option_11 = {
    Text = "Действительно, Ожье самый усердный в тренировках среди всех пробуждённых!"
  },
  AvgCommunicate_94500_Option_14 = {
    Text = "Можно и так сказать..."
  },
  AvgCommunicate_94500_Option_2 = {
    Text = "Это замечательно, я очень рад за вас."
  },
  AvgCommunicate_94500_Option_5 = {
    Text = "На самом деле это нормально, ведь некоторых людей и Правда стоит остерегаться..."
  },
  AvgCommunicate_94500_Option_8 = {
    Text = "Огир просто очень легко смущается."
  },
  AvgCommunicate_94501_Content_1 = {
    Text = "Уважаемый господин, благодарю вас за жилище, которое вы любезно подготовили для меня и Кастора."
  },
  AvgCommunicate_94501_Content_10 = {
    Text = "Этот чудак Кастор так полюбил умываться, что делал это Часть 5 раз в день, но я остановила его, и теперь он ограничивается тремя разами."
  },
  AvgCommunicate_94501_Content_12 = {
    Text = "Если умываться слишком часто, кожа испортится!!"
  },
  AvgCommunicate_94501_Content_13 = {
    Text = "Но вы раньше никогда не пользовались такими вещами? Не ожидал, что Церковь Светоча окажется настолько скупой."
  },
  AvgCommunicate_94501_Content_14 = {
    Text = "Действительно не пользовались, но не потому, что церковь скупа, а потому что мы, будучи Святыми, всегда были обязаны сдерживать желания и усердно совершенствоваться."
  },
  AvgCommunicate_94501_Content_15 = {
    Text = "Мы почти никогда не соприкасались с подобными техническими изделиями, а наш распорядок дня и питание строго регламентировались."
  },
  AvgCommunicate_94501_Content_16 = {
    Text = "Хотя одежда и еда были достаточно роскошными, принимать пищу вне трёх установленных приёмов запрещалось, а после наступления времени подъёма мы обязаны были покинуть покои."
  },
  AvgCommunicate_94501_Content_17 = {
    Text = "В детстве я часто мечтала о том, чтобы не нужно было рано вставать и можно было целый день есть всё, что захочется."
  },
  AvgCommunicate_94501_Content_18 = {
    Text = "За последние дни я уже неоднократно видел девушку, проходящую по коридору с едой в руках после обеда. Похоже, жизнь, о которой я мечтал, здесь уже стала обыденностью."
  },
  AvgCommunicate_94501_Content_19 = {
    Text = "А, это, наверное, Мёрфи ходила за пирожными... Да уж, нелёгкая у вас жизнь."
  },
  AvgCommunicate_94501_Content_2 = {
    Text = "Кастор рассказал мне, что в комнату специально добавили ещё одну кровать, и я сразу поняла, что это ваших рук дело."
  },
  AvgCommunicate_94501_Content_20 = {
    Text = "Всё осталось в прошлом. Все ошибки и искажения останутся позади, и мы с новыми силами встанем на верный путь. Прошу вас быть тому свидетелем."
  },
  AvgCommunicate_94501_Content_21 = {
    Text = "Вы слишком любезны. Если что — обращайтесь ко мне. С вашим отношением к делу вы уже в разы меньше хлопот доставляете, чем некоторые другие Пробуждённые!"
  },
  AvgCommunicate_94501_Content_3 = {
    Text = "С детства в церкви мы привыкли жить вместе в одних покоях, и когда узнали, что здесь каждому полагается отдельная Комната, немного встревожились."
  },
  AvgCommunicate_94501_Content_4 = {
    Text = "Теперь, видя вашу заботу о каждой мелочи, я по-настоящему осознала, как права была госпожа Тайис, посоветовав нам обратиться к вам."
  },
  AvgCommunicate_94501_Content_5 = {
    Text = "Ха-ха, пустяки, пустяки. Вы уже привыкли к жизни здесь?"
  },
  AvgCommunicate_94501_Content_6 = {
    Text = "Благодаря вашей заботе всё прекрасно. Здешние покои хоть и тесны, словно комнатка прислуги, но обставлены всем необходимым, и после привыкания даже ощущается уют."
  },
  AvgCommunicate_94501_Content_7 = {
    Text = "А-ха-ха, Правда? Ну и хорошо, ну и хорошо…"
  },
  AvgCommunicate_94501_Content_8 = {
    Text = "Мы постепенно учимся жить без прислуги, не беспокойтесь о нас. Скорее, это то, о чём мы оба мечтали долгие годы."
  },
  AvgCommunicate_94501_Content_9 = {
    Text = "Особенно поразительна пенка для умывания — если использовать её по инструкции, она образует множество пузырьков, словно облака, а зубная паста имеет такой свежий вкус!"
  },
  AvgCommunicate_94501_Option_19 = {
    Text = "А, это, наверное, Мёрфи ходила за пирожными..."
  },
  AvgCommunicate_94501_Option_21 = {
    Text = "Вы слишком любезны."
  },
  AvgCommunicate_94501_Option_5 = {
    Text = "Пустяки, пустяки."
  },
  AvgCommunicate_94501_Option_7 = {
    Text = "А-ха-ха, Правда? Ну и хорошо, ну и хорошо…"
  },
  AvgCommunicate_94502_Content_1 = {
    Text = "Простите за Беспокойство, не могли бы вы нас немного представить..."
  },
  AvgCommunicate_94502_Content_10 = {
    Text = "О! Должно быть, это Ожье и Лотан."
  },
  AvgCommunicate_94502_Content_11 = {
    Text = "Ожье... Я запомню это имя. Тот юноша излучал прямоту и отвагу, мы с Кастором были совершенно очарованы. Мы хотели подойти, но они быстро прошли мимо и ушли."
  },
  AvgCommunicate_94502_Content_12 = {
    Text = "Вернувшись в комнату, мы ворочались без сна — так хотелось познакомиться с тем рыцарем, но мы не знали, как к нему обратиться. Поэтому пришли просить вас о представлении. Надеемся, вы найдёте время и поможете устроить нашу встречу."
  },
  AvgCommunicate_94502_Content_13 = {
    Text = "Я всё понял. Вообще-то вам не нужно так церемониться. Ожье очень отзывчивый человек — стоит вам только заговорить, и он с радостью подружится с вами."
  },
  AvgCommunicate_94502_Content_14 = {
    Text = "Настоящий рыцарь, как и подобает! Такое великодушие вызывает восхищение — он готов принять незнакомцев, которые к тому же когда-то служили врагу."
